type serverControlDatabaseAccessKind int

const (
	serverControlDatabaseRead serverControlDatabaseAccessKind = iota
	serverControlDatabaseWrite
	serverControlDatabaseReaderCount = 5
)

type serverControlDatabaseAccessRequest struct {
	ctx      context.Context
	reply    chan error
	purpose  string
	queuedAt time.Time
	run      func(*sql.DB) error
}

type serverControlDatabaseDispatcher struct {
	readRequests  chan serverControlDatabaseAccessRequest
	writeRequests chan serverControlDatabaseAccessRequest
	stop          chan struct{}
	workersDone   chan struct{}
	closeRequests chan chan struct{}
	stopped       chan struct{}
}

// The control database uses one write participant and five read participants.
// WAL keeps readers available while the writer owns the only write connection.
func startServerControlDatabaseDispatcher(databasePath string, debug bool) (*serverControlDatabaseDispatcher, error) {
	writerDatabase, err := openServerControlDatabaseHandle(databasePath, true)
	if err != nil {
		return nil, err
	}
	if err := hostingandsupport.Migrate(context.Background(), writerDatabase); err != nil {
		_ = writerDatabase.Close()
		return nil, err
	}

	readerDatabases := make([]*sql.DB, 0, serverControlDatabaseReaderCount)
	for range serverControlDatabaseReaderCount {
		readerDatabase, openErr := openServerControlDatabaseHandle(databasePath, false)
		if openErr != nil {
			_ = writerDatabase.Close()
			for _, openedDatabase := range readerDatabases {
				_ = openedDatabase.Close()
			}
			return nil, openErr
		}
		readerDatabases = append(readerDatabases, readerDatabase)
	}

	dispatcher := &serverControlDatabaseDispatcher{
		readRequests:  make(chan serverControlDatabaseAccessRequest, 256),
		writeRequests: make(chan serverControlDatabaseAccessRequest, 128),
		stop:          make(chan struct{}),
		workersDone:   make(chan struct{}, serverControlDatabaseReaderCount+1),
		closeRequests: make(chan chan struct{}),
		stopped:       make(chan struct{}),
	}
	go dispatcher.runWorker(writerDatabase, dispatcher.writeRequests, "writer", debug)
	for readerIndex, readerDatabase := range readerDatabases {
		go dispatcher.runWorker(readerDatabase, dispatcher.readRequests, fmt.Sprintf("reader-%d", readerIndex+1), debug)
	}
	go dispatcher.runCloser()
	return dispatcher, nil
}

func openServerControlDatabaseHandle(databasePath string, writer bool) (*sql.DB, error) {
	database, err := sql.Open("sqlite", "file:"+databasePath)
	if err != nil {
		return nil, err
	}
	database.SetMaxOpenConns(1)
	database.SetMaxIdleConns(1)
	database.SetConnMaxLifetime(0)
	pragmas := []string{
		"PRAGMA busy_timeout=5000",
		"PRAGMA foreign_keys=ON",
		"PRAGMA synchronous=NORMAL",
	}
	if writer {
		pragmas = append([]string{"PRAGMA journal_mode=WAL"}, pragmas...)
	}
	for _, pragma := range pragmas {
		if _, err := database.ExecContext(context.Background(), pragma); err != nil {
			_ = database.Close()
			return nil, err
		}
	}
	return database, nil
}

func (dispatcher *serverControlDatabaseDispatcher) runWorker(database *sql.DB, requests <-chan serverControlDatabaseAccessRequest, workerName string, debug bool) {
	defer func() {
		_ = database.Close()
		dispatcher.workersDone <- struct{}{}
	}()
	for {
		select {
		case <-dispatcher.stop:
			return
		case request := <-requests:
			select {
			case <-request.ctx.Done():
				select {
				case request.reply <- request.ctx.Err():
				default:
				}
				continue
			default:
			}
			queueDuration := time.Duration(0)
			if !request.queuedAt.IsZero() {
				queueDuration = time.Since(request.queuedAt)
			}
			if debug || queueDuration >= 5*time.Second {
				log.Printf("%sCONTROL DB%s worker=%s purpose=%s queue=%s", terminalCyan(), terminalReset(), workerName, request.purpose, queueDuration.String())
			}
			startedAt := time.Now()
			err := request.run(database)
			sessionDuration := time.Since(startedAt)
			if (debug && sessionDuration >= slowDatabaseOperationLogAfter) || sessionDuration >= 5*time.Second {
				log.Printf("%sCONTROL DB%s worker=%s purpose=%s operation=%s", terminalCyan(), terminalReset(), workerName, request.purpose, sessionDuration.String())
			}
			select {
			case request.reply <- err:
			case <-request.ctx.Done():
			case <-dispatcher.stop:
			}
		}
	}
}

func (dispatcher *serverControlDatabaseDispatcher) execute(ctx context.Context, kind serverControlDatabaseAccessKind, purpose string, run func(*sql.DB) error) error {
	if dispatcher == nil {
		return errors.New("server control database dispatcher is not running")
	}
	select {
	case <-dispatcher.stopped:
		return errors.New("server control database dispatcher stopped")
	default:
	}
	if ctx == nil {
		ctx = context.Background()
	}
	if run == nil {
		return errors.New("server control database operation is required")
	}
	request := serverControlDatabaseAccessRequest{
		ctx:      ctx,
		reply:    make(chan error, 1),
		purpose:  firstNonEmpty(strings.TrimSpace(purpose), "unspecified"),
		queuedAt: time.Now(),
		run:      run,
	}
	requests := dispatcher.readRequests
	if kind == serverControlDatabaseWrite {
		requests = dispatcher.writeRequests
	}
	select {
	case requests <- request:
	case <-ctx.Done():
		return ctx.Err()
	case <-dispatcher.stop:
		return errors.New("server control database dispatcher stopped")
	}
	select {
	case err := <-request.reply:
		return err
	case <-ctx.Done():
		return ctx.Err()
	case <-dispatcher.stop:
		return errors.New("server control database dispatcher stopped")
	}
}

func (dispatcher *serverControlDatabaseDispatcher) Close() {
	if dispatcher == nil {
		return
	}
	reply := make(chan struct{})
	select {
	case dispatcher.closeRequests <- reply:
	case <-dispatcher.stopped:
		return
	}
	select {
	case <-reply:
	case <-dispatcher.stopped:
	}
}

func (dispatcher *serverControlDatabaseDispatcher) runCloser() {
	reply := <-dispatcher.closeRequests
	close(dispatcher.stop)
	for range serverControlDatabaseReaderCount + 1 {
		<-dispatcher.workersDone
	}
	for {
		select {
		case <-dispatcher.readRequests:
		case <-dispatcher.writeRequests:
		default:
			close(dispatcher.stopped)
			close(reply)
			return
		}
	}
}

// siteFileDatabase owns one file-backed database handle from one goroutine.
// database/sql is still the portable execution layer, but all callers enter
// through channel queues so SQLite-style files do not receive parallel writes.
type siteFileDatabase struct {
	path          string
	rawDatabase   *sql.DB
	debug         bool
	generalQueue  chan siteDBOperation
	readQueue     chan siteDBOperation
	writeQueue    chan siteDBOperation
	closeRequests chan chan error
}

const slowHTTPRequestLogAfter = 2 * time.Second
const slowHTTPRequestRepeatAfter = 10 * time.Second
const slowDatabaseOperationLogAfter = time.Second
const slowDatabaseOperationRepeatAfter = 5 * time.Second

func contextWithDomain(ctx context.Context, domain string) context.Context {
	normalizedDomain := normalizeDomainName(domain)
	if normalizedDomain == "" {
		normalizedDomain = "localhost"
	}
	return context.WithValue(ctx, siteDomainContextKey{}, normalizedDomain)
}

func domainFromContext(ctx context.Context) string {
	if ctx == nil {
		return "localhost"
	}
	domain, ok := ctx.Value(siteDomainContextKey{}).(string)
	if !ok {
		return "localhost"
	}
	normalizedDomain := normalizeDomainName(domain)
	if normalizedDomain == "" {
		return "localhost"
	}
	return normalizedDomain
}

func contextWithSiteDatabaseCreation(ctx context.Context) context.Context {
	if ctx == nil {
		ctx = context.Background()
	}
	return context.WithValue(ctx, siteDatabaseCreateContextKey{}, true)
}

func siteDatabaseCreationAllowed(ctx context.Context) bool {
	if ctx == nil {
		return false
	}
	allowed, ok := ctx.Value(siteDatabaseCreateContextKey{}).(bool)
	return ok && allowed
}

func newSiteFileDatabase(databasePath string, rawDatabase *sql.DB, debug bool) *siteFileDatabase {
	rawDatabase.SetMaxOpenConns(1)
	rawDatabase.SetMaxIdleConns(1)
	rawDatabase.SetConnMaxLifetime(0)

	database := &siteFileDatabase{
		path:          databasePath,
		rawDatabase:   rawDatabase,
		debug:         debug,
		generalQueue:  make(chan siteDBOperation, 64),
		readQueue:     make(chan siteDBOperation, 256),
		writeQueue:    make(chan siteDBOperation, 128),
		closeRequests: make(chan chan error),
	}
	go database.run()
	log.Printf("%sDB WORKER%s connected path=%s", terminalGreen(), terminalReset(), databasePath)
	return database
}

func (db *siteFileDatabase) run() {
	queues := []chan siteDBOperation{db.writeQueue, db.readQueue, db.generalQueue}
	turn := 0

	for {
		select {
		case response := <-db.closeRequests:
			finishedOperations := db.finishQueuedOperations()
			response <- db.close(finishedOperations)
			return
		default:
		}

		operation, closeResponse, closing := db.nextOperation(queues, &turn)
		if closing {
			finishedOperations := db.finishQueuedOperations()
			closeResponse <- db.close(finishedOperations)
			return
		}

		db.completeOperation(operation)
	}
}

func (db *siteFileDatabase) completeOperation(operation siteDBOperation) {
	select {
	case <-operation.ctx.Done():
		if db.debug {
			db.logDatabaseOperationCanceled(operation)
		}
		operation.response <- siteDBOperationResponse{err: operation.ctx.Err()}
		return
	default:
	}

	startedAt := time.Now()
	response := operation.run(operation.ctx, db.rawDatabase)
	duration := time.Since(startedAt)
	if db.debug && (duration >= slowDatabaseOperationLogAfter || response.err != nil) {
		db.logDatabaseOperationFinished(operation, duration, response.err)
	}
	operation.response <- response
}

func (db *siteFileDatabase) finishQueuedOperations() int {
	finishedOperations := 0
	for {
		select {
		case operation := <-db.writeQueue:
			db.completeOperation(operation)
		case operation := <-db.readQueue:
			db.completeOperation(operation)
		case operation := <-db.generalQueue:
			db.completeOperation(operation)
		default:
			return finishedOperations
		}
		finishedOperations++
	}
}

func (db *siteFileDatabase) close(finishedOperations int) error {
	log.Printf("%sDB WORKER%s closing path=%s queued_operations_finished=%d", terminalYellow(), terminalReset(), db.path, finishedOperations)
	err := db.rawDatabase.Close()
	if err != nil {
		log.Printf("%sDB WORKER%s close failed path=%s err=%v", terminalRed(), terminalReset(), db.path, err)
		return err
	}
	log.Printf("%sDB WORKER%s disconnected path=%s", terminalGreen(), terminalReset(), db.path)
	return nil
}

func (db *siteFileDatabase) nextOperation(queues []chan siteDBOperation, turn *int) (siteDBOperation, chan error, bool) {
	for range queues {
		queue := queues[*turn%len(queues)]
		*turn = *turn + 1
		select {
		case operation := <-queue:
			return operation, nil, false
		default:
		}
	}

	select {
	case response := <-db.closeRequests:
		return siteDBOperation{}, response, true
	case operation := <-db.writeQueue:
		return operation, nil, false
	case operation := <-db.readQueue:
		return operation, nil, false
	case operation := <-db.generalQueue:
		return operation, nil, false
	}
}

func (db *siteFileDatabase) ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error) {
	arguments := append([]any(nil), args...)
	operation := siteDBOperation{
		query: query,
		args:  arguments,
		kind:  siteDBWorkloadForQuery(query),
		run: func(runCtx context.Context, rawDatabase *sql.DB) siteDBOperationResponse {
			result, err := rawDatabase.ExecContext(runCtx, query, arguments...)
			return siteDBOperationResponse{result: result, err: err}
		},
	}
	response := db.runOperation(ctx, operation)
	return response.result, response.err
}

func (db *siteFileDatabase) QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error) {
	arguments := append([]any(nil), args...)
	operation := siteDBOperation{
		query: query,
		args:  arguments,
		kind:  siteDBWorkloadForQuery(query),
		run: func(runCtx context.Context, rawDatabase *sql.DB) siteDBOperationResponse {
			rows, err := rawDatabase.QueryContext(runCtx, query, arguments...)
			return siteDBOperationResponse{rows: rows, err: err}
		},
	}
	response := db.runOperation(ctx, operation)
	return response.rows, response.err
}

func (db *siteFileDatabase) QueryRowContext(ctx context.Context, query string, args ...any) (*sql.Row, error) {
	arguments := append([]any(nil), args...)
	operation := siteDBOperation{
		query: query,
		args:  arguments,
		kind:  siteDBWorkloadForQuery(query),
		run: func(runCtx context.Context, rawDatabase *sql.DB) siteDBOperationResponse {
			row := rawDatabase.QueryRowContext(runCtx, query, arguments...)
			return siteDBOperationResponse{row: row}
		},
	}
	response := db.runOperation(ctx, operation)
	return response.row, response.err
}

func (db *siteFileDatabase) Migrate(ctx context.Context, domain string, migrate siteDBMigrator) error {
	if migrate == nil {
		return nil
	}
	operation := siteDBOperation{
		kind: siteDBWorkloadGeneral,
		run: func(runCtx context.Context, rawDatabase *sql.DB) siteDBOperationResponse {
			return siteDBOperationResponse{err: migrate(runCtx, rawDatabase, domain)}
		},
	}
	return db.runOperation(ctx, operation).err
}

func (db *siteFileDatabase) Close() error {
	response := make(chan error, 1)
	db.closeRequests <- response
	return <-response
}

func (db *siteFileDatabase) runOperation(ctx context.Context, operation siteDBOperation) siteDBOperationResponse {
	if ctx == nil {
		ctx = context.Background()
	}
	operation.ctx = ctx
	operation.response = make(chan siteDBOperationResponse, 1)

	queue := db.queueFor(operation.kind)
	if !db.debug {
		select {
		case <-ctx.Done():
			return siteDBOperationResponse{err: ctx.Err()}
		case queue <- operation:
		}
		select {
		case response := <-operation.response:
			return response
		case <-ctx.Done():
			return siteDBOperationResponse{err: ctx.Err()}
		}
	}

	queueStartedAt := time.Now()
	queueTimer := time.NewTimer(slowDatabaseOperationLogAfter)
	defer queueTimer.Stop()
	for queued := false; !queued; {
		select {
		case <-ctx.Done():
			return siteDBOperationResponse{err: ctx.Err()}
		case queue <- operation:
			queued = true
		case <-queueTimer.C:
			db.logDatabaseOperationWaiting("queue", operation, time.Since(queueStartedAt))
			queueTimer.Reset(slowDatabaseOperationRepeatAfter)
		}
	}

	runStartedAt := time.Now()
	waitTimer := time.NewTimer(slowDatabaseOperationLogAfter)
	defer waitTimer.Stop()
	for {
		select {
		case response := <-operation.response:
			waitDuration := time.Since(runStartedAt)
			if waitDuration >= slowDatabaseOperationLogAfter || response.err != nil {
				db.logDatabaseOperationResponse(operation, time.Since(queueStartedAt), response.err)
			}
			return response
		case <-ctx.Done():
			db.logDatabaseOperationWaiting("context-canceled", operation, time.Since(queueStartedAt))
			return siteDBOperationResponse{err: ctx.Err()}
		case <-waitTimer.C:
			db.logDatabaseOperationWaiting("response", operation, time.Since(runStartedAt))
			waitTimer.Reset(slowDatabaseOperationRepeatAfter)
		}
	}
}

func (db *siteFileDatabase) queueFor(kind siteDBWorkloadKind) chan siteDBOperation {
	switch kind {
	case siteDBWorkloadRead:
		return db.readQueue
	case siteDBWorkloadWrite:
		return db.writeQueue
	default:
		return db.generalQueue
	}
}

func siteDBWorkloadForQuery(query string) siteDBWorkloadKind {
	statement := strings.ToUpper(strings.TrimSpace(query))
	if statement == "" {
		return siteDBWorkloadGeneral
	}
	switch {
	case strings.HasPrefix(statement, "SELECT"), strings.HasPrefix(statement, "WITH"):
		return siteDBWorkloadRead
	case strings.HasPrefix(statement, "INSERT"), strings.HasPrefix(statement, "UPDATE"), strings.HasPrefix(statement, "DELETE"), strings.HasPrefix(statement, "CREATE"), strings.HasPrefix(statement, "ALTER"), strings.HasPrefix(statement, "DROP"), strings.HasPrefix(statement, "REPLACE"):
		return siteDBWorkloadWrite
	default:
		return siteDBWorkloadGeneral
	}
}

func siteDBWorkloadName(kind siteDBWorkloadKind) string {
	switch kind {
	case siteDBWorkloadRead:
		return "read"
	case siteDBWorkloadWrite:
		return "write"
	default:
		return "general"
	}
}

func (db *siteFileDatabase) logDatabaseOperationWaiting(stage string, operation siteDBOperation, duration time.Duration) {
	log.Printf("%sDB WORKER%s waiting stage=%s path=%s domain=%s kind=%s duration=%s queues=write:%d,read:%d,general:%d",
		terminalYellow(), terminalReset(), diagnosticlog.SafeLogValue(stage), diagnosticlog.SafeLogValue(db.path),
		diagnosticlog.SafeLogValue(domainFromContext(operation.ctx)), siteDBWorkloadName(operation.kind), duration.String(),
		len(db.writeQueue), len(db.readQueue), len(db.generalQueue))
}

func (db *siteFileDatabase) logDatabaseOperationFinished(operation siteDBOperation, duration time.Duration, err error) {
	status := "ok"
	logColor := terminalCyan()
	if err != nil {
		status = diagnosticlog.SafeLogValue(err.Error())
		logColor = terminalRed()
	}
	log.Printf("%sDB WORKER%s operation finished path=%s domain=%s kind=%s duration=%s status=%q",
		logColor, terminalReset(), diagnosticlog.SafeLogValue(db.path), diagnosticlog.SafeLogValue(domainFromContext(operation.ctx)),
		siteDBWorkloadName(operation.kind), duration.String(), status)
}

func (db *siteFileDatabase) logDatabaseOperationResponse(operation siteDBOperation, duration time.Duration, err error) {
	status := "ok"
	logColor := terminalCyan()
	if err != nil {
		status = diagnosticlog.SafeLogValue(err.Error())
		logColor = terminalRed()
	}
	log.Printf("%sDB WORKER%s response delivered path=%s domain=%s kind=%s duration=%s status=%q",
		logColor, terminalReset(), diagnosticlog.SafeLogValue(db.path), diagnosticlog.SafeLogValue(domainFromContext(operation.ctx)),
		siteDBWorkloadName(operation.kind), duration.String(), status)
}

func (db *siteFileDatabase) logDatabaseOperationCanceled(operation siteDBOperation) {
	status := "-"
	if operation.ctx.Err() != nil {
		status = diagnosticlog.SafeLogValue(operation.ctx.Err().Error())
	}
	log.Printf("%sDB WORKER%s operation skipped path=%s domain=%s kind=%s status=%q",
		terminalYellow(), terminalReset(), diagnosticlog.SafeLogValue(db.path), diagnosticlog.SafeLogValue(domainFromContext(operation.ctx)),
		siteDBWorkloadName(operation.kind), status)
}

// perSiteDBRouter resolves a separate sqlite file per domain and keeps the map
// ownership in a single goroutine so we do not coordinate it with mutexes.
type perSiteDBRouter struct {
	fallbackDomain          string
	debug                   bool
	requests                chan siteDBRequest
	preloadRequests         chan siteDBPreloadRequest
	domainListRequests      chan siteDBDomainListRequest
	forgetDomainRequests    chan siteDBForgetDomainRequest
	migrationStatusRequests chan siteDBMigrationStatusRequest
	migrationEvents         chan siteDBMigrationEvent
	closeRequests           chan chan error
	noopDatabase            *sql.DB
}

func newPerSiteDBRouter(siteDatabaseRootDir string, fallbackDomain string, migrate siteDBMigrator, debug bool) *perSiteDBRouter {
	router := &perSiteDBRouter{
		fallbackDomain:          fallbackDomain,
		debug:                   debug,
		requests:                make(chan siteDBRequest),
		preloadRequests:         make(chan siteDBPreloadRequest),
		domainListRequests:      make(chan siteDBDomainListRequest),
		forgetDomainRequests:    make(chan siteDBForgetDomainRequest),
		migrationStatusRequests: make(chan siteDBMigrationStatusRequest),
		migrationEvents:         make(chan siteDBMigrationEvent, 256),
		closeRequests:           make(chan chan error),
		noopDatabase:            mustOpenNoopSQLite(),
	}
	go router.run(siteDatabaseRootDir, migrate)
	return router
}

func (r *perSiteDBRouter) run(siteDatabaseRootDir string, migrate siteDBMigrator) {
	databasesByDomain := make(map[string]*siteFileDatabase)
	primaryDomainsByAlias := make(map[string]string)
	startupMigrationFinished := false
	migratedDomains := make(map[string]bool)
	degradedDomains := make(map[string]error)
	go r.scanStartupMigrations(context.Background(), siteDatabaseRootDir, migrate)
	for {
		select {
		case event := <-r.migrationEvents:
			switch event.kind {
			case "applied":
				migratedDomains[event.domain] = true
				delete(degradedDomains, event.domain)
				log.Printf("%sDB MIGRATION%s applied path=%s domain=%s from=%d to=%d", terminalGreen(), terminalReset(), event.path, event.domain, event.previousVersion, event.currentVersion)
			case "skipped":
				migratedDomains[event.domain] = true
				if r.debug {
					log.Printf("%sDB MIGRATION%s skipped path=%s domain=%s version=%d", terminalCyan(), terminalReset(), event.path, event.domain, event.currentVersion)
				}
			case "failed":
				degradedDomains[event.domain] = event.err
				log.Printf("%sDB MIGRATION%s failed path=%s domain=%s step=%s err=%v", terminalRed(), terminalReset(), event.path, event.domain, diagnosticlog.SafeLogValue(event.step), event.err)
			case "ignored":
				if r.debug {
					log.Printf("%sDB MIGRATION%s ignored unregistered path=%s domain=%s", terminalCyan(), terminalReset(), event.path, event.domain)
				}
			case "summary":
				startupMigrationFinished = true
				log.Printf("%sDB MIGRATION%s startup summary total=%d applied=%d skipped=%d failed=%d", terminalCyan(), terminalReset(), event.total, event.applied, event.skipped, event.failed)
			}
		case statusRequest := <-r.migrationStatusRequests:
			domain := normalizeDomainName(statusRequest.domain)
			if domain == "" {
				domain = r.fallbackDomain
			}
			status := siteDBMigrationStatus{startupFinished: startupMigrationFinished}
			if err := degradedDomains[domain]; err != nil {
				status.degraded = true
				status.err = err
			}
			statusRequest.response <- status
		case preloadRequest := <-r.preloadRequests:
			if !startupMigrationFinished {
				preloadRequest.response <- siteDBPreloadResponse{err: errSiteMigrationsStarting}
				continue
			}
			response := r.preloadMigratedDatabases(siteDatabaseRootDir, databasesByDomain, migratedDomains, degradedDomains, migrate)
			preloadRequest.response <- response
		case domainListRequest := <-r.domainListRequests:
			domainList := make([]string, 0, len(migratedDomains))
			for domain := range migratedDomains {
				if degradedDomains[domain] == nil {
					domainList = append(domainList, domain)
				}
			}
			sort.Strings(domainList)
			domainListRequest.response <- domainList
		case forgetRequest := <-r.forgetDomainRequests:
			domain := normalizeDomainName(forgetRequest.domain)
			if domain == "" {
				domain = r.fallbackDomain
			}
			var closeErr error
			if database := databasesByDomain[domain]; database != nil {
				closeErr = database.Close()
			}
			delete(databasesByDomain, domain)
			delete(migratedDomains, domain)
			delete(degradedDomains, domain)
			for aliasDomain, primaryDomain := range primaryDomainsByAlias {
				if aliasDomain == domain || primaryDomain == domain {
					delete(primaryDomainsByAlias, aliasDomain)
				}
			}
			forgetRequest.response <- closeErr
		case request := <-r.requests:
			startedAt := time.Now()
			domain := normalizeDomainName(request.domain)
			if domain == "" {
				domain = r.fallbackDomain
			}
			if !startupMigrationFinished {
				request.response <- siteDBResponse{err: errSiteMigrationsStarting}
				continue
			}
			if err := degradedDomains[domain]; err != nil {
				request.response <- siteDBResponse{err: siteDatabaseDegradedError{domain: domain, err: err}}
				continue
			}
			databaseDomain := domain
			aliasDomain := ""
			if primaryDomain := primaryDomainsByAlias[domain]; primaryDomain != "" {
				database, err := r.databaseForDomain(siteDatabaseRootDir, databasesByDomain, migratedDomains, degradedDomains, primaryDomain, request.createIfMissing, migrate)
				if err != nil {
					request.response <- siteDBResponse{err: err}
					continue
				}
				if activePrimaryDomainForAlias(database, domain) == primaryDomain {
					r.logRouterResolved(domain, primaryDomain, domain, time.Since(startedAt), nil)
					request.response <- siteDBResponse{db: database}
					continue
				}
				delete(primaryDomainsByAlias, domain)
			}
			if primaryDomain := findActivePrimaryDomainForAlias(siteDatabaseRootDir, databasesByDomain, domain); primaryDomain != "" {
				primaryDomainsByAlias[domain] = primaryDomain
				databaseDomain = primaryDomain
				aliasDomain = domain
			}
			if err := degradedDomains[databaseDomain]; err != nil {
				request.response <- siteDBResponse{err: siteDatabaseDegradedError{domain: databaseDomain, err: err}}
				continue
			}
			database, err := r.databaseForDomain(siteDatabaseRootDir, databasesByDomain, migratedDomains, degradedDomains, databaseDomain, request.createIfMissing, migrate)
			if err != nil {
				r.logRouterResolved(domain, databaseDomain, aliasDomain, time.Since(startedAt), err)
				request.response <- siteDBResponse{err: err}
				continue
			}
			r.logRouterResolved(domain, databaseDomain, aliasDomain, time.Since(startedAt), nil)
			request.response <- siteDBResponse{db: database}
		case closeResponse := <-r.closeRequests:
			var closeErr error
			for _, database := range databasesByDomain {
				if err := database.Close(); err != nil && closeErr == nil {
					closeErr = err
				}
			}
			_ = routerCloseNoop(r.noopDatabase)
			closeResponse <- closeErr
			return
		}
	}
}

func (r *perSiteDBRouter) preloadMigratedDatabases(siteDatabaseRootDir string, databasesByDomain map[string]*siteFileDatabase, migratedDomains map[string]bool, degradedDomains map[string]error, migrate siteDBMigrator) siteDBPreloadResponse {
	domainList := make([]string, 0, len(migratedDomains))
	for domain := range migratedDomains {
		if _, degraded := degradedDomains[domain]; degraded {
			continue
		}
		domainList = append(domainList, domain)
	}
	sort.Strings(domainList)
	response := siteDBPreloadResponse{total: len(domainList)}
	for _, domain := range domainList {
		_, err := r.databaseForDomain(siteDatabaseRootDir, databasesByDomain, migratedDomains, degradedDomains, domain, false, migrate)
		if err != nil {
			response.failed++
			if response.err == nil {
				response.err = err
			}
			log.Printf("%sPRELOAD%s site database failed domain=%s err=%v", terminalRed(), terminalReset(), domain, err)
			continue
		}
		response.opened++
	}
	log.Printf("%sPRELOAD%s site databases total=%d opened=%d failed=%d", terminalGreen(), terminalReset(), response.total, response.opened, response.failed)
	return response
}

func (r *perSiteDBRouter) scanStartupMigrations(ctx context.Context, siteDatabaseRootDir string, migrate siteDBMigrator) {
	databaseEntries, readErr := os.ReadDir(siteDatabaseRootDir)
	if readErr != nil {
		if !errors.Is(readErr, os.ErrNotExist) {
			r.migrationEvents <- siteDBMigrationEvent{kind: "failed", domain: r.fallbackDomain, path: siteDatabaseRootDir, step: "read database directory", err: readErr}
			r.migrationEvents <- siteDBMigrationEvent{kind: "summary", total: 0, failed: 1}
			return
		}
		r.migrationEvents <- siteDBMigrationEvent{kind: "summary"}
		return
	}

	databaseFiles := []string{}
	for _, databaseEntry := range databaseEntries {
		if databaseEntry.IsDir() || !strings.HasSuffix(strings.ToLower(databaseEntry.Name()), ".db") {
			continue
		}
		databaseFiles = append(databaseFiles, databaseEntry.Name())
	}
	if len(databaseFiles) == 0 {
		r.migrationEvents <- siteDBMigrationEvent{kind: "summary"}
		return
	}

	results := make(chan siteDBMigrationEvent, len(databaseFiles))
	for _, databaseFile := range databaseFiles {
		databasePath := filepath.Join(siteDatabaseRootDir, databaseFile)
		databaseDomain := normalizeDomainName(strings.TrimSuffix(databaseFile, filepath.Ext(databaseFile)))
		if databaseDomain == "" {
			databaseDomain = r.fallbackDomain
		}
		go r.migrateStartupDatabase(ctx, databasePath, databaseDomain, migrate, results)
	}

	summary := siteDBMigrationEvent{kind: "summary"}
	for range databaseFiles {
		result := <-results
		switch result.kind {
		case "applied":
			summary.total++
			summary.applied++
		case "skipped":
			summary.total++
			summary.skipped++
		case "failed":
			summary.total++
			summary.failed++
		}
		r.migrationEvents <- result
	}
	r.migrationEvents <- summary
}

func (r *perSiteDBRouter) migrateStartupDatabase(ctx context.Context, databasePath, databaseDomain string, migrate siteDBMigrator, results chan siteDBMigrationEvent) {
	migrationCtx, cancel := context.WithTimeout(ctx, siteDatabaseStartupMigrationTimeout)
	defer cancel()
	database, err := sql.Open("sqlite", "file:"+databasePath)
	if err != nil {
		results <- siteDBMigrationEvent{kind: "failed", domain: databaseDomain, path: databasePath, step: "open database", err: err}
		return
	}
	defer database.Close()
	database.SetMaxOpenConns(1)
	database.SetMaxIdleConns(1)

	if !siteDatabaseHasRegisteredAdmin(migrationCtx, database) {
		results <- siteDBMigrationEvent{kind: "ignored", domain: databaseDomain, path: databasePath}
		return
	}

	version, versionErr := sqliteUserVersion(migrationCtx, database)
	if versionErr != nil {
		results <- siteDBMigrationEvent{kind: "failed", domain: databaseDomain, path: databasePath, step: "read schema version", err: versionErr}
		return
	}
	schemaComplete, schemaErr := siteDatabaseSchemaComplete(migrationCtx, database)
	if schemaErr != nil {
		results <- siteDBMigrationEvent{kind: "failed", domain: databaseDomain, path: databasePath, step: "verify schema", err: schemaErr}
		return
	}
	if version >= currentSiteDatabaseSchemaVersion && schemaComplete {
		results <- siteDBMigrationEvent{kind: "skipped", domain: databaseDomain, path: databasePath, previousVersion: version, currentVersion: version}
		return
	}
	if migrate == nil {
		results <- siteDBMigrationEvent{kind: "failed", domain: databaseDomain, path: databasePath, step: "migration handler", err: errors.New("migration handler is not configured")}
		return
	}
	if migrateErr := migrate(migrationCtx, database, databaseDomain); migrateErr != nil {
		results <- siteDBMigrationEvent{kind: "failed", domain: databaseDomain, path: databasePath, step: siteMigrationFailureStep(migrateErr), err: migrateErr}
		return
	}
	nextVersion, nextVersionErr := sqliteUserVersion(migrationCtx, database)
	if nextVersionErr != nil {
		results <- siteDBMigrationEvent{kind: "failed", domain: databaseDomain, path: databasePath, step: "read schema version after migration", err: nextVersionErr}
		return
	}
	results <- siteDBMigrationEvent{kind: "applied", domain: databaseDomain, path: databasePath, previousVersion: version, currentVersion: nextVersion}
}

func (r *perSiteDBRouter) databaseForDomain(siteDatabaseRootDir string, databasesByDomain map[string]*siteFileDatabase, migratedDomains map[string]bool, degradedDomains map[string]error, domain string, createIfMissing bool, migrate siteDBMigrator) (*siteFileDatabase, error) {
	databaseDomain := normalizeDomainName(domain)
	if databaseDomain == "" {
		databaseDomain = r.fallbackDomain
	}
	if err := degradedDomains[databaseDomain]; err != nil {
		return nil, siteDatabaseDegradedError{domain: databaseDomain, err: err}
	}
	database := databasesByDomain[databaseDomain]
	if database != nil {
		return database, nil
	}
	databasePath := filepath.Join(siteDatabaseRootDir, domainStorageName(databaseDomain)+".db")
	if err := ensureParentDir(databasePath); err != nil {
		return nil, err
	}
	if !createIfMissing {
		if _, statErr := os.Stat(databasePath); statErr != nil {
			if errors.Is(statErr, os.ErrNotExist) {
				return nil, errSiteDatabaseMissing
			}
			return nil, statErr
		}
	}
	nextDatabase, err := sql.Open("sqlite", "file:"+databasePath)
	if err != nil {
		return nil, err
	}
	currentVersion, versionErr := sqliteUserVersion(context.Background(), nextDatabase)
	if versionErr != nil {
		_ = nextDatabase.Close()
		degradedDomains[databaseDomain] = versionErr
		log.Printf("%sDB MIGRATION%s failed path=%s domain=%s step=%s err=%v", terminalRed(), terminalReset(), databasePath, databaseDomain, "read schema version", versionErr)
		return nil, siteDatabaseDegradedError{domain: databaseDomain, err: versionErr}
	}
	schemaComplete, schemaErr := siteDatabaseSchemaComplete(context.Background(), nextDatabase)
	if schemaErr != nil {
		_ = nextDatabase.Close()
		degradedDomains[databaseDomain] = schemaErr
		log.Printf("%sDB MIGRATION%s failed path=%s domain=%s step=%s err=%v", terminalRed(), terminalReset(), databasePath, databaseDomain, "verify schema", schemaErr)
		return nil, siteDatabaseDegradedError{domain: databaseDomain, err: schemaErr}
	}
	siteDatabase := newSiteFileDatabase(databasePath, nextDatabase, r.debug)
	if !migratedDomains[databaseDomain] {
		if currentVersion < currentSiteDatabaseSchemaVersion || !schemaComplete {
			if migrateErr := siteDatabase.Migrate(context.Background(), databaseDomain, migrate); migrateErr != nil {
				degradedDomains[databaseDomain] = migrateErr
				log.Printf("%sDB MIGRATION%s failed path=%s domain=%s step=%s err=%v", terminalRed(), terminalReset(), databasePath, databaseDomain, siteMigrationFailureStep(migrateErr), migrateErr)
				_ = siteDatabase.Close()
				return nil, siteDatabaseDegradedError{domain: databaseDomain, err: migrateErr}
			}
			log.Printf("%sDB MIGRATION%s applied path=%s domain=%s reason=runtime from=%d to=%d", terminalGreen(), terminalReset(), databasePath, databaseDomain, currentVersion, currentSiteDatabaseSchemaVersion)
		} else if r.debug {
			log.Printf("%sDB MIGRATION%s skipped path=%s domain=%s reason=runtime version=%d", terminalCyan(), terminalReset(), databasePath, databaseDomain, currentVersion)
		}
		migratedDomains[databaseDomain] = true
	} else if r.debug {
		log.Printf("%sDB MIGRATION%s skipped path=%s domain=%s reason=startup-ready", terminalCyan(), terminalReset(), databasePath, databaseDomain)
	}
	databasesByDomain[databaseDomain] = siteDatabase
	return siteDatabase, nil
}

func findActivePrimaryDomainForAlias(siteDatabaseRootDir string, databasesByDomain map[string]*siteFileDatabase, aliasDomain string) string {
	aliasDomain = normalizeDomainName(aliasDomain)
	if aliasDomain == "" {
		return ""
	}
	for _, database := range databasesByDomain {
		if primaryDomain := activePrimaryDomainForAlias(database, aliasDomain); primaryDomain != "" {
			return primaryDomain
		}
	}
	databaseEntries, err := os.ReadDir(siteDatabaseRootDir)
	if err != nil {
		return ""
	}
	for _, databaseEntry := range databaseEntries {
		if databaseEntry.IsDir() || !strings.HasSuffix(databaseEntry.Name(), ".db") {
			continue
		}
		databasePath := filepath.Join(siteDatabaseRootDir, databaseEntry.Name())
		if siteDatabasePathAlreadyOpen(databasesByDomain, databasePath) {
			continue
		}
		database, err := sql.Open("sqlite", "file:"+databasePath)
		if err != nil {
			continue
		}
		database.SetMaxOpenConns(1)
		database.SetMaxIdleConns(1)
		primaryDomain := activePrimaryDomainForAliasRaw(database, aliasDomain)
		_ = database.Close()
		if primaryDomain != "" {
			return primaryDomain
		}
	}
	return ""
}

func siteDatabasePathAlreadyOpen(databasesByDomain map[string]*siteFileDatabase, databasePath string) bool {
	for _, database := range databasesByDomain {
		if database != nil && database.path == databasePath {
			return true
		}
	}
	return false
}

func activePrimaryDomainForAlias(database *siteFileDatabase, aliasDomain string) string {
	if database == nil {
		return ""
	}
	row, err := database.QueryRowContext(context.Background(), `SELECT primary_domain FROM domain_aliases WHERE alias_domain=? AND is_verified=1 AND dns_a_ok=1 LIMIT 1`, aliasDomain)
	if err != nil {
		return ""
	}
	return scanActivePrimaryDomainForAlias(row, aliasDomain)
}

func activePrimaryDomainForAliasRaw(database *sql.DB, aliasDomain string) string {
	if database == nil {
		return ""
	}
	row := database.QueryRowContext(context.Background(), `SELECT primary_domain FROM domain_aliases WHERE alias_domain=? AND is_verified=1 AND dns_a_ok=1 LIMIT 1`, aliasDomain)
	return scanActivePrimaryDomainForAlias(row, aliasDomain)
}

func scanActivePrimaryDomainForAlias(row *sql.Row, aliasDomain string) string {
	var rawPrimaryDomain string
	err := row.Scan(&rawPrimaryDomain)
	if err != nil {
		return ""
	}
	primaryDomain := normalizeDomainName(rawPrimaryDomain)
	if primaryDomain == "" || primaryDomain == aliasDomain {
		return ""
	}
	return primaryDomain
}

func siteDatabaseHasRegisteredAdmin(ctx context.Context, database *sql.DB) bool {
	if database == nil {
		return false
	}
	var adminCount int
	err := database.QueryRowContext(ctx, `SELECT COUNT(1) FROM users WHERE is_admin=1`).Scan(&adminCount)
	return err == nil && adminCount > 0
}

func (r *perSiteDBRouter) Close() error {
	closeResponse := make(chan error, 1)
	r.closeRequests <- closeResponse
	return <-closeResponse
}

func (r *perSiteDBRouter) MigrationStatus(ctx context.Context, domain string) siteDBMigrationStatus {
	if ctx == nil {
		ctx = context.Background()
	}
	response := make(chan siteDBMigrationStatus, 1)
	request := siteDBMigrationStatusRequest{domain: domain, response: response}
	select {
	case r.migrationStatusRequests <- request:
	case <-ctx.Done():
		return siteDBMigrationStatus{err: ctx.Err()}
	}
	select {
	case status := <-response:
		return status
	case <-ctx.Done():
		return siteDBMigrationStatus{err: ctx.Err()}
	}
}

func (r *perSiteDBRouter) Preload(ctx context.Context) siteDBPreloadResponse {
	if ctx == nil {
		ctx = context.Background()
	}
	response := make(chan siteDBPreloadResponse, 1)
	request := siteDBPreloadRequest{response: response}
	select {
	case r.preloadRequests <- request:
	case <-ctx.Done():
		return siteDBPreloadResponse{err: ctx.Err()}
	}
	select {
	case preloadResponse := <-response:
		return preloadResponse
	case <-ctx.Done():
		return siteDBPreloadResponse{err: ctx.Err()}
	}
}

func (r *perSiteDBRouter) Domains(ctx context.Context) []string {
	if ctx == nil {
		ctx = context.Background()
	}
	response := make(chan []string, 1)
	select {
	case r.domainListRequests <- siteDBDomainListRequest{response: response}:
	case <-ctx.Done():
		return nil
	}
	select {
	case domains := <-response:
		return domains
	case <-ctx.Done():
		return nil
	}
}

func (r *perSiteDBRouter) ForgetDomain(ctx context.Context, domain string) error {
	if ctx == nil {
		ctx = context.Background()
	}
	response := make(chan error, 1)
	request := siteDBForgetDomainRequest{domain: domain, response: response}
	select {
	case r.forgetDomainRequests <- request:
	case <-ctx.Done():
		return ctx.Err()
	}
	select {
	case err := <-response:
		return err
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (r *perSiteDBRouter) ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error) {
	database, err := r.databaseForContext(ctx)
	if err != nil {
		return nil, err
	}
	return database.ExecContext(ctx, query, args...)
}

func (r *perSiteDBRouter) QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error) {
	database, err := r.databaseForContext(ctx)
	if err != nil {
		return nil, err
	}
	return database.QueryContext(ctx, query, args...)
}

func (r *perSiteDBRouter) QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row {
	database, err := r.databaseForContext(ctx)
	if err != nil {
		if r.debug {
			log.Printf("%sDB ROUTER%s query-row fallback domain=%s err=%s",
				terminalYellow(), terminalReset(), diagnosticlog.SafeLogValue(domainFromContext(ctx)), diagnosticlog.SafeLogValue(err.Error()))
		}
		return r.noopDatabase.QueryRowContext(ctx, `SELECT 1 WHERE 0`)
	}
	row, err := database.QueryRowContext(ctx, query, args...)
	if err != nil {
		if r.debug {
			log.Printf("%sDB ROUTER%s query-row fallback domain=%s path=%s err=%s",
				terminalYellow(), terminalReset(), diagnosticlog.SafeLogValue(domainFromContext(ctx)),
				diagnosticlog.SafeLogValue(database.path), diagnosticlog.SafeLogValue(err.Error()))
		}
		return r.noopDatabase.QueryRowContext(ctx, `SELECT 1 WHERE 0`)
	}
	return row
}

func (r *perSiteDBRouter) databaseForContext(ctx context.Context) (*siteFileDatabase, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	domain := domainFromContext(ctx)
	if domain == "" {
		domain = r.fallbackDomain
	}
	response := make(chan siteDBResponse, 1)
	request := siteDBRequest{domain: domain, createIfMissing: siteDatabaseCreationAllowed(ctx), response: response}
	if !r.debug {
		select {
		case r.requests <- request:
		case <-ctx.Done():
			return nil, ctx.Err()
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case next := <-response:
			return next.db, next.err
		}
	}

	sendStartedAt := time.Now()
	sendTimer := time.NewTimer(slowDatabaseOperationLogAfter)
	defer sendTimer.Stop()
	for sent := false; !sent; {
		select {
		case r.requests <- request:
			sent = true
		case <-ctx.Done():
			log.Printf("%sDB ROUTER%s request canceled before send domain=%s duration=%s err=%s",
				terminalYellow(), terminalReset(), diagnosticlog.SafeLogValue(domain), time.Since(sendStartedAt).String(),
				diagnosticlog.SafeLogValue(ctx.Err().Error()))
			return nil, ctx.Err()
		case <-sendTimer.C:
			log.Printf("%sDB ROUTER%s waiting stage=send domain=%s duration=%s",
				terminalYellow(), terminalReset(), diagnosticlog.SafeLogValue(domain), time.Since(sendStartedAt).String())
			sendTimer.Reset(slowDatabaseOperationRepeatAfter)
		}
	}

	waitStartedAt := time.Now()
	waitTimer := time.NewTimer(slowDatabaseOperationLogAfter)
	defer waitTimer.Stop()
	for {
		select {
		case <-ctx.Done():
			log.Printf("%sDB ROUTER%s request canceled while waiting domain=%s duration=%s err=%s",
				terminalYellow(), terminalReset(), diagnosticlog.SafeLogValue(domain), time.Since(waitStartedAt).String(),
				diagnosticlog.SafeLogValue(ctx.Err().Error()))
			return nil, ctx.Err()
		case next := <-response:
			return next.db, next.err
		case <-waitTimer.C:
			log.Printf("%sDB ROUTER%s waiting stage=response domain=%s duration=%s",
				terminalYellow(), terminalReset(), diagnosticlog.SafeLogValue(domain), time.Since(waitStartedAt).String())
			waitTimer.Reset(slowDatabaseOperationRepeatAfter)
		}
	}
}

func (r *perSiteDBRouter) logRouterResolved(requestDomain, databaseDomain, aliasDomain string, duration time.Duration, err error) {
	if !r.debug {
		return
	}
	if duration < 200*time.Millisecond && err == nil {
		return
	}
	status := "ok"
	logColor := terminalCyan()
	if err != nil {
		status = err.Error()
		logColor = terminalRed()
	}
	log.Printf("%sDB ROUTER%s resolved request_domain=%s database_domain=%s alias_domain=%s duration=%s status=%q",
		logColor, terminalReset(), requestDomain, databaseDomain, diagnosticlog.SafeLogValue(aliasDomain), duration.String(), status)
}

func mustOpenNoopSQLite() *sql.DB {
	noopDatabase, err := sql.Open("sqlite", "file::memory:?cache=shared")
	if err == nil {
		return noopDatabase
	}
	noopDatabase, err = sql.Open("sqlite", ":memory:")
	if err == nil {
		return noopDatabase
	}
	log.Fatalf("failed to open noop sqlite database: %v", err)
	return nil
}

func routerCloseNoop(noopDatabase *sql.DB) error {
	if noopDatabase == nil {
		return nil
	}
	return noopDatabase.Close()
}

