func (a *App) defaultHTMLForNewPage(ctx context.Context, domain, pagePath string) string {
	ancestorPath := parentPagePath(pagePath)
	for ancestorPath != "" {
		ancestorPage, err := a.findPage(ctx, domain, ancestorPath)
		if err == nil && ancestorPage.Path != "" && strings.TrimSpace(ancestorPage.HTML) != "" {
			return ancestorPage.HTML
		}
		ancestorPath = parentPagePath(ancestorPath)
	}
	return "<h1>New page</h1>"
}

func parentPagePath(pagePath string) string {
	if pagePath == "" || pagePath == "/" {
		return ""
	}
	if strings.HasSuffix(pagePath, "/") {
		trimmedPath := strings.TrimSuffix(pagePath, "/")
		if trimmedPath == "" {
			return "/"
		}
		return trimmedPath
	}
	lastSlashIndex := strings.LastIndex(pagePath, "/")
	if lastSlashIndex <= 0 {
		return "/"
	}
	return pagePath[:lastSlashIndex]
}

func cleanPath(rawPath string) string {
	trimmedPath := strings.TrimSpace(rawPath)
	if trimmedPath == "" {
		return "/"
	}
	if trimmedPath[0] != '/' {
		trimmedPath = "/" + trimmedPath
	}
	normalizedPath := path.Clean(trimmedPath)
	if normalizedPath == "." || normalizedPath == "" {
		return "/"
	}
	return normalizedPath
}

func requestCanUseCanonicalTrailingSlash(r *http.Request, pagePath string) bool {
	if r == nil || r.URL == nil {
		return false
	}
	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		return false
	}
	if strings.TrimSpace(r.URL.RawQuery) != "" {
		return false
	}
	rawPath := strings.TrimSpace(r.URL.Path)
	if rawPath == "" || rawPath == "/" || strings.HasSuffix(rawPath, "/") {
		return false
	}
	if pagePath == "/" || strings.HasPrefix(pagePath, "/p/") {
		return false
	}
	if path.Ext(path.Base(pagePath)) != "" {
		return false
	}
	return true
}

func canonicalTrailingSlashURL(r *http.Request, pagePath string) string {
	redirectURL := url.URL{}
	redirectURL.Path = pagePath + "/"
	redirectURL.RawQuery = r.URL.RawQuery
	return redirectURL.String()
}

func (a *App) canonicalTrailingSlashStaticRedirectTarget(r *http.Request, domain, pagePath string) string {
	if !requestCanUseCanonicalTrailingSlash(r, pagePath) {
		return ""
	}
	if _, found := a.pagePasswordRuleFromPrefixFile(domain, pagePath); found {
		return ""
	}
	if !a.publishedStaticPageExists(domain, pagePath) {
		return ""
	}
	return canonicalTrailingSlashURL(r, pagePath)
}

func (a *App) canonicalTrailingSlashRedirectTarget(r *http.Request, domain, pagePath string) string {
	return a.canonicalTrailingSlashRedirectTargetForResolvedPath(r, domain, pagePath, a.resolvedPageRedirectPath(r.Context(), domain, pagePath))
}

func (a *App) canonicalTrailingSlashRedirectTargetForResolvedPath(r *http.Request, domain, pagePath string, redirectTargetPath string) string {
	if !requestCanUseCanonicalTrailingSlash(r, pagePath) {
		return ""
	}
	if redirectTargetPath != "" && redirectTargetPath != pagePath {
		return ""
	}
	if _, found := a.pagePasswordRuleFromPrefixFile(domain, pagePath); found {
		return ""
	}
	if !a.canonicalTrailingSlashResourceExists(r.Context(), domain, pagePath) {
		return ""
	}
	return canonicalTrailingSlashURL(r, pagePath)
}

func (a *App) canonicalTrailingSlashResourceExists(ctx context.Context, domain, pagePath string) bool {
	if a.publishedStaticPageExists(domain, pagePath) {
		return true
	}
	var storedPageCount int
	_ = a.db.QueryRowContext(ctx, `SELECT COUNT(1) FROM pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&storedPageCount)
	if storedPageCount > 0 {
		return true
	}
	_ = a.db.QueryRowContext(ctx, `SELECT COUNT(1) FROM published_pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&storedPageCount)
	if storedPageCount > 0 {
		return true
	}
	return a.chrootResourceExists(ctx, domain, pagePath)
}

func loginReturnPathOrDefault(r *http.Request) string {
	returnPath := strings.TrimSpace(r.URL.Query().Get("return_path"))
	if returnPath != "" {
		return returnPath
	}
	return requestedReturnTarget(r)
}

func hasQueryFlag(r *http.Request, flagName string) bool {
	if strings.TrimSpace(r.URL.RawQuery) == flagName {
		return true
	}
	_, hasFlag := r.URL.Query()[flagName]
	return hasFlag
}

func requestWithSensitiveCookieRequiresHTTPS(r *http.Request) bool {
	if r == nil || httpsecurity.IsLocalRequest(r) || httpsecurity.UsesHTTPS(r) {
		return false
	}
	if hasSitebrushSessionCookie(r) {
		return true
	}
	for _, queryFlag := range []string{"login", "logout", "register", "email_confirm", "captcha", "page_password", "page_password_unlock"} {
		if hasQueryFlag(r, queryFlag) {
			return true
		}
	}
	return false
}

func requestedReturnTarget(r *http.Request) string {
	returnPath := r.URL.Path
	if strings.TrimSpace(returnPath) == "" {
		returnPath = "/"
	}
	queryValues := r.URL.Query()
	queryValues.Del("login")
	queryValues.Del("logout")
	queryValues.Del("register")
	queryValues.Del("return_path")
	encodedQuery := queryValues.Encode()
	if encodedQuery == "" {
		return returnPath
	}
	return returnPath + "?" + encodedQuery
}

func loginURLForRequest(r *http.Request) string {
	loginURL := &url.URL{Path: r.URL.Path}
	queryValues := url.Values{}
	queryValues.Set("login", "")
	queryValues.Set("return_path", requestedReturnTarget(r))
	loginURL.RawQuery = queryValues.Encode()
	return loginURL.String()
}

type templatePropagationProgressEvent struct {
	Stage   string `json:"stage"`
	Domain  string `json:"domain"`
	Path    string `json:"path"`
	Current int    `json:"current"`
	Total   int    `json:"total"`
	Changed int    `json:"changed"`
	Skipped int    `json:"skipped"`
	Message string `json:"message"`
	Error   string `json:"error,omitempty"`
	Done    bool   `json:"done"`
}

type templatePropagationProgressTracker struct {
	mu          sync.Mutex
	subscribers map[string]chan templatePropagationProgressEvent
}

func newTemplatePropagationProgressTracker() *templatePropagationProgressTracker {
	return &templatePropagationProgressTracker{subscribers: make(map[string]chan templatePropagationProgressEvent)}
}

var sitebrushTemplateProgress = newTemplatePropagationProgressTracker()

func (tracker *templatePropagationProgressTracker) Subscribe(token string) (<-chan templatePropagationProgressEvent, func(), bool) {
	token = strings.TrimSpace(token)
	if token == "" {
		return nil, func() {}, false
	}
	tracker.mu.Lock()
	channel := tracker.subscribers[token]
	if channel == nil {
		channel = make(chan templatePropagationProgressEvent, 256)
		tracker.subscribers[token] = channel
	}
	tracker.mu.Unlock()
	cancel := func() {
		tracker.mu.Lock()
		if tracker.subscribers[token] == channel {
			delete(tracker.subscribers, token)
			close(channel)
		}
		tracker.mu.Unlock()
	}
	return channel, cancel, true
}

func (tracker *templatePropagationProgressTracker) Publish(token string, event templatePropagationProgressEvent) {
	token = strings.TrimSpace(token)
	if token == "" {
		return
	}
	tracker.mu.Lock()
	channel := tracker.subscribers[token]
	tracker.mu.Unlock()
	if channel == nil {
		return
	}
	select {
	case channel <- event:
	default:
	}
}

func (tracker *templatePropagationProgressTracker) Finish(token string) {
	token = strings.TrimSpace(token)
	if token == "" {
		return
	}
	tracker.mu.Lock()
	channel := tracker.subscribers[token]
	if channel != nil {
		delete(tracker.subscribers, token)
		close(channel)
	}
	tracker.mu.Unlock()
}

func (a *App) templatePropagationProgressEvents(w http.ResponseWriter, r *http.Request) {
	allowLongStreamingResponse(w)
	if !a.isAdminRequest(r) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	token := strings.TrimSpace(r.URL.Query().Get("template_events"))
	events, cancel, ok := sitebrushTemplateProgress.Subscribe(token)
	if !ok {
		http.Error(w, "missing template progress token", http.StatusBadRequest)
		return
	}
	defer cancel()

	w.Header().Set("Content-Type", "text/event-stream; charset=utf-8")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	flusher, _ := w.(http.Flusher)
	if flusher != nil {
		flusher.Flush()
	}
	for {
		select {
		case <-r.Context().Done():
			return
		case event, open := <-events:
			if !open {
				return
			}
			payload, _ := json.Marshal(event)
			_, _ = fmt.Fprintf(w, "data: %s\n\n", payload)
			if flusher != nil {
				flusher.Flush()
			}
			if event.Done {
				return
			}
		}
	}
}

func (a *App) saveEndpoint(w http.ResponseWriter, r *http.Request) {
	if r.Method == http.MethodPost {
		a.savePage(w, r)
		return
	}
	a.route(w, r)
}

func (a *App) savePage(w http.ResponseWriter, r *http.Request) {
	allowLongStreamingResponse(w)
	if !a.isAdminRequest(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	pagePath := cleanPath(r.FormValue("path"))
	previousPath := pagePath
	if strings.TrimSpace(r.FormValue("previous_path")) != "" {
		previousPath = cleanPath(r.FormValue("previous_path"))
	}
	domain := a.siteDomain(r.Context(), r)
	saveCtx := contextWithDomain(context.Background(), domain)
	progressToken := strings.TrimSpace(r.FormValue("template_progress_token"))
	title := strings.TrimSpace(r.FormValue("title"))
	if title == "" {
		title = pagePath
	}
	html := r.FormValue("html")
	resourceSpider, localizedHTML := localizeSavedPageExternalResources(r.Context(), domain, pagePath, html, r, a.grabTracker)
	html = localizedHTML
	newHTMLBytes := int64(len([]byte(html)))
	var previousStoredHTML string
	_ = a.db.QueryRowContext(saveCtx, `SELECT html FROM pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&previousStoredHTML)
	pageDelta := newHTMLBytes - int64(len([]byte(previousStoredHTML)))
	publishedPageDelta := int64(0)
	publishedStaticDelta := int64(0)
	fileDelta := a.estimateImportedFileDelta(domain, resourceSpider)
	if !a.isDomainFrozen(saveCtx, domain) {
		var previousPublishedHTML string
		_ = a.db.QueryRowContext(saveCtx, `SELECT html FROM published_pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&previousPublishedHTML)
		publishedPageDelta = newHTMLBytes - int64(len([]byte(previousPublishedHTML)))
		publishedStaticPath := filepath.Join(a.domainStaticDir(domain), staticRelativePathForPage(pagePath))
		publishedStaticDelta = newHTMLBytes - a.fileSizeInsideStorage(publishedStaticPath)
	}
	if storageErr := a.applyDomainStorageDelta(saveCtx, domain, pageDelta, publishedPageDelta, newHTMLBytes, fileDelta, publishedStaticDelta); storageErr != nil {
		sitebrushTemplateProgress.Publish(progressToken, templatePropagationProgressEvent{Stage: "error", Domain: domain, Path: pagePath, Error: storageErr.Error(), Done: true})
		http.Error(w, storageErr.Error(), http.StatusInsufficientStorage)
		return
	}
	if persistErr := a.persistSpiderAssets(saveCtx, resourceSpider, pagePath); persistErr != nil {
		_ = a.applyDomainStorageDelta(saveCtx, domain, -pageDelta, -publishedPageDelta, -newHTMLBytes, -fileDelta, -publishedStaticDelta)
		http.Error(w, persistErr.Error(), http.StatusBadGateway)
		return
	}
	a.clearPageRedirectSource(saveCtx, domain, pagePath)
	_, _ = a.db.ExecContext(saveCtx, `INSERT OR REPLACE INTO pages(domain,path,title,html,published) VALUES(?,?,?,?,1)`, domain, pagePath, title, html)
	if !a.isDomainFrozen(saveCtx, domain) {
		_, _ = a.db.ExecContext(saveCtx, `INSERT OR REPLACE INTO published_pages(domain,path,title,html) VALUES(?,?,?,?)`, domain, pagePath, title, html)
		a.writePublishedStaticHTML(domain, pagePath, html)
	}
	_, _ = a.db.ExecContext(saveCtx, `INSERT INTO revisions(domain,page_path,html,created_at) VALUES(?,?,?,?)`, domain, pagePath, html, time.Now().Format(time.RFC3339))
	if previousPath != pagePath {
		a.registerPageRedirect(saveCtx, domain, previousPath, pagePath)
	}
	if pageContentKind(pagePath, html) == "html" {
		sitebrushTemplateProgress.Publish(progressToken, templatePropagationProgressEvent{Stage: "start", Domain: domain, Path: pagePath, Message: "Saving page and scanning SiteBrush-Template pages"})
		a.applyTemplateClassSynchronization(saveCtx, domain, previousStoredHTML, html, progressToken)
		var synchronizedHTML string
		if scanErr := a.db.QueryRowContext(saveCtx, `SELECT html FROM pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&synchronizedHTML); scanErr == nil {
			html = synchronizedHTML
		}
		a.applyTemplatePropagation(saveCtx, domain, html, progressToken)
		sitebrushTemplateProgress.Publish(progressToken, templatePropagationProgressEvent{Stage: "done", Domain: domain, Path: pagePath, Done: true, Message: "Template update completed"})
		sitebrushTemplateProgress.Finish(progressToken)
	}
	httpsecurity.RedirectLocal(w, r, pagePath, http.StatusFound)
}

func (a *App) grabPage(w http.ResponseWriter, r *http.Request) {
	allowLongStreamingResponse(w)
	if !a.isAdminRequest(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}

	pagePath := grabRequestTargetPath(r)
	domain := a.siteDomain(r.Context(), r)
	importContext := contextWithDomain(context.Background(), domain)
	progressToken := strings.TrimSpace(r.FormValue("progress_token"))
	downloadContext, finishDownloadContext := a.grabImportDownloadContext(importContext, progressToken)
	defer finishDownloadContext()

	sourceURL := r.FormValue("source_url")
	if sourceURL == "" {
		http.Error(w, "source_url is required", http.StatusBadRequest)
		return
	}
	sourceOptions, err := parseGrabSourceOptions(r)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	remoteSourceURL, err := parseGrabSourceURLForServerIP(sourceURL, sourceOptions.IP)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	sourceURL = remoteSourceURL.String()

	htmlBytes, resolvedSourceURL, err := downloadGrabSourceHTMLWithResolvedURLContext(downloadContext, sourceURL, sourceOptions)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadGateway)
		return
	}
	remoteSourceURL = resolvedSourceURL
	sourceURL = remoteSourceURL.String()

	importRequest := grabImportRequest{
		Domain:               domain,
		PagePath:             pagePath,
		SourceURL:            sourceURL,
		RemoteSourceURL:      remoteSourceURL,
		HTML:                 string(htmlBytes),
		Context:              downloadContext,
		ProgressToken:        progressToken,
		DownloadTotal:        grabImportDownloadTotal(r),
		DownloadTotalBytes:   grabImportDownloadTotalBytes(r),
		SourceOptions:        sourceOptions,
		SelectedResourceURLs: selectedGrabResourceURLs(r),
	}
	if grabCopyWholeSite(r) {
		importResult, importErr := a.importWholeRemoteSite(importContext, importRequest)
		if importErr != nil {
			statusCode := http.StatusBadGateway
			if strings.Contains(importErr.Error(), "storage limit reached:") {
				statusCode = http.StatusInsufficientStorage
			}
			http.Error(w, importErr.Error(), statusCode)
			return
		}
		if wantsJSONResponse(r) {
			w.Header().Set("Content-Type", "application/json")
			_ = json.NewEncoder(w).Encode(map[string]any{"redirect": httpsecurity.LocalRedirectTarget(importResult.RedirectPath, "/"), "failed_total": importResult.FailedTotal, "failed_urls": importResult.FailedURLs, "failed_reasons": importResult.FailedReasons})
			return
		}
		httpsecurity.RedirectLocal(w, r, importResult.RedirectPath, http.StatusFound)
		return
	}
	spider, html := prepareSinglePageImport(importRequest, a.grabTracker)
	importedPages := []wholeSiteImportedPage{{SourceURL: sourceURL, LocalPath: pagePath, HTML: html}}
	pageDelta, publishedPageDelta, revisionDelta, publishedStaticDelta := a.estimateImportedPagesStorageDelta(importContext, domain, importedPages)
	fileDelta := a.estimateImportedFileDelta(domain, spider)
	if storageErr := a.applyDomainStorageDelta(importContext, domain, pageDelta, publishedPageDelta, revisionDelta, fileDelta, publishedStaticDelta); storageErr != nil {
		http.Error(w, storageErr.Error(), http.StatusInsufficientStorage)
		return
	}
	if persistErr := a.persistSpiderAssets(importContext, spider, pagePath); persistErr != nil {
		_ = a.applyDomainStorageDelta(importContext, domain, -pageDelta, -publishedPageDelta, -revisionDelta, -fileDelta, -publishedStaticDelta)
		http.Error(w, persistErr.Error(), http.StatusBadGateway)
		return
	}
	if storeErr := a.storeWholeSiteImportedPages(importContext, domain, importedPages); storeErr != nil {
		a.rebuildDomainStorageUsage(importContext, domain)
		http.Error(w, storeErr.Error(), http.StatusInternalServerError)
		return
	}
	a.rebuildDomainStorageUsage(importContext, domain)
	if a.grabTracker != nil && importRequest.ProgressToken != "" {
		stage := "done"
		if spider.unresolvedFailedTotal() > 0 {
			stage = "partial"
		}
		a.grabTracker.publish(spider.finalProgressEvent(progressToken, stage))
	}
	if wantsJSONResponse(r) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{"redirect": httpsecurity.LocalRedirectTarget(pagePath, "/"), "failed_total": spider.unresolvedFailedTotal(), "failed_urls": spider.failedResourceURLList(), "failed_reasons": spider.failedResourceReasonMap()})
		return
	}
	httpsecurity.RedirectLocal(w, r, pagePath, http.StatusFound)
}

func (a *App) retryGrabFailedResources(w http.ResponseWriter, r *http.Request) {
	if !a.isAdminRequest(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}

	sourceURL := r.FormValue("source_url")
	if sourceURL == "" {
		http.Error(w, "source_url is required", http.StatusBadRequest)
		return
	}
	sourceOptions, err := parseGrabSourceOptions(r)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	remoteSourceURL, err := parseGrabSourceURLForServerIP(sourceURL, sourceOptions.IP)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	selectedResourceURLs := selectedGrabResourceURLs(r)
	if len(selectedResourceURLs) == 0 {
		http.Error(w, "import_resource_url is required", http.StatusBadRequest)
		return
	}

	domain := a.siteDomain(r.Context(), r)
	pagePath := grabRequestTargetPath(r)
	progressToken := strings.TrimSpace(r.FormValue("progress_token"))
	downloadContext, finishDownloadContext := a.grabImportDownloadContext(r.Context(), progressToken)
	defer finishDownloadContext()
	importResult, err := a.retryImportedPageResources(r.Context(), grabImportRequest{Domain: domain, PagePath: pagePath, RemoteSourceURL: remoteSourceURL, Context: downloadContext, ProgressToken: progressToken, DownloadTotal: grabImportDownloadTotal(r), DownloadTotalBytes: grabImportDownloadTotalBytes(r), SelectedResourceURLs: selectedResourceURLs, SourceOptions: sourceOptions})
	if err != nil {
		statusCode := http.StatusBadGateway
		if strings.Contains(err.Error(), "storage limit reached:") {
			statusCode = http.StatusInsufficientStorage
		}
		http.Error(w, err.Error(), statusCode)
		return
	}
	if wantsJSONResponse(r) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{"status": "ok", "redirect": httpsecurity.LocalRedirectTarget(importResult.RedirectPath, "/"), "failed_total": importResult.FailedTotal, "failed_urls": importResult.FailedURLs, "failed_reasons": importResult.FailedReasons})
		return
	}
	httpsecurity.RedirectLocal(w, r, pagePath, http.StatusFound)
}

func (a *App) cancelGrabImport(w http.ResponseWriter, r *http.Request) {
	if !a.isAdminRequest(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	progressToken := strings.TrimSpace(r.FormValue("progress_token"))
	if progressToken == "" {
		http.Error(w, "progress_token is required", http.StatusBadRequest)
		return
	}
	canceled := a.activeGrabCancelTracker().Cancel(progressToken)
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]any{"status": "ok", "canceled": canceled})
}

// === Public trial site preparation ===

func (a *App) publicTrialSitePreview(w http.ResponseWriter, r *http.Request) {
	if !a.publicTrialAllowed(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	progressToken := strings.TrimSpace(r.FormValue("progress_token"))
	if progressToken == "" {
		http.Error(w, "progress_token is required", http.StatusBadRequest)
		return
	}
	sourceURL := strings.TrimSpace(r.FormValue("source_url"))
	if sourceURL == "" {
		http.Error(w, "source_url is required", http.StatusBadRequest)
		return
	}
	cancelSession, started := a.activePublicTrialPreviewStore().Start(progressToken)
	if !started {
		status, found := a.activePublicTrialPreviewStore().Status(progressToken)
		if !found {
			http.Error(w, "preview token is unavailable", http.StatusConflict)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		if status.Status == "done" || status.Status == "partial" {
			_ = json.NewEncoder(w).Encode(status.Response)
			return
		}
		if preview, usable := a.activePublicTrialPreviewStore().Get(progressToken); usable && len(preview.ImportedPages) > 0 {
			previewURL := absoluteURLForPath(r, "/?trial_site_preview_frame&token="+url.QueryEscape(progressToken))
			_ = json.NewEncoder(w).Encode(publicTrialPreviewResponseFromPreview(preview, "running", previewURL, translationsForRequest(r)))
			return
		}
		w.WriteHeader(http.StatusAccepted)
		_ = json.NewEncoder(w).Encode(map[string]string{"token": progressToken, "status": status.Status})
		return
	}
	previewURL := absoluteURLForPath(r, "/?trial_site_preview_frame&token="+url.QueryEscape(progressToken))
	translations := translationsForRequest(r)
	copyWholeSite := grabCopyWholeSite(r)
	sourceOptions, sourceOptionsErr := parseGrabSourceOptions(r)
	if sourceOptionsErr != nil {
		a.activePublicTrialPreviewStore().Fail(progressToken, sourceOptionsErr.Error())
		http.Error(w, sourceOptionsErr.Error(), http.StatusBadRequest)
		return
	}
	go a.runPublicTrialSitePreview(progressToken, sourceURL, previewURL, translations, cancelSession, copyWholeSite, sourceOptions)

	w.Header().Set("Content-Type", "application/json")
	if strings.TrimSpace(r.FormValue("unified_copy")) == "1" {
		a.writeTerminalPublicTrialPreview(w, r, progressToken)
		return
	}
	if strings.TrimSpace(r.FormValue("async_preview")) != "1" {
		a.writeFirstUsablePublicTrialPreview(w, r, progressToken, previewURL, translations)
		return
	}
	w.WriteHeader(http.StatusAccepted)
	_ = json.NewEncoder(w).Encode(map[string]string{"token": progressToken, "status": "running"})
}

func (a *App) writeTerminalPublicTrialPreview(w http.ResponseWriter, r *http.Request, progressToken string) {
	ticker := time.NewTicker(150 * time.Millisecond)
	defer ticker.Stop()
	timer := time.NewTimer(publicTrialPreviewMaxDuration + 5*time.Second)
	defer timer.Stop()
	for {
		status, found := a.activePublicTrialPreviewStore().Status(progressToken)
		if found {
			switch status.Status {
			case "done", "partial":
				_ = json.NewEncoder(w).Encode(status.Response)
				return
			case "error":
				http.Error(w, status.ErrorText, http.StatusBadGateway)
				return
			case "canceled":
				http.Error(w, "preview canceled", http.StatusConflict)
				return
			}
		}
		select {
		case <-r.Context().Done():
			return
		case <-timer.C:
			if preview, usable := a.activePublicTrialPreviewStore().Get(progressToken); usable && len(preview.ImportedPages) > 0 {
				preview.SinglePageRequired = preview.CopyWholeSite
				response := publicTrialPreviewResponseFromPreview(preview, "partial", "", translationsForRequest(r))
				response.Message = translationOrDefault(translationsForRequest(r), "public_trial_partial_timeout", "The whole-site analysis time limit was reached. Copy the first page to get a reliable test-drive result.")
				a.activePublicTrialPreviewStore().Complete(progressToken, "partial", response)
				_ = json.NewEncoder(w).Encode(response)
				return
			}
			http.Error(w, translationOrDefault(translationsForRequest(r), "public_trial_load_failed", "Website analysis failed."), http.StatusGatewayTimeout)
			return
		case <-ticker.C:
		}
	}
}

func (a *App) writeFirstUsablePublicTrialPreview(w http.ResponseWriter, r *http.Request, progressToken, previewURL string, translations map[string]string) {
	timer := time.NewTimer(45 * time.Second)
	defer timer.Stop()
	ticker := time.NewTicker(150 * time.Millisecond)
	defer ticker.Stop()
	for {
		if preview, found := a.activePublicTrialPreviewStore().Get(progressToken); found && len(preview.ImportedPages) > 0 {
			_ = json.NewEncoder(w).Encode(publicTrialPreviewResponseFromPreview(preview, "running", previewURL, translations))
			return
		}
		if status, found := a.activePublicTrialPreviewStore().Status(progressToken); found && status.Status == "error" {
			http.Error(w, status.ErrorText, http.StatusBadGateway)
			return
		}
		select {
		case <-r.Context().Done():
			return
		case <-timer.C:
			http.Error(w, "preview is still preparing", http.StatusGatewayTimeout)
			return
		case <-ticker.C:
		}
	}
}

func (a *App) runPublicTrialSitePreview(progressToken, requestedSourceURL, previewURL string, translations map[string]string, cancelSession <-chan struct{}, copyWholeSite bool, sourceOptions grabSourceOptions) {
	previewContext, cancelPreview := context.WithTimeout(context.Background(), publicTrialPreviewMaxDuration)
	defer cancelPreview()
	watchdogDone := make(chan struct{})
	defer close(watchdogDone)
	if a.grabTracker != nil {
		activityStream := a.grabTracker.subscribe(progressToken)
		defer a.grabTracker.unsubscribe(progressToken, activityStream)
		go func() {
			timer := time.NewTimer(publicTrialPreviewStallTimeout)
			defer timer.Stop()
			for {
				select {
				case _, streamOpen := <-activityStream:
					if !streamOpen {
						return
					}
					if !timer.Stop() {
						select {
						case <-timer.C:
						default:
						}
					}
					timer.Reset(publicTrialPreviewStallTimeout)
				case <-timer.C:
					cancelPreview()
					return
				case <-watchdogDone:
					return
				case <-previewContext.Done():
					return
				}
			}
		}()
	}
	defer func() {
		if recovered := recover(); recovered != nil {
			errorText := translationOrDefault(translations, "public_trial_load_failed", "Website analysis failed.")
			a.activePublicTrialPreviewStore().Fail(progressToken, errorText)
			if a.grabTracker != nil {
				a.grabTracker.publish(grabProgressEvent{Token: progressToken, Stage: "error", CurrentError: errorText, Message: errorText})
			}
		}
	}()
	go func() {
		select {
		case <-cancelSession:
			cancelPreview()
		case <-previewContext.Done():
		}
	}()

	sourceURL, remoteSourceURL, htmlBytes, err := a.resolvePublicTrialSource(previewContext, requestedSourceURL, progressToken, sourceOptions)
	if err != nil {
		errorText := publicTrialSourceErrorText(translations, err)
		a.activePublicTrialPreviewStore().Fail(progressToken, errorText)
		if a.grabTracker != nil {
			a.grabTracker.publish(grabProgressEvent{Token: progressToken, Stage: "error", CurrentError: errorText, Message: errorText})
		}
		return
	}
	publicSourceOptions := sourceOptions
	initialSpider := newPreviewPageSpider("", remoteSourceURL, grabResourceMaxDepth, a.grabTracker, progressToken, publicSourceOptions)
	initialSpider.setContext(previewContext)
	initialRootResource := &mirroredResource{url: sourceURL, content: htmlBytes}
	initialSpider.resources[sourceURL] = initialRootResource
	initialHTML := string(initialRootResource.content)
	initialImportedPages := []wholeSiteImportedPage{{SourceURL: sourceURL, LocalPath: "/", HTML: initialHTML}}
	initialResources := []grabResourcePreview{}
	initialBytes := int64(len(htmlBytes))
	initialPlan, initialFreePlan, initialFitsFreePlan := a.smallestPublicTrialPlan(previewContext, initialBytes)
	a.activePublicTrialPreviewStore().Save(publicTrialPreview{
		Token:          progressToken,
		SourceURL:      sourceURL,
		ImportedPages:  initialImportedPages,
		Resources:      initialResources,
		Spider:         initialSpider,
		PageCount:      1,
		ResourceCount:  len(initialResources),
		ResourceCounts: publicTrialResourceCountsFromResources(initialResources),
		TotalBytes:     initialBytes,
		RequiredBytes:  initialBytes,
		Plan:           initialPlan,
		FreePlan:       initialFreePlan,
		FitsFreePlan:   initialFitsFreePlan,
		CopyWholeSite:  copyWholeSite,
		SourceOptions:  sourceOptions,
	})
	wholeSitePreview := wholeSitePreviewResult{PageCount: 1, ImportedPages: initialImportedPages, Spider: initialSpider}
	if copyWholeSite {
		freePreviewByteLimit := initialFreePlan.QuotaBytes
		if freePreviewByteLimit <= 0 {
			freePreviewByteLimit = defaultDomainStorageLimitBytes
		}
		wholeSitePreview = previewWholeRemoteSiteResourcesWithLimit(previewContext, remoteSourceURL, string(htmlBytes), "/", a.grabTracker, progressToken, publicSourceOptions, freePreviewByteLimit)
	} else {
		initialSpider.collectPreviewNestedResources(initialRootResource, 0, "text/html")
		wholeSitePreview.Resources = previewResourcesFromSpider(initialSpider, map[string]struct{}{sourceURL: {}})
	}
	importedPages := wholeSitePreview.ImportedPages
	if len(importedPages) == 0 {
		importedPages = initialImportedPages
	}
	resources := wholeSitePreview.Resources
	if len(resources) == 0 {
		resources = initialResources
	}
	previewSpider := wholeSitePreview.Spider
	if previewSpider == nil {
		previewSpider = initialSpider
	}
	pageCount := wholeSitePreview.PageCount
	if pageCount < len(importedPages) {
		pageCount = len(importedPages)
	}
	resourceBytes := sumGrabPreviewResourceBytes(resources)
	pageBytes := int64(0)
	for _, importedPage := range importedPages {
		pageBytes += int64(len([]byte(importedPage.HTML)))
	}
	requiredBytes := pageBytes + resourceBytes
	plan, freePlan, fitsFreePlan := a.smallestPublicTrialPlan(previewContext, requiredBytes)
	previewTimedOut := previewContext.Err() != nil
	preview := publicTrialPreview{
		Token:              progressToken,
		SourceURL:          sourceURL,
		ImportedPages:      importedPages,
		Resources:          resources,
		Spider:             previewSpider,
		PageCount:          pageCount,
		ResourceCount:      len(resources),
		ResourceCounts:     publicTrialResourceCountsFromResources(resources),
		TotalBytes:         requiredBytes,
		RequiredBytes:      requiredBytes,
		Plan:               plan,
		FreePlan:           freePlan,
		FitsFreePlan:       fitsFreePlan,
		SinglePageRequired: copyWholeSite && (wholeSitePreview.LimitReached || previewTimedOut),
		CopyWholeSite:      copyWholeSite,
		SourceOptions:      sourceOptions,
	}
	a.activePublicTrialPreviewStore().Save(preview)
	status := "done"
	if wholeSitePreview.Partial || previewSpider.unresolvedFailedTotal() > 0 || previewContext.Err() != nil {
		status = "partial"
	}
	response := publicTrialPreviewResponseFromPreview(preview, status, previewURL, translations)
	if previewTimedOut && preview.SinglePageRequired {
		response.Message = translationOrDefault(translations, "public_trial_partial_timeout", "The whole-site analysis time limit was reached. Copy the first page to get a reliable test-drive result.")
	}
	response.PageBytes = pageBytes
	a.activePublicTrialPreviewStore().Complete(progressToken, status, response)
	if a.grabTracker != nil && previewSpider != nil {
		a.grabTracker.publish(previewSpider.finalProgressEvent(progressToken, status))
	}
}

func publicTrialPreviewResponseFromPreview(preview publicTrialPreview, status, previewURL string, translations map[string]string) publicTrialPreviewResponse {
	pageBytes := int64(0)
	for _, importedPage := range preview.ImportedPages {
		pageBytes += int64(len([]byte(importedPage.HTML)))
	}
	limitBytes := preview.Plan.QuotaBytes
	if limitBytes <= 0 {
		limitBytes = defaultDomainStorageLimitBytes
	}
	response := publicTrialPreviewResponse{
		Status:                status,
		Usable:                len(preview.ImportedPages) > 0,
		Refreshing:            status == "running",
		SourceURL:             preview.SourceURL,
		PreviewURL:            previewURL,
		PageCount:             preview.PageCount,
		ResourceCount:         preview.ResourceCount,
		ResourceCounts:        preview.ResourceCounts,
		Resources:             preview.Resources,
		PageBytes:             pageBytes,
		TotalBytes:            preview.TotalBytes,
		RequiredBytes:         preview.RequiredBytes,
		FitsFreePlan:          preview.FitsFreePlan,
		SinglePageRequired:    preview.SinglePageRequired,
		Plan:                  preview.Plan,
		FreePlan:              preview.FreePlan,
		Message:               publicTrialPlanMessage(translations, preview),
		DownloadTotal:         preview.PageCount + preview.ResourceCount,
		DownloadTotalBytes:    preview.RequiredBytes,
		PageDownloadBytes:     pageBytes,
		PageStorageBytes:      pageBytes,
		CurrentUsedBytes:      0,
		LimitBytes:            limitBytes,
		FreeBytes:             limitBytes,
		SelectedResourceBytes: max(int64(0), preview.RequiredBytes-pageBytes),
		EstimatedImportBytes:  preview.RequiredBytes,
		ProjectedUsedBytes:    preview.RequiredBytes,
		FitsQuota:             preview.RequiredBytes <= limitBytes,
	}
	if preview.Spider != nil {
		response.FailedTotal = preview.Spider.unresolvedFailedTotal()
		response.FailedURLs = preview.Spider.failedResourceURLList()
		response.FailedReasons = preview.Spider.failedResourceReasonMap()
	}
	return response
}

func (a *App) publicTrialSitePreviewStatus(w http.ResponseWriter, r *http.Request) {
	if !a.publicTrialAllowed(r) || r.Method != http.MethodGet {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	progressToken := strings.TrimSpace(r.URL.Query().Get("token"))
	status, found := a.activePublicTrialPreviewStore().Status(progressToken)
	if !found {
		http.Error(w, "preview not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Content-Type", "application/json")
	switch status.Status {
	case "done", "partial":
		_ = json.NewEncoder(w).Encode(status.Response)
	case "error":
		_ = json.NewEncoder(w).Encode(map[string]string{"status": "error", "error": status.ErrorText})
	default:
		if preview, usable := a.activePublicTrialPreviewStore().Get(progressToken); usable && len(preview.ImportedPages) > 0 {
			previewURL := absoluteURLForPath(r, "/?trial_site_preview_frame&token="+url.QueryEscape(progressToken))
			_ = json.NewEncoder(w).Encode(publicTrialPreviewResponseFromPreview(preview, "running", previewURL, translationsForRequest(r)))
			return
		}
		w.WriteHeader(http.StatusAccepted)
		_ = json.NewEncoder(w).Encode(map[string]string{"token": progressToken, "status": status.Status})
	}
}

func (a *App) publicTrialSitePreviewCancel(w http.ResponseWriter, r *http.Request) {
	if !a.publicTrialAllowed(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	progressToken := strings.TrimSpace(r.FormValue("progress_token"))
	if progressToken == "" {
		http.Error(w, "progress_token is required", http.StatusBadRequest)
		return
	}
	canceled := a.activePublicTrialPreviewStore().Cancel(progressToken)
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]any{"status": "ok", "canceled": canceled})
}

func (a *App) publicTrialSitePreviewFrame(w http.ResponseWriter, r *http.Request) {
	if !a.publicTrialAllowed(r) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	preview, found := a.activePublicTrialPreviewStore().Wait(r.URL.Query().Get("token"), 20*time.Second)
	if !found || len(preview.ImportedPages) == 0 {
		a.renderPublicTrialPreviewWaitingFrame(w, r)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(preview.ImportedPages[0].HTML))
}

