func (a *App) publicTrialSiteCreate(w http.ResponseWriter, r *http.Request) {
	if !a.publicTrialAllowed(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	progressToken := strings.TrimSpace(r.FormValue("preview_token"))
	if progressToken == "" {
		progressToken = strings.TrimSpace(r.FormValue("progress_token"))
	}
	createProgressToken := strings.TrimSpace(r.FormValue("create_progress_token"))
	if createProgressToken == "" {
		createProgressToken = progressToken
	}
	a.activePublicTrialPreviewStore().Cancel(progressToken)
	preview, found := a.activePublicTrialPreviewStore().Get(progressToken)
	if !found {
		http.Error(w, "preview not found", http.StatusNotFound)
		return
	}
	if preview.SinglePageRequired && preview.CopyWholeSite {
		http.Error(w, translationOrDefault(translationsForRequest(r), "public_trial_single_page_required", "The website is larger than the free test-drive limit. Stop scanning the website and copy only its first page."), http.StatusConflict)
		return
	}
	selectedResourceURLs := selectedGrabResourceURLs(r)
	selectionConfirmed := strings.TrimSpace(r.FormValue("import_selection_confirmed")) == "1"
	if len(selectedResourceURLs) == 0 && !selectionConfirmed {
		selectedResourceURLs = publicTrialResourceURLMap(preview.Resources)
	}
	preview = a.preparePublicTrialPreviewForCreate(r.Context(), preview, selectedResourceURLs, createProgressToken)
	var parentDomain string
	err := a.withServerControlDatabaseRead(r.Context(), "public-trial-owner", func(database *sql.DB) error {
		var ownerFound bool
		parentDomain, ownerFound = (hostingandsupport.Store{DB: database}).OwnerDomain(r.Context())
		if !ownerFound {
			return errors.New("owner domain is required")
		}
		return nil
	})
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	trialDomain, err := a.availablePublicTrialDomain(r.Context(), preview.SourceURL, parentDomain)
	if err != nil {
		http.Error(w, err.Error(), http.StatusConflict)
		return
	}
	quotaBytes := preview.Plan.QuotaBytes
	if quotaBytes <= 0 {
		quotaBytes = defaultDomainStorageLimitBytes
	}
	if err := a.createManagedSiteWithoutAdmin(r.Context(), trialDomain, quotaBytes); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	domainContext := contextWithSiteDatabaseCreation(contextWithDomain(r.Context(), trialDomain))
	if err := a.persistPublicTrialPreview(domainContext, trialDomain, preview); err != nil {
		_ = a.deleteDemoManagedSiteWithoutBackup(r.Context(), trialDomain)
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	serviceStatus := "trial"
	if preview.FitsFreePlan {
		serviceStatus = "free"
	}
	if preview.Plan.ID > 0 {
		if err := a.withServerControlDatabaseWrite(r.Context(), "public-trial-assign", func(database *sql.DB) error {
			return (hostingandsupport.Store{DB: database}).AssignSite(r.Context(), trialDomain, preview.Plan.ID, serviceStatus)
		}); err != nil {
			_ = a.deleteDemoManagedSiteWithoutBackup(r.Context(), trialDomain)
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
	}
	a.activePublicTrialPreviewStore().Delete(progressToken)
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]any{"redirect": requestScheme(r) + "://" + trialDomain + "/"})
}

func (a *App) publicTrialSiteWS(w http.ResponseWriter, r *http.Request) {
	if !a.publicTrialAllowed(r) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	progressToken := strings.TrimSpace(r.URL.Query().Get("token"))
	if progressToken == "" {
		http.Error(w, "token is required", http.StatusBadRequest)
		return
	}
	connection, err := upgradeToWebSocket(w, r)
	if err != nil {
		return
	}
	defer connection.Close()
	events := a.grabTracker.subscribe(progressToken)
	defer a.grabTracker.unsubscribe(progressToken, events)
	readyEventJSON, marshalReadyErr := json.Marshal(grabProgressEvent{Token: progressToken, Stage: "ready"})
	if marshalReadyErr != nil {
		return
	}
	if err := connection.WriteText(readyEventJSON); err != nil {
		return
	}
	heartbeatTicker := time.NewTicker(20 * time.Second)
	defer heartbeatTicker.Stop()
	for {
		select {
		case <-r.Context().Done():
			return
		case <-heartbeatTicker.C:
			heartbeatJSON, marshalHeartbeatErr := json.Marshal(grabProgressEvent{Token: progressToken, Stage: "heartbeat"})
			if marshalHeartbeatErr != nil || connection.WriteText(heartbeatJSON) != nil {
				return
			}
		case event, isOpen := <-events:
			if !isOpen {
				return
			}
			eventJSON, marshalErr := json.Marshal(event)
			if marshalErr != nil {
				return
			}
			if err := connection.WriteText(eventJSON); err != nil {
				return
			}
			if event.Stage == "done" || event.Stage == "partial" || (event.Stage == "error" && strings.TrimSpace(event.CurrentURL) == "") {
				return
			}
		}
	}
}

func (a *App) publicTrialAllowed(r *http.Request) bool {
	allowed := false
	_ = a.withServerControlDatabaseRead(r.Context(), "public-trial-allowed", func(database *sql.DB) error {
		store := hostingandsupport.Store{DB: database}
		ownerDomain, found := store.OwnerDomain(r.Context())
		allowed = store.AutomaticRegistrationAllowed(r.Context()) && found && normalizeDomainName(ownerDomain) == normalizeDomainName(a.siteDomain(r.Context(), r))
		return nil
	})
	return allowed
}

func (a *App) cleanupExpiredPublicTrialSite(ctx context.Context, domain string) {
	domain = normalizeDomainName(domain)
	if domain == "" {
		return
	}
	var serviceStatus string
	var updatedAtText string
	err := a.withServerControlDatabaseRead(ctx, "trial-cleanup-check", func(database *sql.DB) error {
		return database.QueryRowContext(ctx, `SELECT service_status,updated_at FROM site_service_assignments WHERE domain=?`, domain).Scan(&serviceStatus, &updatedAtText)
	})
	if err != nil {
		return
	}
	serviceStatus = strings.ToLower(strings.TrimSpace(serviceStatus))
	if serviceStatus != "trial" && serviceStatus != "free" {
		return
	}
	updatedAt, parseErr := time.Parse(time.RFC3339, strings.TrimSpace(updatedAtText))
	if parseErr != nil || time.Since(updatedAt) <= 24*time.Hour {
		return
	}
	if a.rawManagedSiteHasAdmin(ctx, domain) {
		return
	}
	row, found, rowErr := a.managedSiteQuotaRow(ctx, domain)
	if rowErr != nil {
		return
	}
	if found && sameSiteQuotaPath(row.DatabasePath, a.serverControlDBPath()) {
		return
	}
	deleted := false
	_ = a.withServerControlDatabaseWrite(ctx, "trial-cleanup-delete", func(database *sql.DB) error {
		if queryErr := database.QueryRowContext(ctx, `SELECT service_status,updated_at FROM site_service_assignments WHERE domain=?`, domain).Scan(&serviceStatus, &updatedAtText); queryErr != nil {
			return queryErr
		}
		serviceStatus = strings.ToLower(strings.TrimSpace(serviceStatus))
		updatedAt, parseErr = time.Parse(time.RFC3339, strings.TrimSpace(updatedAtText))
		if (serviceStatus != "trial" && serviceStatus != "free") || parseErr != nil || time.Since(updatedAt) <= 24*time.Hour {
			return nil
		}
		var ownerCount int
		_ = database.QueryRowContext(ctx, `SELECT COUNT(1) FROM server_managers WHERE domain=? AND role='owner'`, domain).Scan(&ownerCount)
		if ownerCount > 0 {
			return nil
		}
		(hostingandsupport.Store{DB: database}).RemoveSiteAssignment(ctx, domain)
		_, deleteErr := database.ExecContext(ctx, `DELETE FROM server_managers WHERE domain=? AND role<>'owner'`, domain)
		deleted = deleteErr == nil
		return deleteErr
	})
	if !deleted {
		return
	}
	if found {
		if deleteErr := a.deleteManagedSiteFiles(ctx, row); deleteErr != nil {
			log.Printf("expired public trial cleanup failed domain=%s error=%v", domain, deleteErr)
		}
	}
}

func (a *App) cleanupExpiredPublicTrialSites(ctx context.Context, now time.Time) {
	expiredDomains := make([]string, 0)
	if err := a.withServerControlDatabaseRead(ctx, "trial-cleanup-scan", func(database *sql.DB) error {
		rows, queryErr := database.QueryContext(ctx, `SELECT domain,updated_at FROM site_service_assignments WHERE service_status IN ('trial','free')`)
		if queryErr != nil {
			return queryErr
		}
		defer rows.Close()
		for rows.Next() {
			var domain string
			var updatedAtText string
			if scanErr := rows.Scan(&domain, &updatedAtText); scanErr != nil {
				continue
			}
			updatedAt, parseErr := time.Parse(time.RFC3339, strings.TrimSpace(updatedAtText))
			if parseErr == nil && now.Sub(updatedAt) > 24*time.Hour {
				expiredDomains = append(expiredDomains, domain)
			}
		}
		return rows.Err()
	}); err != nil {
		return
	}
	for _, domain := range expiredDomains {
		select {
		case <-ctx.Done():
			return
		default:
			a.cleanupExpiredPublicTrialSite(ctx, domain)
		}
	}
}

func (a *App) activatePublicTrialAfterAdminRegistration(ctx context.Context, domain string) {
	domain = normalizeDomainName(domain)
	if domain == "" {
		return
	}
	_ = a.withServerControlDatabaseWrite(ctx, "public-trial-activate", func(database *sql.DB) error {
		store := hostingandsupport.Store{DB: database}
		assignment, found := store.ServiceAssignments(ctx)[domain]
		if !found || strings.ToLower(strings.TrimSpace(assignment.ServiceStatus)) != "trial" {
			return nil
		}
		return store.AssignSite(ctx, domain, assignment.PlanID, "trial")
	})
}

func (a *App) rawManagedSiteHasAdmin(ctx context.Context, domain string) bool {
	domain = normalizeDomainName(domain)
	if domain == "" {
		return false
	}
	siteDatabasePath := filepath.Join(siteDatabaseRootPath(a.serverControlDBPath()), domainStorageName(domain)+".db")
	realSiteDatabasePath, pathErr := a.existingPathInsideStorage(siteDatabasePath)
	if pathErr != nil {
		return false
	}
	rawDatabase, err := sql.Open("sqlite", "file:"+realSiteDatabasePath)
	if err != nil {
		return false
	}
	defer rawDatabase.Close()
	var adminCount int
	_ = rawDatabase.QueryRowContext(ctx, `SELECT COUNT(1) FROM users WHERE domain=? AND is_admin=1`, domain).Scan(&adminCount)
	return adminCount > 0
}

func (a *App) resolvePublicTrialSource(ctx context.Context, rawSourceURL, progressToken string, sourceOptions grabSourceOptions) (string, *url.URL, []byte, error) {
	sourceText := strings.TrimSpace(rawSourceURL)
	if sourceText == "" {
		return "", nil, nil, errors.New("source_url is required")
	}
	hasScheme := strings.Contains(sourceText, "://") || strings.HasPrefix(sourceText, "//")
	candidates := []string{sourceText}
	if !hasScheme {
		candidates = []string{"https://" + sourceText, "http://" + sourceText}
	}
	var lastErr error
	for _, candidate := range candidates {
		remoteSourceURL, parseErr := parseGrabSourceURL(candidate)
		if parseErr != nil {
			lastErr = parseErr
			continue
		}
		htmlBytes, resolvedSourceURL, downloadErr := a.downloadPublicTrialSourceHTML(ctx, remoteSourceURL.String(), progressToken, sourceOptions)
		if downloadErr == nil {
			return resolvedSourceURL.String(), resolvedSourceURL, htmlBytes, nil
		}
		lastErr = downloadErr
	}
	if lastErr == nil {
		lastErr = errors.New("source_url is invalid")
	}
	return "", nil, nil, lastErr
}

func (a *App) downloadPublicTrialSourceHTML(ctx context.Context, sourceURL, progressToken string, sourceOptions grabSourceOptions) ([]byte, *url.URL, error) {
	remoteSourceURL, err := url.Parse(sourceURL)
	if err != nil {
		return nil, nil, errors.New("source_url is invalid")
	}
	if err := requirePublicOutboundURL(remoteSourceURL); err != nil {
		return nil, nil, err
	}
	client := newGrabHTTPClientForSourceOptions(remoteSourceURL.Hostname(), sourceOptions)
	lastStatus := ""
	downloadResult, err := crawler.DownloadHTMLPageWithRetriesContext(ctx, client, remoteSourceURL, func(request *http.Request) {
		applyGrabRequestHeaders(request, sourceOptions)
		applyGrabHTMLRequestHeaders(request)
	}, crawler.HTMLDownloadRetryOptions{
		Attempts: 3,
		Delay:    1500 * time.Millisecond,
		OnAttempt: func(attempt, total int, pageURL *url.URL) {
			a.publishPublicTrialSourceAttempt(progressToken, "source_attempt", pageURL, attempt, total, 0)
		},
		OnRetry: func(attempt, total int, pageURL *url.URL, retryErr error, delay time.Duration) {
			a.publishPublicTrialSourceRetry(progressToken, pageURL, attempt, total, retryErr, delay)
		},
	})
	if err == nil && downloadResult.IsHTML {
		logImportedHTMLDecodeDecision(remoteSourceURL, downloadResult)
		downloadedHTML := rewriteImportedHTMLCharsetDeclaration(downloadResult.HTML)
		if isSitebrushMissingPageHTML(downloadedHTML) {
			return nil, downloadResult.ResolvedURL, errors.New("source page is a SiteBrush 404 page")
		}
		return []byte(downloadedHTML), downloadResult.ResolvedURL, nil
	}
	if downloadResult.Status != "" {
		lastStatus = downloadResult.Status
	}
	if shouldFallbackGrabSourceToHTTP(remoteSourceURL) {
		fallbackURL := crawler.CloneURL(remoteSourceURL)
		fallbackURL.Scheme = "http"
		fallbackURL.Host = fallbackURL.Hostname()
		if err := requirePublicOutboundURL(fallbackURL); err != nil {
			return nil, nil, err
		}
		downloadResult, err = crawler.DownloadHTMLPageWithRetriesContext(ctx, client, fallbackURL, func(request *http.Request) {
			applyGrabRequestHeaders(request, sourceOptions)
			applyGrabHTMLRequestHeaders(request)
		}, crawler.HTMLDownloadRetryOptions{
			Attempts: 2,
			Delay:    1500 * time.Millisecond,
			OnAttempt: func(attempt, total int, pageURL *url.URL) {
				a.publishPublicTrialSourceAttempt(progressToken, "source_attempt", pageURL, attempt, total, 0)
			},
			OnRetry: func(attempt, total int, pageURL *url.URL, retryErr error, delay time.Duration) {
				a.publishPublicTrialSourceRetry(progressToken, pageURL, attempt, total, retryErr, delay)
			},
		})
		if err == nil && downloadResult.IsHTML {
			logImportedHTMLDecodeDecision(fallbackURL, downloadResult)
			downloadedHTML := rewriteImportedHTMLCharsetDeclaration(downloadResult.HTML)
			if isSitebrushMissingPageHTML(downloadedHTML) {
				return nil, downloadResult.ResolvedURL, errors.New("source page is a SiteBrush 404 page")
			}
			return []byte(downloadedHTML), downloadResult.ResolvedURL, nil
		}
		if downloadResult.Status != "" {
			lastStatus = downloadResult.Status
		}
	}
	if strings.TrimSpace(lastStatus) != "" {
		return nil, nil, fmt.Errorf("source page returned %s", lastStatus)
	}
	if err != nil {
		return nil, nil, errors.New("failed to download source page")
	}
	return nil, nil, errors.New("source page did not return a public HTML page")
}

func (a *App) publishPublicTrialSourceAttempt(progressToken, stage string, pageURL *url.URL, attempt, total int, retryDelaySeconds int) {
	if a == nil || a.grabTracker == nil || strings.TrimSpace(progressToken) == "" {
		return
	}
	currentURL := ""
	if pageURL != nil {
		currentURL = pageURL.String()
	}
	a.grabTracker.publish(grabProgressEvent{
		Token:             progressToken,
		Stage:             stage,
		FoundTotal:        1,
		DownloadTotal:     1,
		RetryAttempt:      attempt,
		RetryTotal:        total,
		RetryDelaySeconds: retryDelaySeconds,
		CurrentURL:        currentURL,
		CompletedPercent:  5,
	})
}

func (a *App) publishPublicTrialSourceRetry(progressToken string, pageURL *url.URL, attempt, total int, retryErr error, delay time.Duration) {
	delaySeconds := int(delay.Seconds())
	if delaySeconds < 0 {
		delaySeconds = 0
	}
	if a == nil || a.grabTracker == nil || strings.TrimSpace(progressToken) == "" {
		return
	}
	currentURL := ""
	if pageURL != nil {
		currentURL = pageURL.String()
	}
	a.grabTracker.publish(grabProgressEvent{
		Token:             progressToken,
		Stage:             "error",
		FoundTotal:        1,
		DownloadTotal:     1,
		FailedTotal:       1,
		RetryAttempt:      attempt,
		RetryTotal:        total - 1,
		RetryDelaySeconds: delaySeconds,
		CurrentURL:        currentURL,
		CurrentError:      crawler.ErrorReason(retryErr),
		CompletedPercent:  5,
	})
	a.publishPublicTrialSourceAttempt(progressToken, "retry_wait", pageURL, attempt, total-1, delaySeconds)
}

func (a *App) smallestPublicTrialPlan(ctx context.Context, requiredBytes int64) (publicTrialPlanView, publicTrialPlanView, bool) {
	plans := a.publicHostingAndSupportPlans(ctx)
	if requiredBytes <= 0 {
		requiredBytes = 1
	}
	var freePlan hostingandsupport.Plan
	freePlanFound := false
	var selectedPlan hostingandsupport.Plan
	for _, plan := range plans {
		if planIsFree(plan) && (!freePlanFound || plan.QuotaBytes < freePlan.QuotaBytes) {
			freePlan = plan
			freePlanFound = true
		}
		if plan.QuotaBytes < requiredBytes {
			continue
		}
		if selectedPlan.ID == 0 || plan.QuotaBytes < selectedPlan.QuotaBytes {
			selectedPlan = plan
		}
	}
	if freePlanFound && freePlan.QuotaBytes >= requiredBytes {
		freePlanView := publicTrialPlanViewFromHostingAndSupportPlan(freePlan)
		return freePlanView, freePlanView, true
	}
	if selectedPlan.ID == 0 && len(plans) > 0 {
		selectedPlan = plans[len(plans)-1]
	}
	return publicTrialPlanViewFromHostingAndSupportPlan(selectedPlan), publicTrialPlanViewFromHostingAndSupportPlan(freePlan), false
}

func publicTrialPlanMessage(translations map[string]string, preview publicTrialPreview) string {
	if preview.SinglePageRequired {
		return translationOrDefault(translations, "public_trial_single_page_required", "The website is larger than the free test-drive limit. Stop scanning the website and copy only its first page.")
	}
	if preview.FitsFreePlan {
		return translationOrDefault(translations, "public_trial_free_result", "Great – this website can be launched on the free SiteBrush plan.")
	}
	return translationOrDefault(translations, "public_trial_oversize_result", "This website is larger than the free plan. You can still test its first page free for 24 hours.")
}

func publicTrialSourceErrorText(translations map[string]string, err error) string {
	errorPrefix := translationOrDefault(translations, "public_trial_load_failed", "Website analysis failed.")
	if err == nil {
		return errorPrefix
	}
	errorText := strings.TrimSpace(err.Error())
	if sourceStatus := strings.TrimSpace(strings.TrimPrefix(errorText, "source page returned ")); sourceStatus != errorText && sourceStatus != "" {
		return errorPrefix + " HTTP " + strings.TrimPrefix(sourceStatus, "HTTP ")
	}
	return errorPrefix + " " + errorText
}

func publicTrialFreePlanForMessage(preview publicTrialPreview) (publicTrialPlanView, bool) {
	if preview.FreePlan.ID > 0 {
		return preview.FreePlan, true
	}
	return publicTrialPlanView{}, false
}

func publicTrialPlanViewFromHostingAndSupportPlan(plan hostingandsupport.Plan) publicTrialPlanView {
	return publicTrialPlanView{ID: plan.ID, Name: plan.Name, QuotaBytes: plan.QuotaBytes, QuotaLabel: plan.QuotaLabel, IsFree: planIsFree(plan)}
}

func publicTrialResourceCountsFromResources(resources []grabResourcePreview) publicTrialResourceCounts {
	var counts publicTrialResourceCounts
	for _, resource := range resources {
		switch strings.ToLower(strings.TrimSpace(resource.Kind)) {
		case "image":
			counts.Images++
		case "css", "style", "stylesheet":
			counts.CSS++
		case "js", "javascript", "script":
			counts.JS++
		default:
			counts.Other++
		}
	}
	return counts
}

func publicTrialResourceURLMap(resources []grabResourcePreview) map[string]struct{} {
	resourceURLs := make(map[string]struct{})
	for _, resource := range resources {
		resourceURL := strings.TrimSpace(resource.URL)
		if resourceURL != "" {
			resourceURLs[resourceURL] = struct{}{}
		}
	}
	return resourceURLs
}

func publicTrialSelectedResources(resources []grabResourcePreview, selectedResourceURLs map[string]struct{}) []grabResourcePreview {
	if len(selectedResourceURLs) == 0 {
		return nil
	}
	selectedResources := make([]grabResourcePreview, 0, len(resources))
	for _, resource := range resources {
		resourceURL := strings.TrimSpace(resource.URL)
		if _, selected := selectedResourceURLs[resourceURL]; selected {
			selectedResources = append(selectedResources, resource)
		}
	}
	return selectedResources
}

func (a *App) preparePublicTrialPreviewForCreate(ctx context.Context, preview publicTrialPreview, selectedResourceURLs map[string]struct{}, progressToken string) publicTrialPreview {
	selectedResources := publicTrialSelectedResources(preview.Resources, selectedResourceURLs)
	remoteSourceURL, parseErr := url.Parse(preview.SourceURL)
	if parseErr != nil || remoteSourceURL.Hostname() == "" {
		preview.Resources = selectedResources
		preview.ResourceCount = len(selectedResources)
		preview.ResourceCounts = publicTrialResourceCountsFromResources(selectedResources)
		return preview
	}
	spider := newPageSpider("", remoteSourceURL, grabResourceMaxDepth, a.grabTracker, progressToken, preview.SourceOptions)
	spider.setContext(ctx)
	spider.publicAssetBasePath = "/"
	spider.selectedResourceURLs = selectedResourceURLs
	spider.setDownloadPlan(len(preview.ImportedPages)+len(selectedResources), publicTrialPreviewSelectedBytes(preview.ImportedPages, selectedResources))
	spider.documentURLRewriter = func(normalizedURL string) (string, bool) {
		parsedURL, err := url.Parse(normalizedURL)
		if err != nil || !crawler.SameHost(remoteSourceURL, parsedURL) || !crawler.IsPageURL(parsedURL) {
			return "", false
		}
		return crawler.WholeSiteLocalLink("/", remoteSourceURL, parsedURL), true
	}
	importedPages := make([]wholeSiteImportedPage, 0, len(preview.ImportedPages))
	for _, importedPage := range preview.ImportedPages {
		pageSourceURL, err := url.Parse(importedPage.SourceURL)
		if err != nil || pageSourceURL.Hostname() == "" {
			pageSourceURL = remoteSourceURL
		}
		rootResource := &mirroredResource{url: pageSourceURL.String(), content: []byte(importedPage.HTML)}
		spider.resources[pageSourceURL.String()] = rootResource
		spider.rewriteNestedResources(rootResource, 0, "text/html")
		importedPages = append(importedPages, wholeSiteImportedPage{SourceURL: importedPage.SourceURL, LocalPath: importedPage.LocalPath, HTML: string(rootResource.content)})
		spider.downloadedTotal++
		spider.publishResourceProgress("downloaded", pageSourceURL.String(), 100, int64(len(importedPage.HTML)), int64(len(importedPage.HTML)))
	}
	spider.retryFailedResources(remoteSourceURL, grabImportFailedResourceRetryAttempts)
	spider.rewriteImportedPagesStaticURLTextReferences(importedPages)
	requiredBytes := publicTrialPreviewSelectedBytes(importedPages, selectedResources)
	plan, freePlan, fitsFreePlan := a.smallestPublicTrialPlan(ctx, requiredBytes)
	preview.ImportedPages = importedPages
	preview.Resources = selectedResources
	preview.Spider = spider
	preview.ResourceCount = len(selectedResources)
	preview.ResourceCounts = publicTrialResourceCountsFromResources(selectedResources)
	preview.TotalBytes = requiredBytes
	preview.RequiredBytes = requiredBytes
	preview.Plan = plan
	preview.FreePlan = freePlan
	preview.FitsFreePlan = fitsFreePlan
	return preview
}

func publicTrialPreviewSelectedBytes(importedPages []wholeSiteImportedPage, resources []grabResourcePreview) int64 {
	var totalBytes int64
	for _, importedPage := range importedPages {
		totalBytes += int64(len([]byte(importedPage.HTML)))
	}
	totalBytes += sumGrabPreviewResourceBytes(resources)
	return totalBytes
}

func (a *App) availablePublicTrialDomain(ctx context.Context, sourceURL, parentDomain string) (string, error) {
	parentDomain = normalizeDomainName(parentDomain)
	if parentDomain == "" {
		return "", errors.New("owner domain is required")
	}
	baseLabel := publicTrialSubdomainLabel(sourceURL)
	if baseLabel != "" {
		for suffix := 0; suffix < 10; suffix++ {
			label := baseLabel
			if suffix > 0 {
				label = fmt.Sprintf("%s%d", baseLabel, suffix+1)
			}
			candidateDomain := label + "." + parentDomain
			if a.publicTrialDomainAvailable(ctx, candidateDomain) {
				return candidateDomain, nil
			}
		}
	}
	for attempt := 0; attempt < 20; attempt++ {
		candidateDomain := randomPublicTrialSubdomain() + "." + parentDomain
		if a.publicTrialDomainAvailable(ctx, candidateDomain) {
			return candidateDomain, nil
		}
	}
	return "", errors.New("trial domain is unavailable")
}

func publicTrialSubdomainLabel(sourceURL string) string {
	parsedURL, err := url.Parse(sourceURL)
	if err != nil {
		return ""
	}
	host := normalizeDomainName(parsedURL.Hostname())
	if host == "" {
		return ""
	}
	parts := strings.Split(host, ".")
	if len(parts) < 2 {
		return ""
	}
	label := parts[len(parts)-2]
	if label == "co" || label == "com" || label == "net" || label == "org" {
		label = parts[0]
	}
	return safePublicTrialLabel(label)
}

func safePublicTrialLabel(rawLabel string) string {
	var builder strings.Builder
	for _, labelRune := range strings.ToLower(strings.TrimSpace(rawLabel)) {
		if (labelRune >= 'a' && labelRune <= 'z') || (labelRune >= '0' && labelRune <= '9') {
			builder.WriteRune(labelRune)
			continue
		}
		if labelRune == '-' && builder.Len() > 0 {
			builder.WriteByte('-')
		}
	}
	label := strings.Trim(builder.String(), "-")
	if len(label) > 24 {
		label = strings.Trim(label[:24], "-")
	}
	return label
}

func randomPublicTrialSubdomain() string {
	token := strings.ToLower(randomAccessToken())
	label := strings.NewReplacer("-", "", "_", "").Replace(token)
	if len(label) > 4 {
		label = label[:4]
	}
	if len(label) < 4 {
		label = "k7m2"
	}
	return label
}

func (a *App) publicTrialDomainAvailable(ctx context.Context, domain string) bool {
	domain = normalizeDomainName(domain)
	if domain == "" {
		return false
	}
	databasePath := filepath.Join(siteDatabaseRootPath(a.serverControlDBPath()), domainStorageName(domain)+".db")
	realDatabasePath, pathErr := a.writablePathInsideStorage(databasePath)
	if pathErr != nil {
		return false
	}
	if _, err := os.Stat(realDatabasePath); err == nil {
		return false
	}
	var userCount int
	_ = a.db.QueryRowContext(contextWithDomain(ctx, domain), `SELECT COUNT(1) FROM users WHERE domain=?`, domain).Scan(&userCount)
	return userCount == 0
}

func (a *App) createManagedSiteWithoutAdmin(ctx context.Context, domain string, quotaBytes int64) error {
	siteDatabasePath := filepath.Join(siteDatabaseRootPath(a.serverControlDBPath()), domainStorageName(domain)+".db")
	realSiteDatabasePath, pathErr := a.writablePathInsideStorage(siteDatabasePath)
	if pathErr != nil {
		return pathErr
	}
	if _, statErr := os.Stat(realSiteDatabasePath); statErr == nil {
		return fmt.Errorf("site database for %s already exists", domain)
	} else if !errors.Is(statErr, os.ErrNotExist) {
		return statErr
	}
	if err := ensureParentDir(realSiteDatabasePath); err != nil {
		return err
	}
	rawDatabase, err := sql.Open("sqlite", "file:"+realSiteDatabasePath)
	if err != nil {
		return err
	}
	created := false
	defer func() {
		_ = rawDatabase.Close()
		if !created {
			_ = os.Remove(realSiteDatabasePath)
		}
	}()
	siteApplication := &App{db: rawDatabase, storagePath: a.storagePath, storageRealRoot: a.storageRealRoot, dbPath: a.serverControlDBPath(), debug: a.debug}
	siteContext := contextWithDomain(ctx, domain)
	if err := siteApplication.migrate(siteContext); err != nil {
		return err
	}
	siteApplication.ensureDomainStorageUsageRow(siteContext, domain)
	_, err = rawDatabase.ExecContext(siteContext, `UPDATE domain_storage_usage SET limit_bytes=?, updated_at=? WHERE domain=?`, quotaBytes, time.Now().UTC().Format(time.RFC3339), domain)
	created = err == nil
	return err
}

func (a *App) persistPublicTrialPreview(ctx context.Context, domain string, preview publicTrialPreview) error {
	if len(preview.ImportedPages) == 0 {
		return errors.New("preview is empty")
	}
	if preview.Spider != nil {
		preview.Spider.domain = domain
	}
	pageDelta, publishedPageDelta, revisionDelta, publishedStaticDelta := a.estimateImportedPagesStorageDelta(ctx, domain, preview.ImportedPages)
	fileDelta := a.estimateImportedFileDelta(domain, preview.Spider)
	if storageErr := a.applyDomainStorageDelta(ctx, domain, pageDelta, publishedPageDelta, revisionDelta, fileDelta, publishedStaticDelta); storageErr != nil {
		return storageErr
	}
	if persistErr := a.persistSpiderAssets(ctx, preview.Spider, "/"); persistErr != nil {
		_ = a.applyDomainStorageDelta(ctx, domain, -pageDelta, -publishedPageDelta, -revisionDelta, -fileDelta, -publishedStaticDelta)
		return persistErr
	}
	if storeErr := a.storeWholeSiteImportedPages(ctx, domain, preview.ImportedPages); storeErr != nil {
		_ = a.applyDomainStorageDelta(ctx, domain, -pageDelta, -publishedPageDelta, -revisionDelta, -fileDelta, -publishedStaticDelta)
		return storeErr
	}
	a.rebuildDomainStorageUsage(ctx, domain)
	return nil
}

func (a *App) retryImportedPageResources(ctx context.Context, importRequest grabImportRequest) (grabImportResult, error) {
	if importRequest.RemoteSourceURL == nil || len(importRequest.SelectedResourceURLs) == 0 {
		return grabImportResult{RedirectPath: cleanPath(importRequest.PagePath)}, nil
	}
	spider := newPageSpider(importRequest.Domain, importRequest.RemoteSourceURL, grabResourceMaxDepth, a.grabTracker, importRequest.ProgressToken, importRequest.SourceOptions)
	spider.setContext(importRequest.Context)
	spider.setDownloadPlan(importRequest.DownloadTotal, importRequest.DownloadTotalBytes)
	spider.selectedResourceURLs = importRequest.SelectedResourceURLs
	spider.publicAssetBasePath = cleanPath(importRequest.PagePath)
	resourceURLs := make([]string, 0, len(importRequest.SelectedResourceURLs))
	for resourceURL := range importRequest.SelectedResourceURLs {
		resourceURLs = append(resourceURLs, resourceURL)
	}
	sort.Strings(resourceURLs)
	for _, resourceURL := range resourceURLs {
		_, _ = spider.fetchResource(resourceURL, importRequest.RemoteSourceURL, 0, true)
	}
	spider.retryFailedResources(importRequest.RemoteSourceURL, grabImportFailedResourceRetryAttempts)
	replacements := importedResourceReplacements(spider)
	fileDelta := a.estimateImportedFileDelta(importRequest.Domain, spider)
	domainContext := contextWithDomain(ctx, importRequest.Domain)
	pageDelta, publishedPageDelta, publishedStaticDelta := a.estimateRetriedResourcePageDelta(domainContext, importRequest.Domain, replacements)
	if storageErr := a.applyDomainStorageDelta(domainContext, importRequest.Domain, pageDelta, publishedPageDelta, 0, fileDelta, publishedStaticDelta); storageErr != nil {
		return grabImportResult{RedirectPath: cleanPath(importRequest.PagePath), FailedTotal: spider.unresolvedFailedTotal(), FailedURLs: spider.failedResourceURLList(), FailedReasons: spider.failedResourceReasonMap()}, storageErr
	}
	if persistErr := a.persistSpiderAssets(domainContext, spider, importRequest.PagePath); persistErr != nil {
		_ = a.applyDomainStorageDelta(domainContext, importRequest.Domain, -pageDelta, -publishedPageDelta, 0, -fileDelta, -publishedStaticDelta)
		return grabImportResult{RedirectPath: cleanPath(importRequest.PagePath), FailedTotal: spider.unresolvedFailedTotal(), FailedURLs: spider.failedResourceURLList(), FailedReasons: spider.failedResourceReasonMap()}, persistErr
	}
	a.applyRetriedResourcePageReplacements(domainContext, importRequest.Domain, replacements)
	a.rebuildDomainStorageUsage(domainContext, importRequest.Domain)
	if a.grabTracker != nil && importRequest.ProgressToken != "" {
		stage := "done"
		if spider.unresolvedFailedTotal() > 0 {
			stage = "partial"
		}
		a.grabTracker.publish(spider.finalProgressEvent(importRequest.ProgressToken, stage))
	}
	return grabImportResult{RedirectPath: cleanPath(importRequest.PagePath), FailedTotal: spider.unresolvedFailedTotal(), FailedURLs: spider.failedResourceURLList(), FailedReasons: spider.failedResourceReasonMap()}, nil
}

func (a *App) grabPreview(w http.ResponseWriter, r *http.Request) {
	startedAt := time.Now()
	if !a.isAdminRequest(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	sourceURL := r.FormValue("source_url")
	if sourceURL == "" {
		http.Error(w, "source_url is required", http.StatusBadRequest)
		return
	}
	sourceOptions, err := parseGrabSourceOptions(r)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	remoteSourceURL, err := parseGrabSourceURLForServerIP(sourceURL, sourceOptions.IP)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	sourceURL = remoteSourceURL.String()
	htmlBytes, resolvedSourceURL, err := downloadGrabSourceHTMLWithResolvedURL(sourceURL, sourceOptions)
	if err != nil {
		a.logProblemEvent("grab preview failed source=%s error=%v duration=%s", sourceURL, err, time.Since(startedAt).String())
		http.Error(w, err.Error(), http.StatusBadGateway)
		return
	}
	remoteSourceURL = resolvedSourceURL
	sourceURL = remoteSourceURL.String()
	progressToken := strings.TrimSpace(r.FormValue("progress_token"))
	domain := a.siteDomain(r.Context(), r)
	pagePath := grabRequestTargetPath(r)
	var resources []grabResourcePreview
	pageCount := 1
	var importedPages []wholeSiteImportedPage
	var pageDownloadBytes int64
	var previewSpider *pageSpider
	if grabCopyWholeSite(r) {
		wholeSitePreview := previewWholeRemoteSiteResources(r.Context(), remoteSourceURL, string(htmlBytes), pagePath, a.grabTracker, progressToken, sourceOptions)
		resources = wholeSitePreview.Resources
		pageCount = wholeSitePreview.PageCount
		importedPages = wholeSitePreview.ImportedPages
		previewSpider = wholeSitePreview.Spider
	} else {
		previewSpider, importedHTML := prepareSinglePageImport(grabImportRequest{Domain: domain, PagePath: pagePath, SourceURL: sourceURL, RemoteSourceURL: remoteSourceURL, HTML: string(htmlBytes), ProgressToken: progressToken, SourceOptions: sourceOptions}, a.grabTracker)
		resources = previewResourcesFromSpider(previewSpider, map[string]struct{}{sourceURL: {}})
		importedPages = []wholeSiteImportedPage{{SourceURL: sourceURL, LocalPath: pagePath, HTML: importedHTML}}
	}
	for _, importedPage := range importedPages {
		pageDownloadBytes += int64(len([]byte(importedPage.HTML)))
	}
	selectedResourceBytes := sumGrabPreviewResourceBytes(resources)
	quotaEstimate := a.estimateImportQuota(r.Context(), domain, importedPages, previewSpider)
	w.Header().Set("Content-Type", "application/json")
	encodeErr := json.NewEncoder(w).Encode(grabPreviewResponse{
		SourceURL:             remoteSourceURL.String(),
		PageCount:             pageCount,
		ResourceCount:         len(resources),
		Resources:             resources,
		DownloadTotal:         pageCount + len(resources),
		DownloadTotalBytes:    pageDownloadBytes + selectedResourceBytes,
		PageDownloadBytes:     pageDownloadBytes,
		PageStorageBytes:      quotaEstimate.PageStorageBytes,
		CurrentUsedBytes:      quotaEstimate.CurrentUsedBytes,
		LimitBytes:            quotaEstimate.LimitBytes,
		FreeBytes:             quotaEstimate.FreeBytes,
		SelectedResourceBytes: selectedResourceBytes,
		EstimatedImportBytes:  quotaEstimate.EstimatedImportBytes,
		ProjectedUsedBytes:    quotaEstimate.ProjectedUsedBytes,
		FitsQuota:             quotaEstimate.FitsQuota,
	})
	if encodeErr != nil {
		a.logProblemEvent("grab preview response failed source=%s error=%v duration=%s", sourceURL, encodeErr, time.Since(startedAt).String())
	}
	if encodeErr == nil && a.grabTracker != nil && progressToken != "" && previewSpider != nil {
		a.grabTracker.publish(previewSpider.finalProgressEvent(progressToken, "done"))
	}
}

func parseGrabSourceURL(sourceURL string) (*url.URL, error) {
	return parseGrabSourceURLForServerIP(sourceURL, "")
}

func grabRequestTargetPath(r *http.Request) string {
	rawPath := strings.TrimSpace(r.FormValue("path"))
	if rawPath == "" {
		rawPath = r.URL.Path
	}
	return cleanPath(rawPath)
}

func parseGrabSourceURLForServerIP(sourceURL, sourceIP string) (*url.URL, error) {
	trimmedSourceURL := strings.TrimSpace(sourceURL)
	if trimmedSourceURL == "" {
		return nil, errors.New("source_url is required")
	}
	sourceIPPort := grabSourceIPPort(sourceIP)
	if strings.HasPrefix(trimmedSourceURL, "//") {
		trimmedSourceURL = "https:" + trimmedSourceURL
	}
	if !strings.Contains(trimmedSourceURL, "://") {
		trimmedSourceURL = defaultGrabSchemeForServerIP(trimmedSourceURL, sourceIP) + "://" + trimmedSourceURL
	}
	remoteSourceURL, err := url.Parse(trimmedSourceURL)
	if err != nil || remoteSourceURL.Hostname() == "" || (remoteSourceURL.Scheme != "http" && remoteSourceURL.Scheme != "https") {
		return nil, errors.New("source_url is invalid")
	}
	if err := outboundhttp.RequirePublicURL(remoteSourceURL); err != nil {
		return nil, err
	}
	if sourceIPPort != "" {
		remoteSourceURL.Host = net.JoinHostPort(remoteSourceURL.Hostname(), sourceIPPort)
	}
	return remoteSourceURL, nil
}

func defaultGrabScheme(sourceURL string) string {
	return defaultGrabSchemeForServerIP(sourceURL, "")
}

func defaultGrabSchemeForServerIP(sourceURL, sourceIP string) string {
	sourceIPPort := grabSourceIPPort(sourceIP)
	if sourceIPPort == "443" {
		return "https"
	}
	if sourceIPPort != "" {
		return "http"
	}
	if strings.TrimSpace(sourceIP) != "" {
		return "https"
	}
	hostCandidate := sourceURL
	if slashIndex := strings.Index(hostCandidate, "/"); slashIndex >= 0 {
		hostCandidate = hostCandidate[:slashIndex]
	}
	if colonIndex := strings.LastIndex(hostCandidate, ":"); colonIndex >= 0 {
		hostCandidate = hostCandidate[:colonIndex]
	}
	if hostCandidate == "localhost" || net.ParseIP(hostCandidate) != nil {
		return "http"
	}
	return "https"
}

func parseOptionalGrabSourceIP(rawSourceIP string) (string, error) {
	trimmedSourceIP := strings.TrimSpace(rawSourceIP)
	if trimmedSourceIP == "" {
		return "", nil
	}
	parsedIP, portPart := splitGrabSourceIP(trimmedSourceIP)
	if parsedIP == nil {
		return "", errors.New("source_ip is invalid")
	}
	if !outboundhttp.IPAllowed(parsedIP) {
		return "", errors.New("source_ip must be a public network address")
	}
	if portPart == "" {
		return parsedIP.String(), nil
	}
	parsedPort, err := strconv.Atoi(strings.TrimSpace(portPart))
	if err != nil || parsedPort <= 0 || parsedPort > 65535 {
		return "", errors.New("source_ip port is invalid")
	}
	return net.JoinHostPort(parsedIP.String(), strconv.Itoa(parsedPort)), nil
}

func parseGrabSourceOptions(r *http.Request) (grabSourceOptions, error) {
	sourceIP, err := parseOptionalGrabSourceIP(r.FormValue("source_ip"))
	if err != nil {
		return grabSourceOptions{}, err
	}
	languageCode, err := parseOptionalGrabSourceLanguage(r.FormValue("source_language"))
	if err != nil {
		return grabSourceOptions{}, err
	}
	return grabSourceOptions{IP: sourceIP, LanguageCode: languageCode}, nil
}

func parseOptionalGrabSourceLanguage(rawLanguage string) (string, error) {
	languageCode := strings.ToLower(strings.TrimSpace(rawLanguage))
	if languageCode == "" || languageCode == "auto" {
		return "", nil
	}
	for _, supportedLanguageCode := range supportedGrabSourceLanguageCodes() {
		if languageCode == supportedLanguageCode {
			return languageCode, nil
		}
	}
	return "", errors.New("source_language is invalid")
}

func supportedGrabSourceLanguageCodes() []string {
	return []string{"en", "fr", "ru", "ja", "it", "sv", "fi", "mn", "zh", "he", "fa", "de", "tr", "kk", "es", "pt"}
}

func grabSourceAcceptLanguage(languageCode string) string {
	languageCode = strings.ToLower(strings.TrimSpace(languageCode))
	if languageCode == "" {
		return ""
	}
	regionTags := map[string]string{
		"en": "en-US", "fr": "fr-FR", "ru": "ru-RU", "ja": "ja-JP",
		"it": "it-IT", "sv": "sv-SE", "fi": "fi-FI", "mn": "mn-MN",
		"zh": "zh-CN", "he": "he-IL", "fa": "fa-IR", "de": "de-DE",
		"tr": "tr-TR", "kk": "kk-KZ", "es": "es-ES", "pt": "pt-PT",
	}
	regionTag, found := regionTags[languageCode]
	if !found {
		return languageCode
	}
	fallbackCode := "en"
	if languageCode == "en" {
		fallbackCode = "ru"
	}
	return languageCode + "," + regionTag + ";q=0.9," + fallbackCode + ";q=0.5,*;q=0.1"
}

func wantsJSONResponse(r *http.Request) bool {
	return strings.Contains(strings.ToLower(r.Header.Get("Accept")), "application/json")
}

func readRequestBodyWithLimit(reader io.Reader, limitBytes int64) ([]byte, error) {
	return readAllWithLimit(reader, limitBytes)
}

func readAllWithLimit(reader io.Reader, limitBytes int64) ([]byte, error) {
	if limitBytes <= 0 {
		return io.ReadAll(reader)
	}
	requestBody, err := io.ReadAll(io.LimitReader(reader, limitBytes+1))
	if err != nil {
		return nil, err
	}
	if int64(len(requestBody)) > limitBytes {
		return nil, errReadLimitExceeded
	}
	return requestBody, nil
}

func copyWithLimit(writer io.Writer, reader io.Reader, limitBytes int64) (int64, error) {
	if limitBytes <= 0 {
		return io.Copy(writer, reader)
	}
	limitedReader := &io.LimitedReader{R: reader, N: limitBytes + 1}
	writtenBytes, err := io.Copy(writer, limitedReader)
	if err != nil {
		return writtenBytes, err
	}
	if writtenBytes > limitBytes {
		return writtenBytes, errReadLimitExceeded
	}
	return writtenBytes, nil
}

func publicTrialGrabSourceOptions() grabSourceOptions {
	return grabSourceOptions{}
}

func downloadGrabSourceHTML(sourceURL, sourceIP string) ([]byte, error) {
	htmlBytes, _, err := downloadGrabSourceHTMLWithResolvedURL(sourceURL, grabSourceOptions{IP: sourceIP})
	return htmlBytes, err
}

func downloadGrabSourceHTMLWithResolvedURL(sourceURL string, sourceOptions grabSourceOptions) ([]byte, *url.URL, error) {
	return downloadGrabSourceHTMLWithResolvedURLContext(context.Background(), sourceURL, sourceOptions)
}

func downloadGrabSourceHTMLWithResolvedURLContext(ctx context.Context, sourceURL string, sourceOptions grabSourceOptions) ([]byte, *url.URL, error) {
	remoteSourceURL, err := url.Parse(sourceURL)
	if err != nil {
		return nil, nil, errors.New("source_url is invalid")
	}
	if err := outboundhttp.RequirePublicURL(remoteSourceURL); err != nil {
		return nil, nil, err
	}
	client := newGrabHTTPClientForSourceOptions(remoteSourceURL.Hostname(), sourceOptions)
	lastStatus := ""
	downloadResult, err := crawler.DownloadHTMLPageWithRetriesContext(ctx, client, remoteSourceURL, func(request *http.Request) {
		applyGrabRequestHeaders(request, sourceOptions)
		applyGrabHTMLRequestHeaders(request)
	}, crawler.HTMLDownloadRetryOptions{
		Attempts: 2,
		Delay:    1500 * time.Millisecond,
	})
	if err == nil && downloadResult.IsHTML {
		logImportedHTMLDecodeDecision(remoteSourceURL, downloadResult)
		downloadedHTML := rewriteImportedHTMLCharsetDeclaration(downloadResult.HTML)
		if isSitebrushMissingPageHTML(downloadedHTML) {
			return nil, downloadResult.ResolvedURL, errors.New("source page is a SiteBrush 404 page")
		}
		return []byte(downloadedHTML), downloadResult.ResolvedURL, nil
	}
	if downloadResult.Status != "" {
		lastStatus = downloadResult.Status
	}
	if shouldFallbackGrabSourceToHTTP(remoteSourceURL) {
		fallbackURL := crawler.CloneURL(remoteSourceURL)
		fallbackURL.Scheme = "http"
		fallbackURL.Host = fallbackURL.Hostname()
		downloadResult, err = crawler.DownloadHTMLPageWithRetriesContext(ctx, client, fallbackURL, func(request *http.Request) {
			applyGrabRequestHeaders(request, sourceOptions)
			applyGrabHTMLRequestHeaders(request)
		}, crawler.HTMLDownloadRetryOptions{
			Attempts: 2,
			Delay:    1500 * time.Millisecond,
		})
		if err == nil && downloadResult.IsHTML {
			logImportedHTMLDecodeDecision(fallbackURL, downloadResult)
			downloadedHTML := rewriteImportedHTMLCharsetDeclaration(downloadResult.HTML)
			if isSitebrushMissingPageHTML(downloadedHTML) {
				return nil, downloadResult.ResolvedURL, errors.New("source page is a SiteBrush 404 page")
			}
			return []byte(downloadedHTML), downloadResult.ResolvedURL, nil
		}
		if downloadResult.Status != "" {
			lastStatus = downloadResult.Status
		}
	}
	if strings.TrimSpace(lastStatus) != "" {
		return nil, nil, fmt.Errorf("source page returned %s", lastStatus)
	}
	if err != nil {
		return nil, nil, errors.New("failed to download source page")
	}
	return nil, nil, errors.New("source page did not return a public HTML page")
}

func decodeImportedHTMLBytes(htmlBytes []byte, contentType string) string {
	decodedHTML := crawler.DecodeHTML(htmlBytes, contentType)
	return rewriteImportedHTMLCharsetDeclaration(decodedHTML.Text)
}

func logImportedHTMLDecodeDecision(requestedURL *url.URL, downloadResult crawler.HTMLDownloadResult) {
	if downloadResult.EncodingCertain {
		return
	}
	encodingURL := requestedURL
	if downloadResult.ResolvedURL != nil {
		encodingURL = downloadResult.ResolvedURL
	}
	encodingURLText := ""
	if encodingURL != nil {
		encodingURLText = encodingURL.String()
	}
	log.Printf(
		"IMPORT uncertain character encoding url=%q encoding=%q source=%q",
		encodingURLText,
		downloadResult.Encoding,
		downloadResult.EncodingSource,
	)
}

func decodeImportedResourceBytes(resourceURL string, resourceBytes []byte, responseContentType, resourceContentType string) []byte {
	if isImportedHTMLContentType(resourceContentType) {
		return []byte(decodeImportedHTMLBytes(resourceBytes, responseContentType))
	}
	if !isImportedTextResource(resourceURL, responseContentType, resourceContentType) {
		return resourceBytes
	}
	decodedResource := crawler.DecodeText(resourceBytes, responseContentType)
	resourceText := decodedResource.Text
	if isImportedCSSResource(resourceURL, resourceContentType) {
		resourceText = rewriteImportedCSSCharsetDeclaration(resourceText, decodedResource.Encoding != "" && decodedResource.Encoding != "utf-8")
	}
	return []byte(resourceText)
}

func rewriteImportedHTMLCharsetDeclaration(htmlSource string) string {
	tokenizer := html.NewTokenizer(strings.NewReader(htmlSource))
	var rewrittenSource strings.Builder
	rewrittenSource.Grow(len(htmlSource) + 64)
	charsetDeclarationFound := false
	consumedSourceBytes := 0
	for {
		tokenType := tokenizer.Next()
		if tokenType == html.ErrorToken {
			rewrittenSource.WriteString(htmlSource[consumedSourceBytes:])
			break
		}
		rawToken := string(tokenizer.Raw())
		consumedSourceBytes += len(rawToken)
		if tokenType != html.StartTagToken && tokenType != html.SelfClosingTagToken {
			rewrittenSource.WriteString(rawToken)
			continue
		}
		currentToken := tokenizer.Token()
		if !strings.EqualFold(currentToken.Data, "meta") {
			rewrittenSource.WriteString(rawToken)
			continue
		}
		rewrittenToken, found := rewriteImportedHTMLMetaCharset(currentToken)
		if found {
			charsetDeclarationFound = true
			rewrittenSource.WriteString(rewrittenToken.String())
			continue
		}
		rewrittenSource.WriteString(rawToken)
	}

	rewrittenHTML := rewrittenSource.String()
	if charsetDeclarationFound {
		return rewrittenHTML
	}
	metaCharsetTag := `<meta charset="utf-8">`
	if headOpenMatch := importedHTMLHeadOpenPattern.FindStringIndex(rewrittenHTML); headOpenMatch != nil {
		return rewrittenHTML[:headOpenMatch[1]] + metaCharsetTag + rewrittenHTML[headOpenMatch[1]:]
	}
	if htmlOpenMatch := importedHTMLHTMLOpenPattern.FindStringIndex(rewrittenHTML); htmlOpenMatch != nil {
		return rewrittenHTML[:htmlOpenMatch[1]] + `<head>` + metaCharsetTag + `</head>` + rewrittenHTML[htmlOpenMatch[1]:]
	}
	return metaCharsetTag + rewrittenHTML
}

func rewriteImportedHTMLMetaCharset(metaToken html.Token) (html.Token, bool) {
	httpEquivContentType := false
	for _, attribute := range metaToken.Attr {
		if strings.EqualFold(attribute.Key, "http-equiv") && strings.EqualFold(strings.TrimSpace(attribute.Val), "content-type") {
			httpEquivContentType = true
			break
		}
	}

	for attributeIndex := range metaToken.Attr {
		attribute := &metaToken.Attr[attributeIndex]
		switch {
		case strings.EqualFold(attribute.Key, "charset"):
			attribute.Val = "utf-8"
			return metaToken, true
		case httpEquivContentType && strings.EqualFold(attribute.Key, "content"):
			if importedMetaContentCharsetPattern.MatchString(attribute.Val) {
				attribute.Val = importedMetaContentCharsetPattern.ReplaceAllString(attribute.Val, "${1}${2}utf-8")
			} else {
				attribute.Val = strings.TrimSpace(attribute.Val) + "; charset=utf-8"
			}
			return metaToken, true
		}
	}
	if httpEquivContentType {
		metaToken.Attr = append(metaToken.Attr, html.Attribute{Key: "charset", Val: "utf-8"})
		return metaToken, true
	}
	return metaToken, false
}

func rewriteImportedCSSCharsetDeclaration(cssSource string, addIfMissing bool) string {
	rewrittenCSS := importedCSSCharsetAssignmentPattern.ReplaceAllString(cssSource, `${1}utf-8${2}`)
	if rewrittenCSS != cssSource || !addIfMissing {
		return rewrittenCSS
	}
	return `@charset "utf-8";` + "\n" + strings.TrimPrefix(rewrittenCSS, "\uFEFF")
}

func isImportedHTMLContentType(contentType string) bool {
	return contentType == "text/html" || contentType == "application/xhtml+xml"
}

func isImportedTextResource(resourceURL, responseContentType, resourceContentType string) bool {
	normalizedResponseContentType := crawler.NormalizedResourceContentType(responseContentType)
	effectiveResourceContentType := crawler.NormalizedResourceContentType(resourceContentType)
	if strings.HasPrefix(normalizedResponseContentType, "text/") || strings.HasPrefix(effectiveResourceContentType, "text/") {
		return true
	}
	if strings.Contains(normalizedResponseContentType, "javascript") || strings.Contains(normalizedResponseContentType, "ecmascript") || strings.Contains(effectiveResourceContentType, "javascript") || strings.Contains(effectiveResourceContentType, "ecmascript") {
		return true
	}
	switch normalizedResponseContentType {
	case "application/json", "application/manifest+json", "application/ld+json", "application/xml", "application/rss+xml", "application/atom+xml", "image/svg+xml":
		return true
	}
	switch crawler.ResourceExtension(resourceURL) {
	case ".css", ".js", ".mjs", ".cjs", ".json", ".map", ".xml", ".svg", ".txt", ".text", ".md", ".markdown", ".csv", ".tsv", ".yaml", ".yml", ".toml", ".ini", ".cfg", ".conf", ".webmanifest", ".htm", ".html", ".xhtml":
		return true
	default:
		return false
	}
}

func isImportedCSSResource(resourceURL, resourceContentType string) bool {
	return crawler.NormalizedResourceContentType(resourceContentType) == "text/css" || crawler.ResourceExtension(resourceURL) == ".css"
}

func isSuccessfulGrabResponse(response *http.Response) bool {
	return response != nil && response.StatusCode >= 200 && response.StatusCode <= 299
}

func doGrabGET(client *http.Client, rawURL string, sourceOptions grabSourceOptions) (*http.Response, error) {
	return doGrabGETContext(context.Background(), client, rawURL, sourceOptions)
}

func doGrabGETContext(ctx context.Context, client *http.Client, rawURL string, sourceOptions grabSourceOptions) (*http.Response, error) {
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		return nil, err
	}
	if err := outboundhttp.RequirePublicURL(parsedURL); err != nil {
		return nil, err
	}
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
	if err != nil {
		return nil, err
	}
	applyGrabRequestHeaders(request, sourceOptions)
	applyGrabHTMLRequestHeaders(request)
	return client.Do(request)
}

func applyGrabRequestHeaders(request *http.Request, sourceOptions grabSourceOptions) {
	request.Header.Set("User-Agent", "Mozilla/5.0 (compatible; SiteBrush/1.0)")
	acceptLanguage := grabSourceAcceptLanguage(sourceOptions.LanguageCode)
	if acceptLanguage != "" {
		request.Header.Set("Accept-Language", acceptLanguage)
	}
}

func applyGrabHTMLRequestHeaders(request *http.Request) {
	request.Header.Set("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8")
	request.Header.Set("Upgrade-Insecure-Requests", "1")
	request.Header.Set("DNT", "1")
}

func shouldFallbackGrabSourceToHTTP(sourceURL *url.URL) bool {
	return sourceURL != nil && sourceURL.Scheme == "https"
}

func grabSourceIPPort(sourceIP string) string {
	trimmedSourceIP := strings.TrimSpace(sourceIP)
	if trimmedSourceIP == "" {
		return ""
	}
	if _, port, splitErr := net.SplitHostPort(trimmedSourceIP); splitErr == nil {
		return port
	}
	return ""
}

func splitGrabSourceIP(sourceIP string) (net.IP, string) {
	trimmedSourceIP := strings.TrimSpace(sourceIP)
	ipPart := trimmedSourceIP
	portPart := ""
	if host, port, splitErr := net.SplitHostPort(trimmedSourceIP); splitErr == nil {
		ipPart = host
		portPart = port
	} else if strings.Count(trimmedSourceIP, ":") == 1 {
		host, port, foundPort := strings.Cut(trimmedSourceIP, ":")
		if foundPort {
			ipPart = host
			portPart = port
		}
	}
	return net.ParseIP(strings.Trim(ipPart, "[]")), strings.TrimSpace(portPart)
}

func selectedGrabResourceURLs(r *http.Request) map[string]struct{} {
	if strings.TrimSpace(r.FormValue("import_selection_confirmed")) == "" {
		return nil
	}
	selectedResourceURLs := make(map[string]struct{})
	for _, resourceURL := range r.Form["import_resource_url"] {
		trimmedResourceURL := strings.TrimSpace(resourceURL)
		if trimmedResourceURL == "" {
			continue
		}
		selectedResourceURLs[trimmedResourceURL] = struct{}{}
	}
	return selectedResourceURLs
}

func grabImportDownloadTotal(r *http.Request) int {
	return positiveFormInt(r, "import_download_total")
}

func grabImportDownloadTotalBytes(r *http.Request) int64 {
	return positiveFormInt64(r, "import_download_total_bytes")
}

func positiveFormInt(r *http.Request, fieldName string) int {
	parsedValue, err := strconv.Atoi(strings.TrimSpace(r.FormValue(fieldName)))
	if err != nil || parsedValue < 0 {
		return 0
	}
	return parsedValue
}

func positiveFormInt64(r *http.Request, fieldName string) int64 {
	parsedValue, err := strconv.ParseInt(strings.TrimSpace(r.FormValue(fieldName)), 10, 64)
	if err != nil || parsedValue < 0 {
		return 0
	}
	return parsedValue
}

func grabCopyWholeSite(r *http.Request) bool {
	rawValue := strings.ToLower(strings.TrimSpace(r.FormValue("copy_whole_site")))
	return rawValue == "1" || rawValue == "on" || rawValue == "true" || rawValue == "yes"
}

func sumGrabPreviewResourceBytes(resources []grabResourcePreview) int64 {
	var totalBytes int64
	for _, resource := range resources {
		if resource.SizeBytes <= 0 {
			continue
		}
		totalBytes += resource.SizeBytes
	}
	return totalBytes
}

type importQuotaEstimate struct {
	PageStorageBytes     int64
	ResourceBytes        int64
	EstimatedImportBytes int64
	CurrentUsedBytes     int64
	LimitBytes           int64
	FreeBytes            int64
	ProjectedUsedBytes   int64
	FitsQuota            bool
}

func (a *App) estimateImportQuota(ctx context.Context, domain string, importedPages []wholeSiteImportedPage, spider *pageSpider) importQuotaEstimate {
	pageDelta, publishedPageDelta, revisionDelta, publishedStaticDelta := a.estimateImportedPagesStorageDelta(ctx, domain, importedPages)
	resourceBytes := a.estimateImportedFileDelta(domain, spider)
	usage := a.domainStorageUsage(ctx, domain)
	currentUsedBytes := usage.totalBytes()
	estimatedImportBytes := pageDelta + publishedPageDelta + revisionDelta + publishedStaticDelta + resourceBytes
	projectedUsedBytes := currentUsedBytes + estimatedImportBytes
	freeBytes := usage.LimitBytes - currentUsedBytes
	return importQuotaEstimate{
		PageStorageBytes:     pageDelta + publishedPageDelta + revisionDelta + publishedStaticDelta,
		ResourceBytes:        resourceBytes,
		EstimatedImportBytes: estimatedImportBytes,
		CurrentUsedBytes:     currentUsedBytes,
		LimitBytes:           usage.LimitBytes,
		FreeBytes:            freeBytes,
		ProjectedUsedBytes:   projectedUsedBytes,
		FitsQuota:            projectedUsedBytes <= usage.LimitBytes,
	}
}

func previewGrabResources(pageURL *url.URL, htmlSource string, tracker *grabProgressTracker, progressToken string, sourceOptions grabSourceOptions) []grabResourcePreview {
	spider := newPreviewPageSpider("", pageURL, grabResourceMaxDepth, tracker, progressToken, sourceOptions)
	rootResource := &mirroredResource{url: pageURL.String(), content: []byte(htmlSource)}
	spider.resources[pageURL.String()] = rootResource
	spider.collectPreviewNestedResources(rootResource, 0, "text/html")
	resources := previewResourcesFromSpider(spider, map[string]struct{}{pageURL.String(): {}})
	if tracker != nil && strings.TrimSpace(progressToken) != "" {
		tracker.publish(spider.finalProgressEvent(progressToken, "done"))
	}
	return resources
}

func prepareSinglePageImport(importRequest grabImportRequest, tracker *grabProgressTracker) (*pageSpider, string) {
	spider := newPageSpider(importRequest.Domain, importRequest.RemoteSourceURL, grabResourceMaxDepth, tracker, importRequest.ProgressToken, importRequest.SourceOptions)
	spider.setContext(importRequest.Context)
	spider.setDownloadPlan(importRequest.DownloadTotal, importRequest.DownloadTotalBytes)
	spider.selectedResourceURLs = importRequest.SelectedResourceURLs
	rootResource := &mirroredResource{url: importRequest.SourceURL, content: []byte(importRequest.HTML)}
	spider.resources[importRequest.SourceURL] = rootResource
	spider.rewriteNestedResources(rootResource, 0, "text/html")
	spider.fetchSelectedResources()
	spider.retryFailedResources(importRequest.RemoteSourceURL, grabImportFailedResourceRetryAttempts)
	rootResource.content = []byte(spider.rewriteStaticURLTextReferences(string(rootResource.content), importRequest.RemoteSourceURL, 0))
	return spider, string(rootResource.content)
}

func localizeSavedPageExternalResources(ctx context.Context, domain, pagePath, htmlSource string, request *http.Request, tracker *grabProgressTracker) (*pageSpider, string) {
	pageURL, parseErr := url.Parse(absoluteURLForPath(request, cleanPath(pagePath)))
	if parseErr != nil {
		return nil, htmlSource
	}
	spider := newPageSpider(domain, pageURL, grabResourceMaxDepth, tracker, "", grabSourceOptions{})
	spider.setContext(ctx)
	spider.externalResourcesOnly = true
	rootResource := &mirroredResource{url: pageURL.String(), content: []byte(htmlSource)}
	spider.resources[pageURL.String()] = rootResource
	spider.rewriteNestedResources(rootResource, 0, "text/html")
	return spider, string(rootResource.content)
}

func previewResourcesFromSpider(spider *pageSpider, excludedURLs map[string]struct{}) []grabResourcePreview {
	resources := make([]grabResourcePreview, 0, len(spider.resources))
	for resourceURL, resource := range spider.resources {
		if _, excluded := excludedURLs[resourceURL]; excluded {
			continue
		}
		if resource == nil {
			continue
		}
		sizeBytes := int64(-1)
		if resource.content != nil {
			sizeBytes = int64(len(resource.content))
		} else if resource.sizeBytes >= 0 {
			sizeBytes = resource.sizeBytes
		}
		resourceKind := crawler.PreviewResourceKind("", "", resourceURL)
		if resource != nil && resourceKind == "file" {
			if contentTypeKind := crawler.ResourceKindFromContentType(resource.contentType); contentTypeKind != "" {
				resourceKind = contentTypeKind
			}
		}
		resources = append(resources, grabResourcePreview{URL: resourceURL, Kind: resourceKind, SizeBytes: sizeBytes})
	}
	sort.Slice(resources, func(leftIndex, rightIndex int) bool {
		if resources[leftIndex].Kind == resources[rightIndex].Kind {
			return resources[leftIndex].URL < resources[rightIndex].URL
		}
		return resources[leftIndex].Kind < resources[rightIndex].Kind
	})
	return resources
}

func previewWholeRemoteSiteResources(ctx context.Context, startURL *url.URL, startHTML, publicAssetBasePath string, tracker *grabProgressTracker, progressToken string, sourceOptions grabSourceOptions) wholeSitePreviewResult {
	return previewWholeRemoteSiteResourcesWithLimit(ctx, startURL, startHTML, publicAssetBasePath, tracker, progressToken, sourceOptions, 0)
}

func previewWholeRemoteSiteResourcesWithLimit(ctx context.Context, startURL *url.URL, startHTML, publicAssetBasePath string, tracker *grabProgressTracker, progressToken string, sourceOptions grabSourceOptions, byteLimit int64) wholeSitePreviewResult {
	spider, pageURLs, importedPages, partial := crawlWholeRemoteSite(ctx, startURL, startHTML, publicAssetBasePath, tracker, progressToken, sourceOptions, byteLimit)
	resources := previewResourcesFromSpider(spider, pageURLs)
	return wholeSitePreviewResult{PageCount: len(pageURLs), Resources: resources, ImportedPages: importedPages, Spider: spider, Partial: partial, LimitReached: spider.previewLimitReached}
}

func (a *App) prepareWholeRemoteSiteImport(importRequest grabImportRequest) (*pageSpider, []wholeSiteImportedPage, error) {
	basePath := cleanPath(importRequest.PagePath)
	startURL := importRequest.RemoteSourceURL
	if startURL == nil || startURL.Hostname() == "" {
		return nil, nil, errors.New("source_url is invalid")
	}
	spider := newPageSpider(importRequest.Domain, startURL, grabResourceMaxDepth, a.grabTracker, importRequest.ProgressToken, importRequest.SourceOptions)
	spider.setContext(importRequest.Context)
	spider.setDownloadPlan(importRequest.DownloadTotal, importRequest.DownloadTotalBytes)
	spider.selectedResourceURLs = importRequest.SelectedResourceURLs
	spider.publicAssetBasePath = basePath
	spider.documentURLRewriter = func(normalizedURL string) (string, bool) {
		parsedURL, parseErr := url.Parse(normalizedURL)
		if parseErr != nil || !crawler.SameHost(startURL, parsedURL) || !crawler.IsPageURL(parsedURL) {
			return "", false
		}
		return crawler.WholeSiteLocalLink(basePath, startURL, parsedURL), true
	}

	pageClient := grabImportHTTPClient(newGrabHTTPClientForSourceOptions(startURL.Hostname(), importRequest.SourceOptions))
	knownPagePathsByKey := map[string]string{crawler.WholeSitePageKey(startURL): basePath}
	pageQueue := []wholeSitePageJob{{URL: crawler.CloneURL(startURL), HTML: importRequest.HTML}}
	importedPages := make([]wholeSiteImportedPage, 0, 32)
	importedLocalPaths := make(map[string]struct{})
	consecutiveFailures := 0
	spider.foundTotal++
	spider.publishProgress("found", startURL.String(), 0)

	for len(pageQueue) > 0 && len(importedPages) < wholeSiteImportMaxPages {
		if spider.contextCanceled() {
			spider.publishResourceProgress("partial", crawler.CurrentWholeSiteImportURL(pageQueue), 0, 0, -1)
			break
		}
		if consecutiveFailures >= wholeSiteImportConsecutiveFailureLimit {
			spider.publishResourceProgress("partial", crawler.CurrentWholeSiteImportURL(pageQueue), 0, 0, -1)
			break
		}
		currentJob := pageQueue[0]
		pageQueue = pageQueue[1:]
		if currentJob.URL == nil {
			continue
		}
		pageKey := crawler.WholeSitePageKey(currentJob.URL)
		if pageKey == "" {
			continue
		}
		pageHTML := currentJob.HTML
		if strings.TrimSpace(pageHTML) == "" {
			downloadedHTML, downloaded, downloadErr := spider.downloadWholeSitePageHTMLWithRetries(pageClient, currentJob.URL, importRequest.SourceOptions, grabImportFailedResourceRetryAttempts)
			if downloadErr != nil || !downloaded {
				spider.failedTotal++
				consecutiveFailures++
				spider.recordFailedResource(currentJob.URL.String(), crawler.ErrorReason(downloadErr))
				spider.publishResourceProgress("error", currentJob.URL.String(), 0, 0, -1)
				continue
			}
			pageHTML = downloadedHTML
		}

		for _, linkedPageURL := range crawler.ExtractPageLinks(pageHTML, currentJob.URL, startURL) {
			linkedPageKey := crawler.WholeSitePageKey(linkedPageURL)
			if linkedPageKey == "" {
				continue
			}
			if _, alreadyKnown := knownPagePathsByKey[linkedPageKey]; alreadyKnown {
				continue
			}
			if len(knownPagePathsByKey) >= wholeSiteImportMaxPages {
				break
			}
			knownPagePathsByKey[linkedPageKey] = crawler.WholeSiteLocalPath(basePath, startURL, linkedPageURL)
			pageQueue = append(pageQueue, wholeSitePageJob{URL: crawler.CloneURL(linkedPageURL)})
			spider.foundTotal++
			spider.publishProgress("found", linkedPageURL.String(), 0)
		}

		rootResource := &mirroredResource{url: currentJob.URL.String(), content: []byte(pageHTML)}
		spider.resources[currentJob.URL.String()] = rootResource
		spider.rewriteNestedResources(rootResource, 0, "text/html")
		localPath := knownPagePathsByKey[pageKey]
		if _, alreadyImported := importedLocalPaths[localPath]; alreadyImported {
			continue
		}
		importedLocalPaths[localPath] = struct{}{}
		importedPages = append(importedPages, wholeSiteImportedPage{SourceURL: currentJob.URL.String(), LocalPath: localPath, HTML: string(rootResource.content)})
		spider.downloadedTotal++
		consecutiveFailures = 0
		spider.publishResourceProgress("downloaded", currentJob.URL.String(), 100, int64(len(pageHTML)), int64(len(pageHTML)))
	}
	if len(importedPages) == 0 {
		return nil, nil, errors.New("no pages were imported")
	}
	spider.retryFailedResources(startURL, grabImportFailedResourceRetryAttempts)
	spider.rewriteImportedPagesStaticURLTextReferences(importedPages)
	return spider, importedPages, nil
}

func (a *App) importWholeRemoteSite(ctx context.Context, importRequest grabImportRequest) (grabImportResult, error) {
	spider, importedPages, prepareErr := a.prepareWholeRemoteSiteImport(importRequest)
	if prepareErr != nil {
		return grabImportResult{}, prepareErr
	}
	pageDelta, publishedPageDelta, revisionDelta, publishedStaticDelta := a.estimateImportedPagesStorageDelta(ctx, importRequest.Domain, importedPages)
	fileDelta := a.estimateImportedFileDelta(importRequest.Domain, spider)
	if storageErr := a.applyDomainStorageDelta(ctx, importRequest.Domain, pageDelta, publishedPageDelta, revisionDelta, fileDelta, publishedStaticDelta); storageErr != nil {
		return grabImportResult{FailedTotal: spider.unresolvedFailedTotal(), FailedURLs: spider.failedResourceURLList(), FailedReasons: spider.failedResourceReasonMap()}, storageErr
	}
	if persistErr := a.persistSpiderAssets(ctx, spider, importRequest.PagePath); persistErr != nil {
		_ = a.applyDomainStorageDelta(ctx, importRequest.Domain, -pageDelta, -publishedPageDelta, -revisionDelta, -fileDelta, -publishedStaticDelta)
		return grabImportResult{FailedTotal: spider.unresolvedFailedTotal(), FailedURLs: spider.failedResourceURLList(), FailedReasons: spider.failedResourceReasonMap()}, persistErr
	}
	if storeErr := a.storeWholeSiteImportedPages(ctx, importRequest.Domain, importedPages); storeErr != nil {
		_ = a.applyDomainStorageDelta(ctx, importRequest.Domain, -pageDelta, -publishedPageDelta, -revisionDelta, -fileDelta, -publishedStaticDelta)
		return grabImportResult{FailedTotal: spider.unresolvedFailedTotal(), FailedURLs: spider.failedResourceURLList(), FailedReasons: spider.failedResourceReasonMap()}, storeErr
	}
	a.rebuildDomainStorageUsage(ctx, importRequest.Domain)
	if a.grabTracker != nil {
		stage := "done"
		if spider.unresolvedFailedTotal() > 0 {
			stage = "partial"
		}
		a.grabTracker.publish(spider.finalProgressEvent(importRequest.ProgressToken, stage))
	}
	return grabImportResult{RedirectPath: cleanPath(importRequest.PagePath), FailedTotal: spider.unresolvedFailedTotal(), FailedURLs: spider.failedResourceURLList(), FailedReasons: spider.failedResourceReasonMap()}, nil
}

type wholeSitePreviewPageResult struct {
	job        wholeSitePageJob
	html       string
	downloaded bool
	err        error
}

func crawlWholeRemoteSite(ctx context.Context, startURL *url.URL, startHTML, publicAssetBasePath string, tracker *grabProgressTracker, progressToken string, sourceOptions grabSourceOptions, byteLimit int64) (*pageSpider, map[string]struct{}, []wholeSiteImportedPage, bool) {
	if ctx == nil {
		ctx = context.Background()
	}
	spider := newPreviewPageSpider("", startURL, grabResourceMaxDepth, tracker, progressToken, sourceOptions)
	spider.setContext(ctx)
	spider.previewByteLimit = byteLimit
	spider.publicAssetBasePath = publicAssetBasePath
	spider.documentURLRewriter = func(normalizedURL string) (string, bool) {
		parsedURL, parseErr := url.Parse(normalizedURL)
		if parseErr != nil || !crawler.SameHost(startURL, parsedURL) || !crawler.IsPageURL(parsedURL) {
			return "", false
		}
		return crawler.WholeSiteLocalLink(cleanPath(publicAssetBasePath), startURL, parsedURL), true
	}
	pageClient := grabPreviewHTTPClient(newGrabHTTPClientForSourceOptions(startURL.Hostname(), sourceOptions))
	knownPagePathsByKey := map[string]string{crawler.WholeSitePageKey(startURL): cleanPath(publicAssetBasePath)}
	pageURLs := map[string]struct{}{startURL.String(): {}}
	pageQueue := []wholeSitePageJob{{URL: crawler.CloneURL(startURL), HTML: startHTML}}
	importedPages := make([]wholeSiteImportedPage, 0, 32)
	consecutiveFailures := 0
	partial := false
	spider.foundTotal++
	spider.publishProgress("found", startURL.String(), 0)

	pageJobs := make(chan wholeSitePageJob)
	pageResults := make(chan wholeSitePreviewPageResult, wholeSitePreviewPageConcurrency)
	workerDone := make(chan struct{}, wholeSitePreviewPageConcurrency)
	for workerIndex := 0; workerIndex < wholeSitePreviewPageConcurrency; workerIndex++ {
		go func() {
			defer func() {
				workerDone <- struct{}{}
			}()
			for pageJob := range pageJobs {
				pageHTML := pageJob.HTML
				downloaded := true
				var downloadErr error
				if strings.TrimSpace(pageHTML) == "" {
					pageHTML, downloaded, downloadErr = downloadWholeSitePageHTMLWithRetries(ctx, pageClient, pageJob.URL, sourceOptions, grabImportFailedResourceRetryAttempts)
				}
				pageResults <- wholeSitePreviewPageResult{job: pageJob, html: pageHTML, downloaded: downloaded, err: downloadErr}
			}
		}()
	}

	inFlight := 0
	stopDispatch := false
	contextDone := ctx.Done()
	for (len(pageQueue) > 0 && !stopDispatch) || inFlight > 0 {
		var nextJob wholeSitePageJob
		var nextJobChannel chan wholeSitePageJob
		if !stopDispatch && len(pageQueue) > 0 && inFlight < wholeSitePreviewPageConcurrency {
			nextJob = pageQueue[0]
			nextJobChannel = pageJobs
		}
		select {
		case <-contextDone:
			partial = true
			stopDispatch = true
			pageQueue = nil
			contextDone = nil
		case nextJobChannel <- nextJob:
			pageQueue = pageQueue[1:]
			inFlight++
		case pageResult := <-pageResults:
			inFlight--
			currentJob := pageResult.job
			if currentJob.URL == nil {
				continue
			}
			pageKey := crawler.WholeSitePageKey(currentJob.URL)
			if pageKey == "" {
				continue
			}
			if pageResult.err != nil || !pageResult.downloaded {
				spider.failedTotal++
				consecutiveFailures++
				spider.recordFailedResource(currentJob.URL.String(), crawler.ErrorReason(pageResult.err))
				spider.publishResourceProgress("error", currentJob.URL.String(), 0, 0, -1)
				if consecutiveFailures >= wholeSiteImportConsecutiveFailureLimit {
					partial = true
					stopDispatch = true
					pageQueue = nil
					spider.publishResourceProgress("partial", currentJob.URL.String(), 0, 0, -1)
				}
				continue
			}
			pageHTML := pageResult.html
			if !spider.recordPreviewBytes(int64(len([]byte(pageHTML)))) {
				partial = true
				stopDispatch = true
				pageQueue = nil
			}
			if spider.previewLimitReached {
				rootResource := &mirroredResource{url: currentJob.URL.String(), content: []byte(pageHTML)}
				spider.resources[currentJob.URL.String()] = rootResource
				importedPages = append(importedPages, wholeSiteImportedPage{SourceURL: currentJob.URL.String(), LocalPath: knownPagePathsByKey[pageKey], HTML: pageHTML})
				spider.downloadedTotal++
				spider.publishResourceProgress("partial", currentJob.URL.String(), 100, int64(len(pageHTML)), int64(len(pageHTML)))
				continue
			}
			for _, linkedPageURL := range crawler.ExtractPageLinks(pageHTML, currentJob.URL, startURL) {
				linkedPageKey := crawler.WholeSitePageKey(linkedPageURL)
				if linkedPageKey == "" {
					continue
				}
				if _, alreadyKnown := knownPagePathsByKey[linkedPageKey]; alreadyKnown {
					continue
				}
				if len(knownPagePathsByKey) >= wholeSiteImportMaxPages {
					partial = true
					break
				}
				knownPagePathsByKey[linkedPageKey] = crawler.WholeSiteLocalPath(cleanPath(publicAssetBasePath), startURL, linkedPageURL)
				pageQueue = append(pageQueue, wholeSitePageJob{URL: crawler.CloneURL(linkedPageURL)})
				pageURLs[linkedPageURL.String()] = struct{}{}
				spider.foundTotal++
				spider.publishProgress("found", linkedPageURL.String(), 0)
			}
			rootResource := &mirroredResource{url: currentJob.URL.String(), content: []byte(pageHTML)}
			spider.resources[currentJob.URL.String()] = rootResource
			spider.collectPreviewNestedResources(rootResource, 0, "text/html")
			if spider.previewLimitReached {
				partial = true
				stopDispatch = true
				pageQueue = nil
			}
			importedPages = append(importedPages, wholeSiteImportedPage{SourceURL: currentJob.URL.String(), LocalPath: knownPagePathsByKey[pageKey], HTML: string(rootResource.content)})
			spider.downloadedTotal++
			consecutiveFailures = 0
			spider.publishResourceProgress("downloaded", currentJob.URL.String(), 100, int64(len(pageHTML)), int64(len(pageHTML)))
		}
	}
	close(pageJobs)
	for workerIndex := 0; workerIndex < wholeSitePreviewPageConcurrency; workerIndex++ {
		<-workerDone
	}

	if ctx.Err() != nil {
		partial = true
	}
	spider.collectPreviewImportedPagesStaticURLTextReferences(importedPages)
	return spider, pageURLs, importedPages, partial
}

func downloadWholeSitePageHTMLWithRetries(ctx context.Context, client *http.Client, pageURL *url.URL, sourceOptions grabSourceOptions, retries int) (string, bool, error) {
	if retries < 0 {
		retries = 0
	}
	var lastErr error
	for attempt := 0; attempt <= retries; attempt++ {
		if attempt > 0 {
			retryTimer := time.NewTimer(grabImportFailedResourceRetryDelay)
			select {
			case <-ctx.Done():
				if !retryTimer.Stop() {
					select {
					case <-retryTimer.C:
					default:
					}
				}
				return "", false, ctx.Err()
			case <-retryTimer.C:
			}
		}
		pageHTML, downloaded, err := downloadWholeSitePageHTMLContext(ctx, client, pageURL, sourceOptions)
		if err == nil && downloaded {
			return pageHTML, true, nil
		}
		if err != nil {
			lastErr = err
		} else {
			lastErr = errors.New("page was not downloaded")
		}
	}
	return "", false, lastErr
}

func (a *App) storeWholeSiteImportedPages(ctx context.Context, domain string, importedPages []wholeSiteImportedPage) error {
	frozenDomain := a.isDomainFrozen(ctx, domain)
	for _, importedPage := range importedPages {
		pagePath := cleanPath(importedPage.LocalPath)
		pageHTML := importedPage.HTML
		a.clearPageRedirectSource(ctx, domain, pagePath)
		if _, err := a.db.ExecContext(ctx, `INSERT OR REPLACE INTO pages(domain,path,title,html,published) VALUES(?,?,?,?,1)`, domain, pagePath, pagePath, pageHTML); err != nil {
			return fmt.Errorf("store imported page %s: %w", pagePath, err)
		}
		if !frozenDomain {
			if _, err := a.db.ExecContext(ctx, `INSERT OR REPLACE INTO published_pages(domain,path,title,html) VALUES(?,?,?,?)`, domain, pagePath, pagePath, pageHTML); err != nil {
				return fmt.Errorf("publish imported page %s: %w", pagePath, err)
			}
			a.writePublishedStaticHTML(domain, pagePath, pageHTML)
		}
		if _, err := a.db.ExecContext(ctx, `INSERT INTO revisions(domain,page_path,html,created_at) VALUES(?,?,?,?)`, domain, pagePath, pageHTML, time.Now().Format(time.RFC3339)); err != nil {
			return fmt.Errorf("store imported page revision %s: %w", pagePath, err)
		}
	}
	return nil
}

func (a *App) estimateImportedPagesStorageDelta(ctx context.Context, domain string, importedPages []wholeSiteImportedPage) (int64, int64, int64, int64) {
	frozenDomain := a.isDomainFrozen(ctx, domain)
	var pageDelta int64
	var publishedPageDelta int64
	var revisionDelta int64
	var publishedStaticDelta int64
	for _, importedPage := range importedPages {
		pagePath := cleanPath(importedPage.LocalPath)
		pageHTML := importedPage.HTML
		newHTMLBytes := int64(len([]byte(pageHTML)))
		var previousStoredHTML string
		_ = a.db.QueryRowContext(ctx, `SELECT html FROM pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&previousStoredHTML)
		pageDelta += newHTMLBytes - int64(len([]byte(previousStoredHTML)))
		revisionDelta += newHTMLBytes
		if frozenDomain {
			continue
		}
		var previousPublishedHTML string
		_ = a.db.QueryRowContext(ctx, `SELECT html FROM published_pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&previousPublishedHTML)
		publishedPageDelta += newHTMLBytes - int64(len([]byte(previousPublishedHTML)))
		publishedStaticDelta += newHTMLBytes - a.fileSizeInsideStorage(filepath.Join(a.domainStaticDir(domain), staticRelativePathForPage(pagePath)))
	}
	return pageDelta, publishedPageDelta, revisionDelta, publishedStaticDelta
}

func (a *App) estimateImportedFileDelta(domain string, spider *pageSpider) int64 {
	if a == nil || spider == nil {
		return 0
	}
	baseDir := a.domainFilesDirForDomain(domain)
	var fileDelta int64
	for _, resource := range spider.resources {
		if resource == nil || !resource.persist || strings.TrimSpace(resource.assetPath) == "" || resource.content == nil {
			continue
		}
		assetReference := publicAssetReferenceFromPath(resource.assetPath)
		if assetReference == "" {
			continue
		}
		targetFilePath := filepath.Join(baseDir, filepath.FromSlash(assetReference))
		existingSize := a.fileSizeInsideStorage(targetFilePath)
		newSize := int64(len(resource.content))
		if existingSize <= 0 {
			fileDelta += newSize
			continue
		}
		fileDelta += newSize - existingSize
	}
	return fileDelta
}

func downloadWholeSitePageHTML(client *http.Client, pageURL *url.URL, sourceOptions grabSourceOptions) (string, bool, error) {
	return downloadWholeSitePageHTMLContext(context.Background(), client, pageURL, sourceOptions)
}

func downloadWholeSitePageHTMLContext(ctx context.Context, client *http.Client, pageURL *url.URL, sourceOptions grabSourceOptions) (string, bool, error) {
	downloadResult, err := crawler.DownloadHTMLPageContext(ctx, client, pageURL, func(request *http.Request) {
		applyGrabRequestHeaders(request, sourceOptions)
		applyGrabHTMLRequestHeaders(request)
	})
	if err == nil && downloadResult.IsHTML {
		logImportedHTMLDecodeDecision(pageURL, downloadResult)
	}
	return downloadResult.HTML, downloadResult.IsHTML, err
}

func (spider *pageSpider) downloadWholeSitePageHTMLWithRetries(client *http.Client, pageURL *url.URL, sourceOptions grabSourceOptions, retries int) (string, bool, error) {
	if retries < 0 {
		retries = 0
	}
	var lastErr error
	totalAttempts := retries + 1
	pageURLText := ""
	if pageURL != nil {
		pageURLText = pageURL.String()
	}
	for attempt := 1; attempt <= totalAttempts; attempt++ {
		if spider.contextCanceled() {
			return "", false, spider.context().Err()
		}
		if attempt > 1 {
			spider.waitBeforeRetry(pageURLText, attempt-1, retries)
			if spider.contextCanceled() {
				return "", false, spider.context().Err()
			}
			spider.publishRetryProgress("retrying", pageURLText, attempt-1, retries, 0)
		}
		html, downloaded, err := downloadWholeSitePageHTMLContext(spider.context(), client, pageURL, sourceOptions)
		if err == nil && downloaded {
			spider.clearFailedResource(pageURLText)
			return html, true, nil
		}
		if spider.contextCanceled() {
			return "", false, spider.context().Err()
		}
		if err != nil {
			lastErr = err
		} else {
			lastErr = errors.New("not html")
		}
		if pageURLText != "" {
			spider.recordFailedResource(pageURLText, crawler.ErrorReason(lastErr))
			spider.publishResourceProgress("error", pageURLText, 0, 0, -1)
		}
	}
	return "", false, lastErr
}

type importedHTMLCleanupRule struct {
	name    string
	matches func(*html.Node) bool
}

var legacyImportedSiteBrushCleanupRules = []importedHTMLCleanupRule{
	{name: "sitebrush-comment", matches: isLegacySiteBrushCommentNode},
	{name: "sitebrush-menu-container", matches: isLegacySiteBrushMenuContainerNode},
	{name: "sitebrush-context-script", matches: isLegacySiteBrushContextScriptNode},
	{name: "sitebrush-context-style", matches: isLegacySiteBrushContextStyleNode},
}

var importedLanguageRedirectPathPattern = regexp.MustCompile(`(?i)['"]/?(en|fr|ru|ja|it|sv|fi|mn|zh|he|fa|de|tr|kk|es|pt)/(index\.(html?|xhtml|php|asp|aspx|jsp|cgi))?['"]`)

func cleanupLegacyImportedSiteBrushHTML(source string) string {
	loweredSource := strings.ToLower(source)
	if !strings.Contains(loweredSource, "sitebrush") && !strings.Contains(loweredSource, "jqcontextmenu") && !strings.Contains(loweredSource, "contextmenu") {
		return source
	}
	documentNode, parseErr := html.Parse(strings.NewReader(source))
	if parseErr != nil {
		return source
	}
	removeImportedHTMLNodes(documentNode)
	var rendered bytes.Buffer
	if renderErr := html.Render(&rendered, documentNode); renderErr != nil {
		return source
	}
	return rendered.String()
}

func neutralizeImportedHostLanguageRedirects(source string) string {
	loweredSource := strings.ToLower(source)
	if !strings.Contains(loweredSource, "location") || (!strings.Contains(loweredSource, "hostname") && !strings.Contains(loweredSource, "host")) {
		return source
	}
	documentNode, parseErr := html.Parse(strings.NewReader(source))
	if parseErr != nil {
		return source
	}
	removeImportedHostLanguageRedirectScripts(documentNode)
	var rendered bytes.Buffer
	if renderErr := html.Render(&rendered, documentNode); renderErr != nil {
		return source
	}
	return rendered.String()
}

func removeImportedHostLanguageRedirectScripts(parentNode *html.Node) {
	if parentNode == nil {
		return
	}
	for childNode := parentNode.FirstChild; childNode != nil; {
		nextNode := childNode.NextSibling
		if isImportedHostLanguageRedirectScriptNode(childNode) {
			parentNode.RemoveChild(childNode)
		} else {
			removeImportedHostLanguageRedirectScripts(childNode)
		}
		childNode = nextNode
	}
}

func isImportedHostLanguageRedirectScriptNode(node *html.Node) bool {
	if node == nil || node.Type != html.ElementNode || node.Data != "script" || strings.TrimSpace(htmlAttribute(node, "src")) != "" {
		return false
	}
	scriptSource := strings.ToLower(htmlNodeText(node))
	if scriptSource == "" {
		return false
	}
	hasNavigationSink := strings.Contains(scriptSource, "location.href") || strings.Contains(scriptSource, "location.replace") || strings.Contains(scriptSource, "location.assign")
	if !hasNavigationSink {
		return false
	}
	if !strings.Contains(scriptSource, "hostname") && !strings.Contains(scriptSource, "host") {
		return false
	}
	if !strings.Contains(scriptSource, "pathname") && !strings.Contains(scriptSource, "path") {
		return false
	}
	return importedLanguageRedirectPathPattern.MatchString(scriptSource)
}

func removeImportedHTMLNodes(parentNode *html.Node) {
	if parentNode == nil {
		return
	}
	for childNode := parentNode.FirstChild; childNode != nil; {
		nextNode := childNode.NextSibling
		if shouldRemoveImportedHTMLNode(childNode) {
			parentNode.RemoveChild(childNode)
		} else {
			removeImportedHTMLNodes(childNode)
		}
		childNode = nextNode
	}
}

func shouldRemoveImportedHTMLNode(node *html.Node) bool {
	for _, cleanupRule := range legacyImportedSiteBrushCleanupRules {
		if cleanupRule.matches(node) {
			return true
		}
	}
	return false
}

func isLegacySiteBrushCommentNode(node *html.Node) bool {
	return node != nil && node.Type == html.CommentNode && strings.Contains(strings.ToLower(node.Data), "powered by sitebrush")
}

func isLegacySiteBrushMenuContainerNode(node *html.Node) bool {
	if node == nil || node.Type != html.ElementNode {
		return false
	}
	nodeID := strings.ToLower(strings.TrimSpace(htmlAttribute(node, "id")))
	if nodeID == "sitebrushmenu" || nodeID == "jqcontextmenu" {
		return true
	}
	nodeClass := htmlClassSet(node)
	return nodeClass["sitebrushcontextmenu"] || nodeClass["contextmenucopyright"] || (nodeClass["contextmenu"] && nodeClass["sitebrushmenu"])
}

func isLegacySiteBrushContextScriptNode(node *html.Node) bool {
	if node == nil || node.Type != html.ElementNode || node.Data != "script" {
		return false
	}
	scriptSource := strings.ToLower(htmlNodeText(node))
	if scriptSource == "" {
		return false
	}
	for _, marker := range []string{"$.fn.contextmenu", "jqcontextmenu", "$('#sitebrush').contextmenu(", `$("#sitebrush").contextmenu(`, "div.contextmenu", "sitebrushmenu"} {
		if strings.Contains(scriptSource, marker) {
			return true
		}
	}
	return false
}

func isLegacySiteBrushContextStyleNode(node *html.Node) bool {
	if node == nil || node.Type != html.ElementNode || node.Data != "style" {
		return false
	}
	styleSource := strings.ToLower(htmlNodeText(node))
	if styleSource == "" {
		return false
	}
	for _, marker := range []string{".sitebrushcontextmenu", ".contextmenucopyright", ".sitebrushmenu", "div.contextmenu"} {
		if strings.Contains(styleSource, marker) {
			return true
		}
	}
	return false
}

func htmlAttribute(node *html.Node, attributeKey string) string {
	if node == nil {
		return ""
	}
	for _, attribute := range node.Attr {
		if strings.EqualFold(strings.TrimSpace(attribute.Key), attributeKey) {
			return attribute.Val
		}
	}
	return ""
}

func htmlClassSet(node *html.Node) map[string]bool {
	classSet := make(map[string]bool)
	for _, className := range strings.Fields(strings.ToLower(htmlAttribute(node, "class"))) {
		classSet[className] = true
	}
	return classSet
}

func htmlNodeText(node *html.Node) string {
	if node == nil {
		return ""
	}
	var textBuilder strings.Builder
	for childNode := node.FirstChild; childNode != nil; childNode = childNode.NextSibling {
		if childNode.Type == html.TextNode || childNode.Type == html.CommentNode {
			textBuilder.WriteString(childNode.Data)
		}
	}
	return textBuilder.String()
}

func (a *App) grabProgressWS(w http.ResponseWriter, r *http.Request) {
	if !a.isAdminRequest(r) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	progressToken := strings.TrimSpace(r.URL.Query().Get("token"))
	if progressToken == "" {
		http.Error(w, "token is required", http.StatusBadRequest)
		return
	}
	connection, err := upgradeToWebSocket(w, r)
	if err != nil {
		return
	}
	defer connection.Close()
	events := a.grabTracker.subscribe(progressToken)
	defer a.grabTracker.unsubscribe(progressToken, events)
	readyEventJSON, marshalReadyErr := json.Marshal(grabProgressEvent{Token: progressToken, Stage: "ready"})
	if marshalReadyErr != nil {
		return
	}
	if err := connection.WriteText(readyEventJSON); err != nil {
		return
	}
	for {
		event, isOpen := <-events
		if !isOpen {
			return
		}
		eventJSON, marshalErr := json.Marshal(event)
		if marshalErr != nil {
			return
		}
		if err := connection.WriteText(eventJSON); err != nil {
			return
		}
		if event.Stage == "done" || (event.Stage == "error" && strings.TrimSpace(event.CurrentURL) == "") {
			return
		}
	}
}

func (a *App) grabProgressEvents(w http.ResponseWriter, r *http.Request) {
	if !a.isAdminRequest(r) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	a.streamGrabProgressEvents(w, r)
}

func (a *App) publicTrialSiteEvents(w http.ResponseWriter, r *http.Request) {
	if !a.publicTrialAllowed(r) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	a.streamGrabProgressEvents(w, r)
}

func (a *App) streamGrabProgressEvents(w http.ResponseWriter, r *http.Request) {
	progressToken := strings.TrimSpace(r.URL.Query().Get("token"))
	if progressToken == "" {
		http.Error(w, "token is required", http.StatusBadRequest)
		return
	}
	flusher, canFlush := w.(http.Flusher)
	if !canFlush {
		http.Error(w, "streaming is not supported", http.StatusInternalServerError)
		return
	}
	allowLongStreamingResponse(w)
	w.Header().Set("Content-Type", "text/event-stream; charset=utf-8")
	w.Header().Set("Cache-Control", "no-cache")

	events := a.grabTracker.subscribe(progressToken)
	defer a.grabTracker.unsubscribe(progressToken, events)
	if !writeGrabProgressEvent(w, flusher, grabProgressEvent{Token: progressToken, Stage: "ready"}) {
		return
	}
	heartbeat := time.NewTicker(15 * time.Second)
	defer heartbeat.Stop()
	for {
		select {
		case <-r.Context().Done():
			return
		case <-heartbeat.C:
			if _, writeErr := io.WriteString(w, ": heartbeat\n\n"); writeErr != nil {
				return
			}
			flusher.Flush()
		case event, isOpen := <-events:
			if !isOpen {
				return
			}
			if !writeGrabProgressEvent(w, flusher, event) {
				return
			}
			if event.Stage == "done" || event.Stage == "partial" || event.Stage == "canceled" || (event.Stage == "error" && strings.TrimSpace(event.CurrentURL) == "") {
				return
			}
		}
	}
}

func writeGrabProgressEvent(w io.Writer, flusher http.Flusher, event grabProgressEvent) bool {
	eventJSON, marshalErr := json.Marshal(event)
	if marshalErr != nil {
		return false
	}
	if _, writeErr := fmt.Fprintf(w, "data: %s\n\n", eventJSON); writeErr != nil {
		return false
	}
	flusher.Flush()
	return true
}

func allowLongStreamingResponse(w http.ResponseWriter) {
	// Streaming progress endpoints can outlive the global WriteTimeout, while
	// ordinary page and static responses still keep the server-wide deadline.
	_ = http.NewResponseController(w).SetWriteDeadline(time.Time{})
}

func (a *App) publishProgressEvents(w http.ResponseWriter, r *http.Request) {
	if !a.isAdminRequest(r) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	progressToken := strings.TrimSpace(r.URL.Query().Get("token"))
	if progressToken == "" {
		http.Error(w, "token is required", http.StatusBadRequest)
		return
	}
	flusher, canFlush := w.(http.Flusher)
	if !canFlush {
		http.Error(w, "streaming is not supported", http.StatusInternalServerError)
		return
	}
	allowLongStreamingResponse(w)
	w.Header().Set("Content-Type", "text/event-stream; charset=utf-8")
	w.Header().Set("Cache-Control", "no-cache")

	tracker := a.activePublishTracker()
	events := tracker.subscribe(progressToken)
	defer tracker.unsubscribe(progressToken, events)
	if !writePublishProgressEvent(w, flusher, publishProgressEvent{Token: progressToken, Stage: "ready"}) {
		return
	}
	for {
		select {
		case <-r.Context().Done():
			return
		case event, isOpen := <-events:
			if !isOpen {
				return
			}
			if !writePublishProgressEvent(w, flusher, event) {
				return
			}
			if event.Stage == "done" || event.Stage == "error" {
				return
			}
		}
	}
}

func writePublishProgressEvent(w io.Writer, flusher http.Flusher, event publishProgressEvent) bool {
	eventJSON, marshalErr := json.Marshal(event)
	if marshalErr != nil {
		return false
	}
	if _, writeErr := fmt.Fprintf(w, "data: %s\n\n", eventJSON); writeErr != nil {
		return false
	}
	flusher.Flush()
	return true
}

func (a *App) revisionsPage(w http.ResponseWriter, r *http.Request) {
	if !a.canEditPages(r) {
		if !a.hasAdmin(r.Context(), a.siteDomain(r.Context(), r)) {
			httpsecurity.RedirectLocal(w, r, r.URL.Path+"?register", http.StatusFound)
			return
		}
		httpsecurity.RedirectLocal(w, r, loginURLForRequest(r), http.StatusFound)
		return
	}
	pagePath := cleanPath(r.URL.Query().Get("path"))
	if pagePath == "/" && strings.TrimSpace(r.URL.Query().Get("path")) == "" {
		pagePath = cleanPath(r.URL.Path)
	}
	domain := a.siteDomain(r.Context(), r)
	revisionRows, err := a.db.QueryContext(r.Context(), `SELECT id,page_path,html,created_at,is_active FROM revisions WHERE domain=? AND page_path=? ORDER BY id DESC`, domain, pagePath)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	defer revisionRows.Close()
	var revisionList []Revision
	for revisionRows.Next() {
		var current Revision
		_ = revisionRows.Scan(&current.ID, &current.PagePath, &current.HTML, &current.CreatedAt, &current.IsActive)
		revisionList = append(revisionList, current)
	}
	returnPath := r.URL.Query().Get("return")
	if strings.TrimSpace(returnPath) == "" {
		returnPath = pagePath
	}
	w.Header().Set("Cache-Control", "no-store")
	translations := translationsForRequest(r)
	text := revisionPageText{
		OriginalDate:    template.JSEscapeString(translationOrDefault(translations, "revisions_original_date", "original")),
		FullscreenLabel: template.JSEscapeString(translationOrDefault(translations, "revisions_preview_fullscreen", "Full area")),
		WindowedLabel:   template.JSEscapeString(translationOrDefault(translations, "revisions_preview_windowed", "Window size")),
	}
	a.render(w, r, "revisions.html", map[string]any{"Path": pagePath, "ReturnPath": returnPath, "Revisions": revisionList, "RevisionText": text})
}

func (a *App) expensesPage(w http.ResponseWriter, r *http.Request) {
	if a.redirectToHostingAndSupportMainDomain(w, r) {
		return
	}
	requestDomain := domainFromRequest(r)
	adminEmail, adminFound := a.currentAdminEmailForDomain(r, requestDomain)
	if !adminFound {
		if !a.hasAdmin(r.Context(), requestDomain) {
			httpsecurity.RedirectLocal(w, r, r.URL.Path+"?register", http.StatusFound)
			return
		}
		httpsecurity.RedirectLocal(w, r, loginURLForRequest(r), http.StatusFound)
		return
	}
	if !a.isServerManagerEmail(r.Context(), requestDomain, adminEmail) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	status := ""
	if r.Method == http.MethodPost {
		status = a.handleExpensesAction(r)
		a.refreshHostingAndSupportPanel()
		if expensesActionWantsJSON(r) {
			saved := expensesActionStatusWasSaved(r, status)
			w.Header().Set("Content-Type", "application/json")
			if !saved {
				w.WriteHeader(http.StatusBadRequest)
			}
			_ = json.NewEncoder(w).Encode(map[string]any{"status": status, "saved": saved})
			return
		}
	}
	view, err := a.expensesView(r.Context(), r)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	view["Status"] = status
	a.render(w, r, "expenses.html", view)
}

func (a *App) startHostingAndSupportPanelProcess(stop <-chan struct{}) chan hostingAndSupportPanelRequest {
	requests := make(chan hostingAndSupportPanelRequest, 16)
	initialSnapshot := hostingAndSupportPanelSnapshot{Version: hostingAndSupportPanelSnapshotVersion}
	err := a.withServerControlDatabaseRead(context.Background(), "hosting-panel-initial", func(database *sql.DB) error {
		store := hostingandsupport.Store{DB: database}
		storedSnapshot, found := store.PanelSnapshot(context.Background())
		if found && storedSnapshot.Version == hostingAndSupportPanelSnapshotVersion {
			if decodeErr := json.Unmarshal([]byte(storedSnapshot.PayloadJSON), &initialSnapshot); decodeErr != nil {
				return decodeErr
			}
		}
		if strings.TrimSpace(initialSnapshot.MainDomain) == "" {
			if ownerDomain, ownerFound := store.OwnerDomain(context.Background()); ownerFound {
				initialSnapshot.MainDomain = ownerDomain
				initialSnapshot.OwnerEmails = store.OwnerEmails(context.Background())
			}
		}
		return nil
	})
	if err != nil {
		log.Printf("hosting panel snapshot store unavailable: %v", err)
		initialSnapshot = hostingAndSupportPanelSnapshot{Version: hostingAndSupportPanelSnapshotVersion}
	}
	if initialSnapshot.Version != hostingAndSupportPanelSnapshotVersion {
		initialSnapshot = hostingAndSupportPanelSnapshot{Version: hostingAndSupportPanelSnapshotVersion}
	}
	buildResults := make(chan hostingAndSupportPanelBuildResult, 1)
	snapshotSaves := make(chan hostingAndSupportPanelSnapshot, 1)
	go a.runHostingAndSupportPanelSnapshotSaver(stop, snapshotSaves)
	go a.runHostingAndSupportPanelProcess(stop, requests, buildResults, snapshotSaves, initialSnapshot)
	go a.runHostingAndSupportMetricsProcess(stop, requests)
	return requests
}

func (a *App) runHostingAndSupportPanelProcess(stop <-chan struct{}, requests <-chan hostingAndSupportPanelRequest, buildResults chan hostingAndSupportPanelBuildResult, snapshotSaves chan hostingAndSupportPanelSnapshot, initialSnapshot hostingAndSupportPanelSnapshot) {
	fullRefreshTicker := time.NewTicker(hostingAndSupportFullRefreshInterval)
	defer fullRefreshTicker.Stop()
	snapshot := initialSnapshot
	snapshotGeneration := uint64(0)
	buildRunning := false
	buildPending := false
	startBuild := func() {
		if buildRunning {
			buildPending = true
			return
		}
		buildRunning = true
		buildGeneration := snapshotGeneration
		go func() {
			builtSnapshot, buildErr := a.collectHostingAndSupportPanelSnapshot(context.Background(), nil)
			buildResults <- hostingAndSupportPanelBuildResult{snapshot: builtSnapshot, generation: buildGeneration, err: buildErr}
		}()
	}
	startBuild()
	for {
		select {
		case <-stop:
			if buildRunning {
				<-buildResults
			}
			return
		case request := <-requests:
			switch request.kind {
			case "get":
				request.reply <- hostingAndSupportPanelResponse{snapshot: snapshot}
			case "refresh":
				startBuild()
			case "metrics":
				snapshot = a.applyHostingAndSupportPanelMetrics(snapshot, request.metrics)
			case "quota_changed":
				snapshotGeneration++
				snapshot = a.applyHostingAndSupportPanelQuotaChange(snapshot, request.quotaChange)
				queueLatestHostingAndSupportPanelSnapshot(snapshotSaves, snapshot)
				request.reply <- hostingAndSupportPanelResponse{snapshot: snapshot}
				startBuild()
			case "expense_policy_changed":
				snapshotGeneration++
				snapshot.LocalCostPolicy = request.costPolicy
				for serverIndex := range snapshot.Servers {
					if snapshot.Servers[serverIndex].Local {
						hostingandsupport.ApplyServerCostView(&snapshot.Servers[serverIndex], request.costPolicy, snapshot.Invoices)
						break
					}
				}
				snapshot.BuiltAt = time.Now().UTC().Format(time.RFC3339)
				queueLatestHostingAndSupportPanelSnapshot(snapshotSaves, snapshot)
				request.reply <- hostingAndSupportPanelResponse{snapshot: snapshot}
				startBuild()
			}
		case result := <-buildResults:
			buildRunning = false
			if result.err != nil {
				log.Printf("hosting panel snapshot refresh failed: %v", result.err)
			} else if result.generation == snapshotGeneration {
				currentMetrics := []hostingandsupport.ServerMetricView(nil)
				for _, server := range snapshot.Servers {
					if server.Local {
						currentMetrics = server.SystemMetrics
						break
					}
				}
				snapshot = a.applyHostingAndSupportPanelMetrics(result.snapshot, currentMetrics)
				queueLatestHostingAndSupportPanelSnapshot(snapshotSaves, snapshot)
			}
			if buildPending {
				buildPending = false
				startBuild()
			}
		case <-fullRefreshTicker.C:
			startBuild()
		}
	}
}

func queueLatestHostingAndSupportPanelSnapshot(requests chan hostingAndSupportPanelSnapshot, snapshot hostingAndSupportPanelSnapshot) {
	select {
	case requests <- snapshot:
		return
	default:
	}
	select {
	case <-requests:
	default:
	}
	select {
	case requests <- snapshot:
	default:
	}
}

func (a *App) runHostingAndSupportPanelSnapshotSaver(stop <-chan struct{}, requests <-chan hostingAndSupportPanelSnapshot) {
	for {
		select {
		case <-stop:
			return
		case snapshot := <-requests:
			if persistErr := a.saveHostingAndSupportPanelSnapshot(snapshot); persistErr != nil {
				log.Printf("hosting panel snapshot save failed: %v", persistErr)
			}
		}
	}
}

func (a *App) runHostingAndSupportMetricsProcess(stop <-chan struct{}, requests chan<- hostingAndSupportPanelRequest) {
	metricsTicker := time.NewTicker(hostingAndSupportMetricsRefreshInterval)
	defer metricsTicker.Stop()
	for {
		metrics := a.localHostingServerSystemMetrics(context.Background())
		select {
		case requests <- hostingAndSupportPanelRequest{kind: "metrics", metrics: metrics}:
		case <-stop:
			return
		}
		select {
		case <-metricsTicker.C:
		case <-stop:
			return
		}
	}
}

type billingInvoiceGroup struct {
	customer        hostingandsupport.BillingCustomer
	installationID  string
	serverName      string
	currency        string
	lines           []hostingandsupport.InvoiceLine
	amountMinor     int64
	serverCostMinor int64
	hasPaidSite     bool
}

type billingServerSite struct {
	domain      string
	usedBytes   int64
	ownerEmail  string
	adminEmails []string
	isDemo      bool
}

func (a *App) startBillingInvoiceProcess(stop <-chan struct{}) chan billingInvoiceProcessRequest {
	requests := make(chan billingInvoiceProcessRequest, 1)
	go func() {
		ticker := time.NewTicker(time.Hour)
		defer ticker.Stop()
		run := func() {
			snapshot, found := a.preparedHostingAndSupportPanelSnapshot()
			if !found {
				return
			}
			err := a.withServerControlDatabaseWrite(context.Background(), "automatic-billing", func(database *sql.DB) error {
				a.runAutomaticBillingOnce(context.Background(), hostingandsupport.Store{DB: database}, snapshot, time.Now().UTC())
				return nil
			})
			if err != nil {
				log.Printf("automatic billing database unavailable: %v", err)
				return
			}
			a.refreshHostingAndSupportPanel()
		}
		for {
			select {
			case <-stop:
				return
			case <-ticker.C:
				run()
			case <-requests:
				run()
			}
		}
	}()
	return requests
}

func (a *App) runAutomaticBillingOnce(ctx context.Context, store hostingandsupport.Store, snapshot hostingAndSupportPanelSnapshot, now time.Time) {
	groups := make(map[string]*billingInvoiceGroup)
	addSite := func(installationID string, serverName string, policy expenses.ServerPolicy, site billingServerSite, allocation expenses.SiteAllocation) {
		if site.isDemo {
			return
		}
		ownerEmail := site.ownerEmail
		adminEmails := site.adminEmails
		ownerEmail = strings.ToLower(strings.TrimSpace(ownerEmail))
		if ownerEmail == "" && len(adminEmails) > 0 {
			ownerEmail = strings.ToLower(strings.TrimSpace(adminEmails[0]))
		}
		if ownerEmail == "" || normalizeDomainName(site.domain) == "" {
			return
		}
		customer, err := store.EnsureBillingCustomer(ctx, ownerEmail, adminEmails)
		if err != nil || !customer.AutomaticEnabled || !billingCustomerInvoiceDue(customer, now) {
			return
		}
		groupKey := customer.ID + "\x00" + installationID
		group := groups[groupKey]
		if group == nil {
			group = &billingInvoiceGroup{customer: customer, installationID: installationID, serverName: serverName, currency: policy.Currency}
			groups[groupKey] = group
		}
		line := hostingandsupport.InvoiceLine{
			Domain:            normalizeDomainName(site.domain),
			Description:       "Доля расходов на размещение " + normalizeDomainName(site.domain),
			UsedBytes:         site.usedBytes,
			BillableMegabytes: (site.usedBytes + expenses.DecimalMegabyte - 1) / expenses.DecimalMegabyte,
			ListAmountMinor:   allocation.ExpenseShareMinor,
			TotalAmountMinor:  allocation.ExpenseShareMinor,
			CostShareMinor:    allocation.ExpenseShareMinor,
		}
		if allocation.Free {
			line.Bonus = true
			line.Description = "Бонус: размещение " + normalizeDomainName(site.domain) + " до бесплатного порога"
			line.TotalAmountMinor = 0
		} else if allocation.ExpenseShareMinor > 0 {
			group.hasPaidSite = true
			group.amountMinor += line.TotalAmountMinor
			group.serverCostMinor += allocation.ExpenseShareMinor
		}
		group.lines = append(group.lines, line)
	}
	processServer := func(installationID string, serverName string, policy expenses.ServerPolicy, sites []billingServerSite) {
		policy = expenses.NormalizePolicy(policy)
		if expenses.CalculateMonthlyExpense(policy) <= 0 || strings.TrimSpace(policy.Currency) == "" {
			return
		}
		expenseSites := make([]expenses.SiteUsage, 0, len(sites))
		for siteIndex, site := range sites {
			expenseSites = append(expenseSites, expenses.SiteUsage{
				Key: fmt.Sprintf("%s\x00%06d", normalizeDomainName(site.domain), siteIndex), UsedBytes: site.usedBytes, Excluded: site.isDemo,
			})
		}
		allocations := expenses.AllocateMonthlyExpense(policy, expenseSites)
		for siteIndex, site := range sites {
			allocation := allocations.Sites[fmt.Sprintf("%s\x00%06d", normalizeDomainName(site.domain), siteIndex)]
			addSite(installationID, serverName, policy, site, allocation)
		}
	}
	localInstallationID := "local:" + normalizeDomainName(snapshot.MainDomain)
	localSites := make([]billingServerSite, 0, len(snapshot.Sites))
	for _, site := range snapshot.Sites {
		adminEmails := hostingandsupport.SplitEmailList(site.AdminEmails)
		localSites = append(localSites, billingServerSite{
			domain: site.Domain, usedBytes: site.UsedBytes, adminEmails: adminEmails, isDemo: site.IsDemo,
		})
	}
	processServer(localInstallationID, snapshot.MainDomain, snapshot.LocalCostPolicy, localSites)
	for _, hosting := range snapshot.ClientHostings {
		serverName := firstNonEmpty(hosting.ServerDomain, hosting.InstallationID)
		remoteSites := make([]billingServerSite, 0, len(hosting.Sites))
		for _, site := range hosting.Sites {
			remoteSites = append(remoteSites, billingServerSite{
				domain: site.Domain, usedBytes: site.UsedBytes, ownerEmail: site.OwnerEmail, adminEmails: site.AdminEmails,
				isDemo: site.IsDemo,
			})
		}
		processServer(hosting.InstallationID, serverName, hosting.ExpensePolicy, remoteSites)
	}
	for _, group := range groups {
		if !group.hasPaidSite || group.amountMinor <= 0 || len(group.lines) == 0 {
			continue
		}
		location, err := time.LoadLocation(group.customer.Timezone)
		if err != nil {
			location = time.UTC
		}
		localNow := now.In(location)
		periodStart := time.Date(localNow.Year(), localNow.Month(), group.customer.InvoiceDay, 0, 0, 0, 0, location)
		periodEnd := periodStart.AddDate(0, 1, 0)
		dueAt := periodStart.AddDate(0, 0, group.customer.PaymentTermDays)
		paymentFeeMinor := expenses.PaymentCommissionMinor(group.serverCostMinor, snapshot.CommissionBPS)
		if paymentFeeMinor > 0 {
			group.lines = append(group.lines, hostingandsupport.InvoiceLine{
				Domain:           "sitebrush.com",
				Description:      fmt.Sprintf("Проведение платежа SiteBrush (%.2f%%)", float64(snapshot.CommissionBPS)/100),
				ListAmountMinor:  paymentFeeMinor,
				TotalAmountMinor: paymentFeeMinor,
			})
		}
		invoice := hostingandsupport.Invoice{
			CustomerID:      group.customer.ID,
			CustomerEmail:   group.customer.PrimaryEmail,
			InstallationID:  group.installationID,
			ServerName:      group.serverName,
			Domain:          group.lines[0].Domain,
			PlanName:        "Доля расходов сервера",
			AmountMinor:     group.amountMinor + paymentFeeMinor,
			Currency:        group.currency,
			Provider:        "sitebrush_com",
			DueAt:           dueAt.Format("2006-01-02"),
			Recurring:       true,
			RecurringPeriod: "monthly",
			PeriodStart:     periodStart.Format("2006-01-02"),
			PeriodEnd:       periodEnd.Format("2006-01-02"),
			CommissionBPS:   snapshot.CommissionBPS,
			ServerCostMinor: group.serverCostMinor,
			PaymentFeeMinor: paymentFeeMinor,
			ReserveMinor:    0,
			Lines:           group.lines,
		}
		createdInvoice, createErr := store.CreateInvoice(ctx, invoice)
		if createErr != nil {
			log.Printf("automatic invoice creation failed customer=%s server=%s: %v", group.customer.PrimaryEmail, group.serverName, createErr)
			continue
		}
		if createdInvoice.PublicToken == "" {
			continue
		}
		scheduleToken, tokenErr := store.NewBillingCustomerAccessToken(ctx, group.customer.ID, 30*24*time.Hour)
		if tokenErr != nil {
			_ = store.MarkInvoiceDelivery(ctx, createdInvoice.ID, "error", tokenErr.Error())
			continue
		}
		invoiceURL := billingPublicURL(snapshot.MainDomain, "hosting_invoice", createdInvoice.PublicToken)
		scheduleURL := billingPublicURL(snapshot.MainDomain, "billing_schedule", scheduleToken)
		message := billingInvoiceEmailMessage(a.emailFromAddress(snapshot.MainDomain), createdInvoice, invoiceURL, scheduleURL)
		if enqueueErr := a.enqueueEmail(ctx, message); enqueueErr != nil {
			_ = store.MarkInvoiceDelivery(ctx, createdInvoice.ID, "error", enqueueErr.Error())
			continue
		}
		_ = store.MarkInvoiceDelivery(ctx, createdInvoice.ID, "sent", "")
	}
}

func billingCustomerInvoiceDue(customer hostingandsupport.BillingCustomer, now time.Time) bool {
	location, err := time.LoadLocation(customer.Timezone)
	if err != nil {
		location = time.UTC
	}
	return now.In(location).Day() == customer.InvoiceDay
}

func billingPublicURL(mainDomain string, queryFlag string, token string) string {
	mainDomain = normalizeDomainName(mainDomain)
	scheme := "https"
	if mainDomain == "" || mainDomain == "localhost" {
		mainDomain = "localhost"
		scheme = "http"
	}
	return scheme + "://" + mainDomain + "/?" + url.QueryEscape(queryFlag) + "&token=" + url.QueryEscape(token)
}

func billingInvoiceEmailMessage(fromAddress string, invoice hostingandsupport.Invoice, invoiceURL string, scheduleURL string) mailout.Message {
	amountLabel := hostingandsupport.MoneyLabel(invoice.AmountMinor, invoice.Currency)
	textBody := "Invoice " + invoice.Number + "\n\nServer: " + invoice.ServerName + "\nPeriod: " + invoice.PeriodStart + " - " + invoice.PeriodEnd + "\nTotal: " + amountLabel + "\nDue: " + invoice.DueAt + "\n\nView and pay: " + invoiceURL + "\nBilling schedule: " + scheduleURL
	htmlBody := `<!doctype html><html><body style="margin:0;background:#f4f7f8;color:#172126;font-family:Arial,sans-serif"><div style="max-width:680px;margin:0 auto;padding:32px 18px"><div style="background:#fff;border:1px solid #d9e2e5;border-radius:8px;padding:28px"><div style="font-size:22px;font-weight:700;color:#087f8c">SiteBrush</div><h1 style="font-size:26px;margin:24px 0 8px">Invoice ` + template.HTMLEscapeString(invoice.Number) + `</h1><p style="color:#607078">` + template.HTMLEscapeString(invoice.ServerName) + ` · ` + template.HTMLEscapeString(invoice.PeriodStart) + ` - ` + template.HTMLEscapeString(invoice.PeriodEnd) + `</p><div style="font-size:30px;font-weight:700;margin:24px 0">` + template.HTMLEscapeString(amountLabel) + `</div><p>Payment due: <strong>` + template.HTMLEscapeString(invoice.DueAt) + `</strong></p><p><a href="` + template.HTMLEscapeString(invoiceURL) + `" style="display:inline-block;background:#087f8c;color:white;text-decoration:none;padding:12px 18px;border-radius:6px">View invoice and pay</a></p><p style="margin-top:28px;font-size:13px;color:#607078"><a href="` + template.HTMLEscapeString(scheduleURL) + `">Choose invoice day and payment term</a></p></div></div></body></html>`
	return mailout.Message{From: fromAddress, To: invoice.CustomerEmail, Subject: "SiteBrush invoice " + invoice.Number, Body: textBody, HTMLBody: htmlBody}
}

