func (a *App) preparedHostingAndSupportPanelSnapshot() (hostingAndSupportPanelSnapshot, bool) {
	if a == nil || a.hostingAndSupportPanel == nil {
		return hostingAndSupportPanelSnapshot{}, false
	}
	reply := make(chan hostingAndSupportPanelResponse, 1)
	a.hostingAndSupportPanel <- hostingAndSupportPanelRequest{kind: "get", reply: reply}
	response := <-reply
	return response.snapshot, response.err == nil
}

func (a *App) applyPreparedHostingAndSupportQuotaChange(quotaChange siteQuotaRow) {
	if a == nil || a.hostingAndSupportPanel == nil {
		return
	}
	reply := make(chan hostingAndSupportPanelResponse, 1)
	a.hostingAndSupportPanel <- hostingAndSupportPanelRequest{kind: "quota_changed", quotaChange: quotaChange, reply: reply}
	response := <-reply
	if response.err != nil {
		log.Printf("hosting panel quota snapshot save failed: %v", response.err)
	}
}

func (a *App) applyPreparedExpensePolicy(costPolicy expenses.ServerPolicy) {
	if a == nil || a.hostingAndSupportPanel == nil {
		return
	}
	reply := make(chan hostingAndSupportPanelResponse, 1)
	a.hostingAndSupportPanel <- hostingAndSupportPanelRequest{kind: "expense_policy_changed", costPolicy: costPolicy, reply: reply}
	response := <-reply
	if response.err != nil {
		log.Printf("expenses panel policy snapshot save failed: %v", response.err)
	}
}

func (a *App) saveHostingAndSupportPanelSnapshot(snapshot hostingAndSupportPanelSnapshot) error {
	payload, err := json.Marshal(snapshot)
	if err != nil {
		return err
	}
	return a.withServerControlDatabaseWrite(context.Background(), "expenses-snapshot-save", func(database *sql.DB) error {
		return (hostingandsupport.Store{DB: database}).SavePanelSnapshot(context.Background(), hostingandsupport.PanelSnapshotRecord{
			Version: hostingAndSupportPanelSnapshotVersion, PayloadJSON: string(payload), BuiltAt: snapshot.BuiltAt,
		})
	})
}

func (a *App) hostingAndSupportDemoPaymentPage(w http.ResponseWriter, r *http.Request) {
	invoiceNumber := strings.TrimSpace(r.URL.Query().Get("invoice"))
	if invoiceNumber == "" || strings.ContainsAny(invoiceNumber, "\r\n<>") {
		http.Error(w, "invoice is required", http.StatusBadRequest)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = io.WriteString(w, `<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SiteBrush.com demo payment</title><link href="/p/static/technical_pages.css" rel="stylesheet"></head><body class="technical-page bg-body"><main class="container billing-page py-5"><section class="card billing-card"><div class="card-body"><p class="text-muted">SiteBrush.com demo payments</p><h1>Демо-оплата счёта `+template.HTMLEscapeString(invoiceNumber)+`</h1><p>Платёжная страница подготовлена как демо-настройка первого этапа. Реальное списание здесь не выполняется.</p><a class="btn btn-primary" href="/?expenses">Вернуться в «Серверы и расходы»</a></div></section></main></body></html>`)
}

func (a *App) redirectToHostingAndSupportMainDomain(w http.ResponseWriter, r *http.Request) bool {
	mainDomain := a.hostingAndSupportMainDomain(r.Context())
	requestDomain := normalizeHostingAndSupportMainDomain(domainFromRequest(r))
	if mainDomain == "" || requestDomain == "" || sameHostingAndSupportDomain(mainDomain, requestDomain) {
		return false
	}
	redirectURL := *r.URL
	redirectURL.Scheme = requestScheme(r)
	redirectURL.Host = hostingAndSupportRedirectHost(mainDomain, r.Host)
	statusCode := http.StatusFound
	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		statusCode = http.StatusTemporaryRedirect
	}
	httpsecurity.RedirectExternal(w, r, &redirectURL, statusCode)
	return true
}

func (a *App) hostingAndSupportMainDomain(ctx context.Context) string {
	if snapshot, found := a.preparedHostingAndSupportPanelSnapshot(); found && strings.TrimSpace(snapshot.MainDomain) != "" {
		return normalizeHostingAndSupportMainDomain(snapshot.MainDomain)
	}
	mainDomain := ""
	_ = a.withServerControlDatabaseRead(ctx, "hosting-main-domain", func(database *sql.DB) error {
		if ownerDomain, found := (hostingandsupport.Store{DB: database}).OwnerDomain(ctx); found {
			mainDomain = normalizeHostingAndSupportMainDomain(ownerDomain)
		}
		return nil
	})
	if mainDomain != "" {
		return mainDomain
	}
	domain, email, found := a.firstExistingSiteAdmin(ctx)
	if found {
		_ = a.withServerControlDatabaseWrite(ctx, "hosting-promote-owner", func(database *sql.DB) error {
			(hostingandsupport.Store{DB: database}).PromoteOwnerIfMissing(ctx, domain, email)
			return nil
		})
		return normalizeHostingAndSupportMainDomain(domain)
	}
	return "localhost"
}

func hostingAndSupportRedirectHost(mainDomain string, requestHost string) string {
	mainDomain = normalizeHostingAndSupportMainDomain(mainDomain)
	if mainDomain == "" {
		return strings.TrimSpace(requestHost)
	}
	_, requestPort, err := net.SplitHostPort(strings.TrimSpace(requestHost))
	if err != nil || requestPort == "" {
		return mainDomain
	}
	return net.JoinHostPort(mainDomain, requestPort)
}

func expensesActionWantsJSON(r *http.Request) bool {
	return strings.Contains(r.Header.Get("Accept"), "application/json") || r.FormValue("billing_ajax") == "1"
}

func expensesActionStatusWasSaved(r *http.Request, status string) bool {
	translations := translationsForRequest(r)
	action := strings.TrimSpace(r.FormValue("billing_action"))
	status = strings.TrimSpace(status)
	switch action {
	case "settings", "registration_settings", "service_mail_settings", "demo_settings":
		return status == translationOrDefault(translations, "billing_status_settings_saved", "Billing settings saved.")
	case "update_site":
		domain := normalizeQuotaDomainName(r.FormValue("domain"))
		return domain != "" && status == fmt.Sprintf(translationOrDefault(translations, "billing_status_site_settings_saved", "Site %s settings were saved."), domain)
	case "update_site_quota":
		domain := normalizeQuotaDomainName(r.FormValue("domain"))
		return domain != "" && status == fmt.Sprintf(translationOrDefault(translations, "billing_status_site_settings_saved", "Site %s settings were saved."), domain)
	case "save_plan":
		return status == translationOrDefault(translations, "billing_status_plan_saved", "Plan saved.")
	case "update_backup_retention":
		return status == translationOrDefault(translations, "billing_status_backup_retention_saved", "Backup retention was saved.")
	case "server_cost_policy", "save_server_expense_policy":
		return status == translationOrDefault(translations, "expenses_server_policy_saved", "Server expense settings saved.")
	}
	return false
}

