func (a *App) hostingAndSupportClients(ctx context.Context, billingStore hostingandsupport.Store, siteRows []hostingandsupport.Site, installations []hostingandsupport.ServiceMailInstallation, events []hostingandsupport.ServiceMailEvent, clientHostings []hostingandsupport.ClientHosting, invoices []hostingandsupport.Invoice, commissionBPS int, _ []string) []hostingAndSupportClientView {
	installationDomain := make(map[string]string)
	installationIP := make(map[string]string)
	for _, installation := range installations {
		installationDomain[strings.TrimSpace(installation.InstallationID)] = normalizeDomainName(installation.LastDomain)
		installationIP[strings.TrimSpace(installation.InstallationID)] = strings.TrimSpace(installation.LastIP)
	}
	clientsByEmail := make(map[string]*hostingAndSupportClientAccumulator)
	clientsByDomain := make(map[string]*hostingAndSupportClientAccumulator)
	knownSiteDomains := make(map[string]struct{})
	for _, siteRow := range siteRows {
		if siteRow.IsDemo {
			continue
		}
		siteAdminEmails := hostingandsupport.SplitEmailList(siteRow.AdminEmails)
		domain := normalizeDomainName(siteRow.Domain)
		if domain == "" {
			continue
		}
		knownSiteDomains[domain] = struct{}{}
		client := hostingAndSupportClientForEmails(clientsByEmail, siteAdminEmails)
		if client == nil {
			continue
		}
		client.sites[domain] = hostingAndSupportClientSiteSource{
			aliases:           siteRow.Aliases,
			url:               siteRow.URL,
			usedBytes:         siteRow.UsedBytes,
			usedLabel:         siteRow.UsedLabel,
			limitLabel:        siteRow.LimitLabel,
			billingUsageLabel: siteRow.BillingUsageLabel,
			billingPriceLabel: siteRow.BillingPriceLabel,
			billingStatusText: siteRow.BillingStatusText,
			billingAmount:     siteRow.BillingAmount,
			billingCurrency:   siteRow.BillingCurrency,
			billingBillable:   siteRow.BillingBillable,
		}
		client.domains[domain] = struct{}{}
		clientsByDomain[domain] = client
	}
	for _, installation := range installations {
		domain := normalizeDomainName(installation.LastDomain)
		client := clientsByDomain[domain]
		if client == nil {
			continue
		}
		if installation.InstallationID != "" {
			client.installations[strings.TrimSpace(installation.InstallationID)] = struct{}{}
		}
		if installation.LastIP != "" {
			sourceIP := strings.TrimSpace(installation.LastIP)
			client.ips[sourceIP] = a.hostingAndSupportClientIP(ctx, sourceIP)
			siteSource := client.sites[domain]
			siteSource.ip = sourceIP
			client.sites[domain] = siteSource
		}
	}
	for _, event := range events {
		domain := normalizeDomainName(event.SourceDomain)
		if domain == "" {
			domain = installationDomain[strings.TrimSpace(event.InstallationID)]
		}
		email := strings.ToLower(strings.TrimSpace(event.Recipient))
		client := clientsByDomain[domain]
		if client == nil && email != "" {
			client = hostingAndSupportClientByEmail(clientsByEmail, email)
		}
		if client == nil {
			continue
		}
		if email != "" {
			client.emails[email] = struct{}{}
			if client.primaryEmail == "" || serviceMailEventIsNewerIdentity(event.CodeKind) {
				client.primaryEmail = email
			}
		}
		if domain != "" {
			client.domains[domain] = struct{}{}
			if _, found := client.sites[domain]; !found {
				client.sites[domain] = hostingAndSupportClientSiteSource{}
			}
		}
		if event.InstallationID != "" {
			client.installations[strings.TrimSpace(event.InstallationID)] = struct{}{}
		}
		sourceIP := firstNonEmpty(strings.TrimSpace(event.SourceIP), installationIP[strings.TrimSpace(event.InstallationID)])
		if sourceIP != "" {
			client.ips[sourceIP] = a.hostingAndSupportClientIP(ctx, sourceIP)
			if domain != "" {
				siteSource := client.sites[domain]
				siteSource.ip = sourceIP
				client.sites[domain] = siteSource
			}
		}
		if len(client.events) < 12 {
			client.events = append(client.events, hostingAndSupportClientEventView{
				Kind:      event.CodeKind,
				Status:    event.Status,
				Email:     email,
				Domain:    domain,
				IP:        sourceIP,
				CreatedAt: event.CreatedAt,
				Error:     event.Error,
			})
		}
	}
	for _, clientHosting := range clientHostings {
		remoteExpenseSites := make([]expenses.SiteUsage, 0, len(clientHosting.Sites))
		for _, site := range clientHosting.Sites {
			remoteExpenseSites = append(remoteExpenseSites, expenses.SiteUsage{
				Key: site.Domain, UsedBytes: site.UsedBytes,
				Excluded: site.IsDemo,
			})
		}
		remoteExpensePolicy := clientHosting.ExpensePolicy
		remoteExpensePolicy.DiskTotalBytes = clientHosting.DiskTotalBytes
		remoteExpenseAllocations := expenses.AllocateMonthlyExpense(remoteExpensePolicy, remoteExpenseSites)
		for _, site := range clientHosting.Sites {
			siteEmails := append([]string{site.OwnerEmail}, site.AdminEmails...)
			if site.IsDemo {
				continue
			}
			client := hostingAndSupportClientForEmails(clientsByEmail, siteEmails)
			if client == nil {
				continue
			}
			client.installations[strings.TrimSpace(clientHosting.InstallationID)] = struct{}{}
			if strings.TrimSpace(clientHosting.ServerIP) != "" {
				client.ips[strings.TrimSpace(clientHosting.ServerIP)] = a.hostingAndSupportClientIP(ctx, clientHosting.ServerIP)
			}
			domain := normalizeDomainName(site.Domain)
			if domain == "" {
				continue
			}
			client.domains[domain] = struct{}{}
			siteSource := client.sites[domain]
			if site.UsedBytes > siteSource.usedBytes {
				siteSource.usedBytes = site.UsedBytes
				siteSource.usedLabel = site.UsedLabel
			}
			if siteSource.usedLabel == "" {
				siteSource.usedLabel = site.UsedLabel
			}
			if site.LimitBytes > 0 {
				siteSource.limitBytes = site.LimitBytes
				siteSource.limitLabel = site.LimitLabel
			}
			allocation := remoteExpenseAllocations.Sites[site.Domain]
			siteSource.billingUsageLabel = hostingandsupport.BillingUsageLabel(siteSource.usedBytes)
			siteSource.billingAmount = hostingandsupport.MoneyAmount(allocation.ExpenseShareMinor)
			siteSource.billingCurrency = remoteExpensePolicy.Currency
			siteSource.billingBillable = allocation.ExpenseShareMinor > 0
			if allocation.Free {
				siteSource.billingPriceLabel = hostingandsupport.MoneyLabel(0, remoteExpensePolicy.Currency)
				siteSource.billingStatusText = "бесплатно до " + hostingandsupport.FormatFileSize(remoteExpensePolicy.FreeSiteThresholdBytes)
			} else if allocation.ExpenseShareMinor > 0 {
				siteSource.billingPriceLabel = hostingandsupport.MoneyLabel(allocation.ExpenseShareMinor, remoteExpensePolicy.Currency) + "/мес"
				siteSource.billingStatusText = "доля расходов"
			}
			siteSource.hostingOwner = firstNonEmpty(clientHosting.OwnerEmail, siteSource.hostingOwner)
			siteSource.hostingServer = firstNonEmpty(clientHosting.ServerDomain, clientHosting.InstallationID, siteSource.hostingServer)
			siteSource.ip = firstNonEmpty(clientHosting.ServerIP, siteSource.ip)
			siteSource.dnsMatchesServer = site.DNSMatchesServer
			siteSource.dnsCheckAvailable = strings.TrimSpace(site.ReachabilityCheckedAt) != "" || site.DNSMatchesServer
			client.sites[domain] = siteSource
		}
	}
	clients := make([]hostingAndSupportClientView, 0, len(clientsByEmail))
	seenClients := make(map[*hostingAndSupportClientAccumulator]struct{})
	for _, user := range clientsByEmail {
		if _, seen := seenClients[user]; seen {
			continue
		}
		seenClients[user] = struct{}{}
		siteViews := hostingAndSupportClientSiteViews(user.sites, knownSiteDomains)
		hostingViews := hostingAndSupportClientHostingViews(user.emails, clientHostings)
		view := hostingAndSupportClientView{
			PrimaryEmail:  firstNonEmpty(user.primaryEmail, firstStringFromSet(user.emails)),
			Emails:        sortedStringsFromSet(user.emails),
			Domains:       sortedStringsFromSet(user.domains),
			Sites:         siteViews,
			SiteCount:     len(siteViews),
			Invoices:      hostingAndSupportClientInvoiceViews(invoices, user.emails, user.domains),
			Hostings:      hostingViews,
			HostingCount:  len(hostingViews),
			Installations: sortedStringsFromSet(user.installations),
			IPs:           sortedIPViews(user.ips),
			Events:        user.events,
		}
		view.EmailCount = len(view.Emails)
		view.InvoiceCount = len(view.Invoices)
		view.DomainCount = len(view.Domains)
		view.RelayInstallationCount = len(view.Installations)
		view.InstallationCount = len(hostingViews)
		for _, site := range siteViews {
			if view.InstallationCount == 0 && site.RealInstallation {
				view.InstallationCount++
			}
			if site.HostingSitebrush {
				view.HostingSitebrushCount++
			}
		}
		view.FilterRoles = strings.Join(hostingAndSupportClientFilterRoles(view), " ")
		view.FilterStatuses = strings.Join(hostingAndSupportClientFilterStatuses(view), " ")
		view.FilterPaidStatuses = strings.Join(hostingAndSupportClientFilterPaidStatuses(view), " ")
		if hostingAndSupportClientHasOverLimitSite(view) {
			view.FilterOverLimit = "yes"
		} else {
			view.FilterOverLimit = "no"
		}
		if hostingAndSupportClientHasEventsOrErrors(view) {
			view.FilterHasEvents = "yes"
		} else {
			view.FilterHasEvents = "no"
		}
		view.IPCount = len(view.IPs)
		view.MapPointsJSON = hostingAndSupportClientMapPointsJSON(view.IPs)
		monthlyDueByCurrency := make(map[string]int64)
		for _, site := range view.Sites {
			view.TotalStorageBytes += site.UsedBytes
			if site.BillingBillable {
				view.PaidSiteCount++
				siteAmountMinor := hostingandsupport.MoneyMinor(site.BillingAmount)
				view.MonthlyDueMinor += siteAmountMinor
				currency := strings.ToUpper(strings.TrimSpace(site.BillingCurrency))
				if currency == "" {
					currency = "EUR"
				}
				monthlyDueByCurrency[currency] += siteAmountMinor
			}
		}
		view.TotalStorageLabel = formatFileSize(view.TotalStorageBytes)
		view.MonthlyDueLabel = hostingandsupport.MoneyTotalsLabel(monthlyDueByCurrency)
		if billingStore.DB != nil {
			billingCustomer, customerErr := billingStore.EnsureBillingCustomer(ctx, view.PrimaryEmail, view.Emails)
			if customerErr == nil {
				applyHostingAndSupportClientBilling(ctx, billingStore, &view, billingCustomer)
			}
		}
		expectedCommissionByCurrency := make(map[string]int64, len(monthlyDueByCurrency))
		for currency, amountMinor := range monthlyDueByCurrency {
			expectedCommissionByCurrency[currency] = amountMinor * int64(commissionBPS) / 10000
		}
		view.ExpectedCommissionLabel = hostingandsupport.MoneyTotalsLabel(expectedCommissionByCurrency)
		clients = append(clients, view)
	}
	sort.Slice(clients, func(left, right int) bool {
		if clients[left].InstallationCount != clients[right].InstallationCount {
			return clients[left].InstallationCount > clients[right].InstallationCount
		}
		if clients[left].SiteCount != clients[right].SiteCount {
			return clients[left].SiteCount > clients[right].SiteCount
		}
		if clients[left].RelayInstallationCount != clients[right].RelayInstallationCount {
			return clients[left].RelayInstallationCount > clients[right].RelayInstallationCount
		}
		return clients[left].PrimaryEmail < clients[right].PrimaryEmail
	})
	return clients
}

func (a *App) enrichHostingAndSupportClientsWithBilling(ctx context.Context, billingStore hostingandsupport.Store, clients []hostingAndSupportClientView) {
	for clientIndex := range clients {
		billingCustomer, err := billingStore.EnsureBillingCustomer(ctx, clients[clientIndex].PrimaryEmail, clients[clientIndex].Emails)
		if err == nil {
			applyHostingAndSupportClientBilling(ctx, billingStore, &clients[clientIndex], billingCustomer)
		}
	}
}

func applyHostingAndSupportClientBilling(ctx context.Context, billingStore hostingandsupport.Store, view *hostingAndSupportClientView, billingCustomer hostingandsupport.BillingCustomer) {
	view.BillingCustomerID = billingCustomer.ID
	view.InvoiceDay = billingCustomer.InvoiceDay
	view.PaymentTermDays = billingCustomer.PaymentTermDays
	view.BillingTimezone = billingCustomer.Timezone
	view.AutomaticBillingEnabled = billingCustomer.AutomaticEnabled
	financialTotals := billingStore.BillingCustomerFinancialTotals(ctx, billingCustomer, time.Now().UTC())
	view.PaidThisMonthLabel = hostingandsupport.MoneyTotalsLabel(financialTotals.CoveredThisMonthByCurrency)
	view.LifetimePaidLabel = hostingandsupport.MoneyTotalsLabel(financialTotals.LifetimeCoveredByCurrency)
	view.CommissionThisMonthLabel = hostingandsupport.MoneyLabel(financialTotals.CommissionThisMonthMinor, "EUR")
	view.LifetimeCommissionLabel = hostingandsupport.MoneyLabel(financialTotals.LifetimeCommissionMinor, "EUR")
}

func hostingAndSupportClientFilterRoles(client hostingAndSupportClientView) []string {
	roles := make(map[string]struct{})
	if client.SiteCount > 0 {
		roles["site_admin"] = struct{}{}
	}
	for _, hosting := range client.Hostings {
		for _, role := range hosting.ClientRoles {
			roleName := strings.TrimSpace(role.Role)
			if roleName != "" {
				roles[roleName] = struct{}{}
			}
		}
	}
	return sortedStringsFromSet(roles)
}

func hostingAndSupportClientFilterStatuses(client hostingAndSupportClientView) []string {
	statuses := make(map[string]struct{})
	for _, site := range client.Sites {
		status := strings.TrimSpace(site.Status)
		if status != "" {
			statuses[status] = struct{}{}
		}
	}
	for _, hosting := range client.Hostings {
		status := strings.TrimSpace(hosting.ServerStatusLabel)
		if status != "" {
			statuses[status] = struct{}{}
		}
	}
	return sortedStringsFromSet(statuses)
}

func hostingAndSupportClientFilterPaidStatuses(client hostingAndSupportClientView) []string {
	statuses := make(map[string]struct{})
	for _, site := range client.Sites {
		if site.BillingBillable {
			statuses["paid"] = struct{}{}
		} else {
			statuses["free"] = struct{}{}
		}
	}
	return sortedStringsFromSet(statuses)
}

func hostingAndSupportClientInvoiceViews(invoices []hostingandsupport.Invoice, emails map[string]struct{}, domains map[string]struct{}) []hostingAndSupportClientInvoiceView {
	views := make([]hostingAndSupportClientInvoiceView, 0, len(invoices))
	for _, invoice := range invoices {
		email := strings.ToLower(strings.TrimSpace(invoice.CustomerEmail))
		domain := normalizeDomainName(invoice.Domain)
		_, emailFound := emails[email]
		_, domainFound := domains[domain]
		if !emailFound && !domainFound {
			continue
		}
		views = append(views, hostingAndSupportClientInvoiceView{
			Number:       invoice.Number,
			Domain:       domain,
			AmountLabel:  strings.TrimSpace(invoice.Amount + " " + invoice.Currency),
			StatusLabel:  hostingandsupport.InvoiceStatusLabel(invoice.Status),
			PeriodLabel:  hostingandsupport.InvoicePeriodLabel(invoice),
			HistoryLabel: hostingandsupport.InvoiceHistoryLabel(invoice),
		})
	}
	return views
}

func hostingAndSupportClientHasOverLimitSite(client hostingAndSupportClientView) bool {
	for _, site := range client.Sites {
		if site.OverLimit {
			return true
		}
	}
	for _, hosting := range client.Hostings {
		for _, site := range hosting.Hosting.Sites {
			if site.OverLimit {
				return true
			}
		}
	}
	return false
}

func hostingAndSupportClientHasEventsOrErrors(client hostingAndSupportClientView) bool {
	if len(client.Events) > 0 {
		return true
	}
	for _, hosting := range client.Hostings {
		if len(hosting.Hosting.Events) > 0 {
			return true
		}
	}
	return false
}

func hostingAndSupportClientHostingViews(emails map[string]struct{}, clientHostings []hostingandsupport.ClientHosting) []hostingAndSupportClientHostingView {
	views := make([]hostingAndSupportClientHostingView, 0, 2)
	for _, clientHosting := range clientHostings {
		if hostingandsupport.HostingBelongsToClientEmails(clientHosting, emails) {
			views = append(views, buildHostingAndSupportClientHostingView(clientHosting, emails, time.Now().UTC()))
		}
	}
	sort.Slice(views, func(left, right int) bool {
		if views[left].Hosting.TotalUsedBytes != views[right].Hosting.TotalUsedBytes {
			return views[left].Hosting.TotalUsedBytes > views[right].Hosting.TotalUsedBytes
		}
		return views[left].Hosting.InstallationID < views[right].Hosting.InstallationID
	})
	return views
}

func buildHostingAndSupportClientHostingView(clientHosting hostingandsupport.ClientHosting, emails map[string]struct{}, now time.Time) hostingAndSupportClientHostingView {
	stale := hostingandsupport.HostingSyncIsStale(clientHosting.LastSeenAt, now)
	syncStatusLabel := "синхронизировано"
	syncStatusClass := "billing-sync-ok"
	if strings.TrimSpace(clientHosting.LastSeenAt) == "" {
		syncStatusLabel = "нет синхронизации"
		syncStatusClass = "billing-sync-stale"
	} else if stale {
		syncStatusLabel = "устарело"
		syncStatusClass = "billing-sync-stale"
	}
	return hostingAndSupportClientHostingView{
		Hosting:           clientHosting,
		ServerDisplayName: hostingandsupport.HostingDisplayName(clientHosting),
		ServerStatusLabel: hostingandsupport.HostingStatusLabel(clientHosting),
		SyncStatusLabel:   syncStatusLabel,
		SyncStatusClass:   syncStatusClass,
		Stale:             stale,
		ClientRoles:       hostingandsupport.ClientRolesForEmails(clientHosting, emails),
	}
}

func hostingAndSupportClientByEmail(clients map[string]*hostingAndSupportClientAccumulator, email string) *hostingAndSupportClientAccumulator {
	email = strings.ToLower(strings.TrimSpace(email))
	if client := clients[email]; client != nil {
		return client
	}
	client := &hostingAndSupportClientAccumulator{
		primaryEmail:  email,
		emails:        map[string]struct{}{email: {}},
		domains:       make(map[string]struct{}),
		sites:         make(map[string]hostingAndSupportClientSiteSource),
		installations: make(map[string]struct{}),
		ips:           make(map[string]hostingAndSupportClientIPView),
	}
	clients[email] = client
	return client
}

func hostingAndSupportClientForEmails(clients map[string]*hostingAndSupportClientAccumulator, emails []string) *hostingAndSupportClientAccumulator {
	normalizedEmails := make([]string, 0, len(emails))
	for _, email := range emails {
		email = strings.ToLower(strings.TrimSpace(email))
		if email != "" {
			normalizedEmails = append(normalizedEmails, email)
		}
	}
	if len(normalizedEmails) == 0 {
		return nil
	}
	var client *hostingAndSupportClientAccumulator
	for _, email := range normalizedEmails {
		if clients[email] != nil {
			client = clients[email]
			break
		}
	}
	if client == nil {
		client = hostingAndSupportClientByEmail(clients, normalizedEmails[0])
	}
	for _, email := range normalizedEmails {
		client.emails[email] = struct{}{}
		clients[email] = client
	}
	return client
}

func hostingAndSupportClientSiteViews(sites map[string]hostingAndSupportClientSiteSource, knownSiteDomains map[string]struct{}) []hostingAndSupportClientSiteView {
	views := make([]hostingAndSupportClientSiteView, 0, len(sites))
	for domain, siteSource := range sites {
		view := hostingAndSupportClientSiteView{
			Domain:            domain,
			URL:               strings.TrimSpace(siteSource.url),
			UsedBytes:         siteSource.usedBytes,
			UsedLabel:         siteSource.usedLabel,
			LimitBytes:        siteSource.limitBytes,
			LimitLabel:        siteSource.limitLabel,
			BillingUsageLabel: siteSource.billingUsageLabel,
			BillingPriceLabel: siteSource.billingPriceLabel,
			BillingStatusText: siteSource.billingStatusText,
			BillingAmount:     siteSource.billingAmount,
			BillingCurrency:   siteSource.billingCurrency,
			BillingBillable:   siteSource.billingBillable,
			HostingOwner:      siteSource.hostingOwner,
			HostingServer:     siteSource.hostingServer,
			InstallationIP:    strings.TrimSpace(siteSource.ip),
		}
		if view.UsedLabel == "" {
			view.UsedLabel = formatFileSize(view.UsedBytes)
		}
		if view.BillingUsageLabel == "" {
			billingPrice := hostingandsupport.BillingPriceForUsedBytes(view.UsedBytes)
			view.BillingUsageLabel = hostingandsupport.BillingUsageLabel(view.UsedBytes)
			view.BillingPriceLabel = billingPrice.PriceLabel
			view.BillingStatusText = billingPrice.StatusText
			view.BillingAmount = billingPrice.Amount
			view.BillingCurrency = billingPrice.Currency
			view.BillingBillable = billingPrice.Billable
		}
		if view.LimitLabel == "" && view.LimitBytes > 0 {
			view.LimitLabel = formatFileSize(view.LimitBytes)
		}
		view.OverLimit = view.LimitBytes > 0 && view.UsedBytes > view.LimitBytes
		if hostingandsupport.DomainIsLocalDevelopment(domain, view.InstallationIP) {
			view.LocalDevelopment = true
			view.Status = hostingandsupport.InstallationStatus(domain, view.InstallationIP)
		} else if parentDomain := hostingandsupport.KnownParentDomain(domain, knownSiteDomains); parentDomain != "" {
			view.HostingSitebrush = true
			view.ParentDomain = parentDomain
			view.Status = "хостинг SiteBrush"
		} else if siteSource.dnsCheckAvailable && siteSource.dnsMatchesServer {
			view.RealInstallation = true
			view.Status = "реальная установка"
		} else {
			view.LocalDevelopment = true
			view.Status = "домен не указывает на IP установки"
		}
		views = append(views, view)
	}
	sort.Slice(views, func(left, right int) bool {
		if views[left].UsedBytes != views[right].UsedBytes {
			return views[left].UsedBytes > views[right].UsedBytes
		}
		return views[left].Domain < views[right].Domain
	})
	return views
}

func (a *App) hostingAndSupportClientIP(ctx context.Context, ip string) hostingAndSupportClientIPView {
	view := hostingAndSupportClientIPView{IP: strings.TrimSpace(ip), Provider: "unknown"}
	if a == nil || a.geoIP == nil {
		return view
	}
	location, found := a.geoIP.Lookup(ctx, ip)
	if !found {
		return view
	}
	view.Country = strings.TrimSpace(location.CountryCode)
	view.City = strings.TrimSpace(location.City)
	view.Provider = firstNonEmpty(location.Source, "unknown")
	view.Latitude = location.Latitude
	view.Longitude = location.Longitude
	return view
}

func serviceMailEventIsNewerIdentity(codeKind string) bool {
	switch strings.TrimSpace(codeKind) {
	case "recipient_verified", "email_change", "email_confirm":
		return true
	default:
		return false
	}
}

func firstStringFromSet(values map[string]struct{}) string {
	for value := range values {
		return value
	}
	return ""
}

func sortedStringsFromSet(values map[string]struct{}) []string {
	result := make([]string, 0, len(values))
	for value := range values {
		if strings.TrimSpace(value) != "" {
			result = append(result, value)
		}
	}
	sort.Strings(result)
	return result
}

func sortedIPViews(values map[string]hostingAndSupportClientIPView) []hostingAndSupportClientIPView {
	result := make([]hostingAndSupportClientIPView, 0, len(values))
	for _, value := range values {
		result = append(result, value)
	}
	sort.Slice(result, func(left, right int) bool {
		return result[left].IP < result[right].IP
	})
	return result
}

func hostingAndSupportClientMapPointsJSON(ips []hostingAndSupportClientIPView) template.JS {
	points := make([]map[string]any, 0, len(ips))
	for _, ip := range ips {
		if ip.Latitude == 0 && ip.Longitude == 0 {
			continue
		}
		points = append(points, map[string]any{
			"ip":       ip.IP,
			"country":  ip.Country,
			"city":     ip.City,
			"provider": ip.Provider,
			"lat":      ip.Latitude,
			"lng":      ip.Longitude,
		})
	}
	payload, err := json.Marshal(points)
	if err != nil {
		return template.JS("[]")
	}
	return template.JS(payload)
}

func (a *App) hostingAndSupportSiteRows(ctx context.Context, controlDatabase *sql.DB, plans []hostingandsupport.Plan, assignments map[string]hostingandsupport.ServiceAssignment, deletionBackupSizesByDomain map[string]int64, currentDomain string, demoDomain string, mainDomain string) ([]hostingandsupport.Site, error) {
	rows, err := a.listSiteQuotaRowsWithControlDatabase(ctx, controlDatabase)
	if err != nil {
		return nil, err
	}
	usages := make([]hostingandsupport.SiteUsage, 0, len(rows))
	for _, row := range rows {
		billingUsedBytes := a.managedSiteBillingDiskBytes(row, deletionBackupSizesByDomain)
		usages = append(usages, hostingandsupport.SiteUsage{
			Domain:       row.Domain,
			Aliases:      row.Aliases,
			UsedBytes:    billingUsedBytes,
			LimitBytes:   row.LimitBytes,
			AdminEmails:  row.AdminEmails,
			DatabasePath: row.DatabasePath,
		})
	}
	siteRows := hostingandsupport.BuildSitesWithDemoAndMainDomain(usages, plans, assignments, currentDomain, demoDomain, mainDomain)
	rowByDomain := make(map[string]siteQuotaRow, len(rows))
	for _, row := range rows {
		rowByDomain[row.Domain] = row
	}
	for siteIndex := range siteRows {
		if row, found := rowByDomain[siteRows[siteIndex].Domain]; found {
			deletionSizeBytes := a.managedSiteBillingDiskBytes(row, deletionBackupSizesByDomain)
			siteRows[siteIndex].DeletionSizeBytes = deletionSizeBytes
			siteRows[siteIndex].DeletionSizeLabel = formatFileSize(deletionSizeBytes)
		}
		siteRows[siteIndex].URL = a.hostingAndSupportSiteURL(siteRows[siteIndex].Domain)
	}
	return siteRows, nil
}

func visibleHostingAndSupportLocalSites(sites []hostingandsupport.Site, demoSettings demo.Settings) []hostingandsupport.Site {
	disabledDemoDomain := normalizeDomainName(demoSettings.Domain)
	if demoSettings.Enabled || disabledDemoDomain == "" {
		return sites
	}
	visibleSites := make([]hostingandsupport.Site, 0, len(sites))
	for _, site := range sites {
		if normalizeDomainName(site.Domain) == disabledDemoDomain {
			continue
		}
		visibleSites = append(visibleSites, site)
	}
	return visibleSites
}

func hostingAndSupportSplitSiteRequests(siteRequests []hostingandsupport.SiteRequest) ([]hostingandsupport.SiteRequest, map[string]hostingandsupport.SiteRequest) {
	pendingSiteRequests := make([]hostingandsupport.SiteRequest, 0, len(siteRequests))
	approvedSiteRequestsByDomain := make(map[string]hostingandsupport.SiteRequest)
	for _, siteRequest := range siteRequests {
		status := strings.TrimSpace(siteRequest.Status)
		switch status {
		case "pending":
			pendingSiteRequests = append(pendingSiteRequests, siteRequest)
		case "approved":
			domain := normalizeQuotaDomainName(siteRequest.Domain)
			if domain != "" {
				approvedSiteRequestsByDomain[domain] = siteRequest
			}
		}
	}
	return pendingSiteRequests, approvedSiteRequestsByDomain
}

func hostingAndSupportAttachApprovedSiteRequests(siteRows []hostingandsupport.Site, approvedSiteRequestsByDomain map[string]hostingandsupport.SiteRequest) {
	for siteIndex := range siteRows {
		domain := normalizeQuotaDomainName(siteRows[siteIndex].Domain)
		siteRequest, found := approvedSiteRequestsByDomain[domain]
		if !found {
			continue
		}
		siteRows[siteIndex].HasSiteRequest = true
		siteRows[siteIndex].SiteRequest = siteRequest
	}
}

func (a *App) hostingAndSupportSiteURL(domain string) string {
	normalizedDomain := normalizeDomainName(domain)
	if normalizedDomain == "" {
		return ""
	}
	scheme := "http"
	if a != nil && a.autoCertCachedCertificateValid(normalizedDomain, time.Now()) {
		scheme = "https"
	}
	return scheme + "://" + normalizedDomain + "/"
}

func publicTrialSignupEmbedHTML(r *http.Request, translations map[string]string) string {
	endpointURL := absoluteURLForPath(r, "/")
	scriptURL := "/p/static/site_copy.js?v=" + url.QueryEscape(publicTrialWidgetScriptVersion())
	config := map[string]any{"endpoint": endpointURL}
	configJSON, err := json.Marshal(config)
	if err != nil {
		configJSON = []byte(`{"endpoint":` + strconv.Quote(endpointURL) + `}`)
	}
	return `<form class="SiteBrushPublicTrialForm sitebrush-public-trial-form" data-sitebrush-public-trial-form>
  <p class="SiteBrushPublicTrialTitle sitebrush-public-trial-title" data-sitebrush-public-trial-title></p>
  <label class="SiteBrushPublicTrialField sitebrush-public-trial-field">
    <span class="SiteBrushPublicTrialLabel sitebrush-public-trial-label" data-sitebrush-public-trial-label></span>
    <input class="SiteBrushPublicTrialInput sitebrush-public-trial-input" data-sitebrush-public-trial-input type="text" name="source_url" autocomplete="url" inputmode="url" required>
  </label>
  <button class="SiteBrushPublicTrialButton sitebrush-public-trial-button" data-sitebrush-public-trial-submit type="submit"></button>
</form>
<script src="` + template.HTMLEscapeString(scriptURL) + `" data-sitebrush-live-asset></script>
<script>
(function () {
  var currentScript = document.currentScript;
  var formElement = currentScript && currentScript.parentNode
    ? currentScript.parentNode.querySelector("[data-sitebrush-public-trial-form]")
    : null;

  if (window.SiteBrushPublicTrial && formElement) {
    window.SiteBrushPublicTrial.attach(formElement, ` + string(configJSON) + `);
  }
})();
</script>`
}

func publicTrialWidgetScriptVersion() string {
	scriptBytes, err := embeddedWebFiles.ReadFile("web/static/site_copy.js")
	if err != nil {
		return CompileVersion
	}
	scriptHash := sha256.Sum256(scriptBytes)
	return hex.EncodeToString(scriptHash[:8])
}

