func siteAdminEmails(ctx context.Context, databasePath, domain string) []string {
	rawDatabase, err := sql.Open("sqlite", "file:"+databasePath)
	if err != nil {
		return nil
	}
	defer rawDatabase.Close()
	return siteAdminEmailsFromDatabase(ctx, rawDatabase, domain)
}

func siteAdminEmailsFromDatabase(ctx context.Context, database *sql.DB, domain string) []string {
	rows, err := database.QueryContext(ctx, `SELECT email FROM users WHERE domain=? AND is_admin=1 ORDER BY email`, domain)
	if err != nil {
		return nil
	}
	defer rows.Close()
	emails := make([]string, 0, 2)
	for rows.Next() {
		var email string
		if scanErr := rows.Scan(&email); scanErr == nil && strings.TrimSpace(email) != "" {
			emails = append(emails, strings.TrimSpace(email))
		}
	}
	return emails
}

