func (a *App) generateSitebrushComKeyFromForm(r *http.Request) string {
	privateKey, err := ecdh.X25519().GenerateKey(rand.Reader)
	if err != nil {
		return err.Error()
	}
	publicKeyText := base64.StdEncoding.EncodeToString(privateKey.PublicKey().Bytes())
	privateKeyText := base64.StdEncoding.EncodeToString(privateKey.Bytes())
	privateKeyPath, err := a.writeSitebrushComPrivateKeyFile(privateKeyText)
	if err != nil {
		return err.Error()
	}
	if err := a.withServerControlDatabaseWrite(r.Context(), "save-sitebrush-key", func(database *sql.DB) error {
		_, saveErr := (hostingandsupport.Store{DB: database}).SaveSitebrushComKey(r.Context(), publicKeyText, privateKeyPath)
		return saveErr
	}); err != nil {
		return err.Error()
	}
	return "sitebrush.com public key generated."
}

func (a *App) writeSitebrushComPrivateKeyFile(privateKeyText string) (string, error) {
	keysRootDirectory := filepath.Join(a.storageRootDir(), "keys")
	keyDirectory := filepath.Join(keysRootDirectory, "sitebrush.com")
	if err := a.mkdirAllInsideStorage(keyDirectory, 0o700); err != nil {
		return "", err
	}
	realKeysRootDirectory, err := a.existingPathInsideStorage(keysRootDirectory)
	if err != nil {
		return "", err
	}
	realKeyDirectory, err := a.existingPathInsideStorageSubtree(keysRootDirectory, keyDirectory)
	if err != nil {
		return "", err
	}
	if err := os.Chmod(realKeysRootDirectory, 0o700); err != nil {
		return "", err
	}
	if err := os.Chmod(realKeyDirectory, 0o700); err != nil {
		return "", err
	}
	privateKeyPath := filepath.Join(keyDirectory, "relay-x25519.private")
	temporaryPath := privateKeyPath + ".tmp"
	realPrivateKeyPath, err := a.writablePathInsideStorageSubtree(keyDirectory, privateKeyPath)
	if err != nil {
		return "", err
	}
	realTemporaryPath, err := a.writablePathInsideStorageSubtree(keyDirectory, temporaryPath)
	if err != nil {
		return "", err
	}
	if err := os.WriteFile(realTemporaryPath, []byte(strings.TrimSpace(privateKeyText)+"\n"), 0o600); err != nil {
		return "", err
	}
	if err := os.Chmod(realTemporaryPath, 0o600); err != nil {
		_ = os.Remove(realTemporaryPath)
		return "", err
	}
	if err := os.Rename(realTemporaryPath, realPrivateKeyPath); err != nil {
		_ = os.Remove(realTemporaryPath)
		return "", err
	}
	if err := os.Chmod(realPrivateKeyPath, 0o600); err != nil {
		return "", err
	}
	return realPrivateKeyPath, nil
}

func (a *App) migrateLegacySitebrushComPrivateKey(ctx context.Context) error {
	var publicKeyText string
	var privateKeyText string
	err := a.withServerControlDatabaseRead(ctx, "migrate-sitebrush-key-read", func(database *sql.DB) error {
		return database.QueryRowContext(ctx, `SELECT public_key,private_key FROM sitebrush_com_keys WHERE domain='sitebrush.com'`).Scan(&publicKeyText, &privateKeyText)
	})
	if err != nil || strings.TrimSpace(privateKeyText) == "" {
		return err
	}
	privateKeyPath, err := a.writeSitebrushComPrivateKeyFile(privateKeyText)
	if err != nil {
		return err
	}
	return a.withServerControlDatabaseWrite(ctx, "migrate-sitebrush-key-save", func(database *sql.DB) error {
		_, saveErr := (hostingandsupport.Store{DB: database}).SaveSitebrushComKey(ctx, publicKeyText, privateKeyPath)
		return saveErr
	})
}

