func (a *App) saveHostingAndSupportDemoSettings(r *http.Request) string {
	translations := translationsForRequest(r)
	demoDomain := normalizeQuotaDomainName(r.FormValue("demo_site_domain"))
	demoSourceURL, demoSourceErr := demo.NormalizeSourceURL(r.FormValue("demo_site_source_url"))
	if demoSourceErr != nil {
		return demoSourceErr.Error()
	}
	demoEnabled := r.FormValue("demo_site_enabled") == "1"
	if demoEnabled && demoDomain == "" {
		return translationOrDefault(translations, "billing_status_demo_domain_required", "Demo site domain is required.")
	}
	demoCopyWholeSite := demoCopyWholeSiteFromRequest(r)
	var previousDemoSettings demo.Settings
	err := a.withServerControlDatabaseWrite(r.Context(), "save-demo-settings", func(database *sql.DB) error {
		store := hostingandsupport.Store{DB: database}
		previousDemoSettings = (demo.Store{DB: database}).Settings(r.Context())
		if demoDomain != "" {
			if ownerDomain, found := store.OwnerDomain(r.Context()); found && normalizeDomainName(ownerDomain) == demoDomain {
				return errors.New(translationOrDefault(translations, "billing_status_demo_owner_blocked", "The owner site cannot be used as the public demo site."))
			}
		}
		return (demo.Store{DB: database}).SaveSettings(r.Context(), demoDomain, demoSourceURL, demoCopyWholeSite, demoEnabled)
	})
	if err != nil {
		return err.Error()
	}
	settings := demo.Settings{Domain: demoDomain, SourceURL: demoSourceURL, CopyWholeSite: demoCopyWholeSite, Enabled: demoEnabled}
	if !demoEnabled {
		a.updateRuntimeDemoSiteState(r.Context(), demoSiteRuntimeState{Settings: settings, Status: "disabled"})
		for _, disabledDemoDomain := range demo.UniqueDomains(previousDemoSettings.Domain, demoDomain) {
			if err := a.deleteDemoManagedSiteWithoutBackup(r.Context(), disabledDemoDomain); err != nil {
				return err.Error()
			}
			_ = a.withServerControlDatabaseWrite(r.Context(), "disable-demo-sessions", func(database *sql.DB) error {
				return (demo.Store{DB: database}).RemoveSessionsForDomain(r.Context(), disabledDemoDomain)
			})
			_ = a.removeInsideStorage(a.demoSiteSnapshotPath(disabledDemoDomain))
		}
		return translationOrDefault(translations, "billing_status_settings_saved", "Billing settings saved.")
	}
	if demoEnabled {
		a.updateRuntimeDemoSiteState(r.Context(), a.demoSiteRefreshingState(r.Context(), settings))
		refreshDemoSite := r.FormValue("refresh_demo_site") == "1"
		adminEmail, _, readyErr := a.ensureDemoSiteReady(r.Context(), settings, refreshDemoSite, "")
		if readyErr == nil && !a.demoSiteSnapshotAvailable(demoDomain) {
			readyErr = a.createDemoSiteSnapshot(r.Context(), demoDomain)
		}
		if readyErr != nil {
			a.updateRuntimeDemoSiteState(r.Context(), a.demoSiteRefreshFailureState(r.Context(), settings, readyErr))
			return readyErr.Error()
		}
		if strings.TrimSpace(adminEmail) == "" {
			readyErr = errors.New("demo administrator is unavailable")
			a.updateRuntimeDemoSiteState(r.Context(), a.demoSiteRefreshFailureState(r.Context(), settings, readyErr))
			return readyErr.Error()
		}
		a.updateRuntimeDemoSiteState(r.Context(), demoSiteRuntimeState{Settings: settings, AdminEmail: adminEmail, Status: "ready"})
	}
	return translationOrDefault(translations, "billing_status_settings_saved", "Billing settings saved.")
}

func (a *App) createManagedSiteFromForm(r *http.Request) string {
	translations := translationsForRequest(r)
	domain := normalizeQuotaDomainName(r.FormValue("domain"))
	email := strings.TrimSpace(r.FormValue("email"))
	password := strings.TrimSpace(r.FormValue("password"))
	quotaBytes, quotaRequested, err := parseSiteQuotaLimitBytes(r.FormValue("quota"))
	if err != nil {
		return err.Error()
	}
	if !quotaRequested {
		quotaBytes = defaultDomainStorageLimitBytes
	}
	if domain == "" {
		return translationOrDefault(translations, "billing_status_site_domain_required", "Site domain is required.")
	}
	if email == "" || password == "" {
		return translationOrDefault(translations, "billing_status_admin_required", "Administrator email and password are required.")
	}
	if _, err := stdmail.ParseAddress(email); err != nil {
		return translationOrDefault(translations, "billing_status_admin_email_invalid", "Administrator email is invalid.")
	}
	if err := a.createManagedSite(r.Context(), domain, email, password, quotaBytes); err != nil {
		return err.Error()
	}
	return fmt.Sprintf(translationOrDefault(translations, "billing_status_site_created", "Site %s was created."), domain)
}

func (a *App) createManagedSite(ctx context.Context, domain, email, password string, quotaBytes int64) error {
	siteDatabasePath := filepath.Join(siteDatabaseRootPath(a.serverControlDBPath()), domainStorageName(domain)+".db")
	realSiteDatabasePath, pathErr := a.writablePathInsideStorage(siteDatabasePath)
	if pathErr != nil {
		return pathErr
	}
	// #nosec G703 -- SQLite requires a native path after the storage jail has validated it.
	if _, statErr := os.Stat(realSiteDatabasePath); statErr == nil {
		return fmt.Errorf("site database for %s already exists", domain)
	} else if !errors.Is(statErr, os.ErrNotExist) {
		return statErr
	}
	if err := ensureParentDir(realSiteDatabasePath); err != nil {
		return err
	}
	rawDatabase, err := sql.Open("sqlite", "file:"+realSiteDatabasePath)
	if err != nil {
		return err
	}
	adminInserted := false
	defer func() {
		_ = rawDatabase.Close()
		if !adminInserted {
			// #nosec G703 -- SQLite requires a native path after the storage jail has validated it.
			_ = os.Remove(realSiteDatabasePath)
		}
	}()
	siteApplication := &App{db: rawDatabase, storagePath: a.storagePath, storageRealRoot: a.storageRealRoot, dbPath: a.serverControlDBPath(), debug: a.debug}
	siteContext := contextWithDomain(ctx, domain)
	if err := siteApplication.migrate(siteContext); err != nil {
		return err
	}
	if siteApplication.hasAdmin(siteContext, domain) {
		return fmt.Errorf("site %s already has an administrator", domain)
	}
	if _, err := rawDatabase.ExecContext(siteContext, `INSERT INTO users(domain,email,password,is_admin) VALUES(?,?,?,1)`, domain, email, password); err != nil {
		return err
	}
	adminInserted = true
	siteApplication.ensureDomainStorageUsageRow(siteContext, domain)
	_, err = rawDatabase.ExecContext(siteContext, `UPDATE domain_storage_usage SET limit_bytes=?, updated_at=? WHERE domain=?`, quotaBytes, time.Now().UTC().Format(time.RFC3339), domain)
	if err == nil {
		a.logHostingSupportEvent(ctx, "site_created", "success", email, domain, "managed site created")
		a.reportHostingSnapshotAsync(ctx)
	}
	return err
}

func (a *App) approveSiteRegistrationRequestFromForm(r *http.Request) string {
	translations := translationsForRequest(r)
	requestID, _ := strconv.Atoi(strings.TrimSpace(r.FormValue("request_id")))
	ownerMessage := strings.TrimSpace(r.FormValue("owner_message"))
	if requestID <= 0 {
		return translationOrDefault(translations, "billing_status_request_not_selected", "Request is not selected.")
	}
	var siteRequest hostingandsupport.SiteRequest
	var plan hostingandsupport.Plan
	err := a.withServerControlDatabaseRead(r.Context(), "approve-site-request-read", func(database *sql.DB) error {
		store := hostingandsupport.Store{DB: database}
		var found bool
		siteRequest, found = store.SiteRequestByID(r.Context(), requestID)
		if !found {
			return errors.New(translationOrDefault(translations, "billing_status_request_not_found", "Request was not found."))
		}
		if siteRequest.Status != "pending" {
			return errors.New(translationOrDefault(translations, "billing_status_request_already_processed", "This request has already been processed."))
		}
		plan, found = store.PlanByID(r.Context(), siteRequest.PlanID)
		if !found {
			return errors.New(translationOrDefault(translations, "billing_status_request_plan_not_found", "Request plan was not found."))
		}
		return nil
	})
	if err != nil {
		return err.Error()
	}
	temporaryPassword := randomAccessToken()
	if err := a.createManagedSite(r.Context(), siteRequest.Domain, siteRequest.Email, temporaryPassword, plan.QuotaBytes); err != nil {
		return err.Error()
	}
	serviceStatus := "paid"
	if planIsFree(plan) {
		serviceStatus = "free"
	}
	if err := a.withServerControlDatabaseWrite(r.Context(), "approve-site-request-finish", func(database *sql.DB) error {
		store := hostingandsupport.Store{DB: database}
		currentRequest, found := store.SiteRequestByID(r.Context(), requestID)
		if !found || currentRequest.Status != "pending" {
			return errors.New(translationOrDefault(translations, "billing_status_request_already_processed", "This request has already been processed."))
		}
		if assignErr := store.AssignSite(r.Context(), siteRequest.Domain, plan.ID, serviceStatus); assignErr != nil {
			return assignErr
		}
		return store.UpdateSiteRequestStatus(r.Context(), requestID, "approved", ownerMessage)
	}); err != nil {
		return err.Error()
	}
	a.logHostingSupportEvent(r.Context(), "support_request", "approved", siteRequest.Email, siteRequest.Domain, "site registration request approved")
	a.reportHostingSnapshotAsync(r.Context())
	if err := a.enqueueSiteRegistrationDecisionEmail(r.Context(), r, siteRequest, plan, "approved", ownerMessage, temporaryPassword); err != nil {
		return fmt.Sprintf(translationOrDefault(translations, "billing_status_site_approved_email_failed", "Site %s was activated, but the customer email was not queued: %s"), siteRequest.Domain, err.Error())
	}
	return fmt.Sprintf(translationOrDefault(translations, "billing_status_site_approved", "Site %s was activated and the customer email was sent."), siteRequest.Domain)
}

func (a *App) rejectSiteRegistrationRequestFromForm(r *http.Request) string {
	translations := translationsForRequest(r)
	requestID, _ := strconv.Atoi(strings.TrimSpace(r.FormValue("request_id")))
	ownerMessage := strings.TrimSpace(r.FormValue("owner_message"))
	if requestID <= 0 {
		return translationOrDefault(translations, "billing_status_request_not_selected", "Request is not selected.")
	}
	var siteRequest hostingandsupport.SiteRequest
	var plan hostingandsupport.Plan
	err := a.withServerControlDatabaseWrite(r.Context(), "reject-site-request", func(database *sql.DB) error {
		store := hostingandsupport.Store{DB: database}
		var found bool
		siteRequest, found = store.SiteRequestByID(r.Context(), requestID)
		if !found {
			return errors.New(translationOrDefault(translations, "billing_status_request_not_found", "Request was not found."))
		}
		if siteRequest.Status != "pending" {
			return errors.New(translationOrDefault(translations, "billing_status_request_already_processed", "This request has already been processed."))
		}
		plan, _ = store.PlanByID(r.Context(), siteRequest.PlanID)
		return store.UpdateSiteRequestStatus(r.Context(), requestID, "rejected", ownerMessage)
	})
	if err != nil {
		return err.Error()
	}
	a.logHostingSupportEvent(r.Context(), "support_request", "rejected", siteRequest.Email, siteRequest.Domain, "site registration request rejected")
	if err := a.enqueueSiteRegistrationDecisionEmail(r.Context(), r, siteRequest, plan, "rejected", ownerMessage, ""); err != nil {
		return fmt.Sprintf(translationOrDefault(translations, "billing_status_request_rejected_email_failed", "Request was rejected, but the customer email was not queued: %s"), err.Error())
	}
	return fmt.Sprintf(translationOrDefault(translations, "billing_status_request_rejected", "Request %s was rejected and the customer email was sent."), siteRequest.Domain)
}

func planIsFree(plan hostingandsupport.Plan) bool {
	price := strings.TrimSpace(plan.Price)
	return price == "" || price == "0" || price == "0.00"
}

func (a *App) enqueueSiteRegistrationRequestOwnerEmails(ctx context.Context, r *http.Request, domain, name, email, phone string, planID int) {
	var ownerEmails []string
	var plan hostingandsupport.Plan
	if err := a.withServerControlDatabaseRead(ctx, "site-registration-owner-email", func(database *sql.DB) error {
		store := hostingandsupport.Store{DB: database}
		ownerEmails = store.OwnerEmails(ctx)
		plan, _ = store.PlanByID(ctx, planID)
		return nil
	}); err != nil {
		return
	}
	if len(ownerEmails) == 0 {
		return
	}
	subject := "Новая заявка на сайт " + domain
	body := strings.Join([]string{
		"Поступила новая заявка на подключение сайта.",
		"",
		"Домен: " + domain,
		"Имя: " + name,
		"Email: " + email,
		"Телефон: " + phone,
		"Тариф: " + hostingAndSupportPlanEmailLabel(plan),
		"",
		"Откройте биллинг, чтобы активировать или отклонить заявку:",
		absoluteURLForPath(r, "/?expenses"),
	}, "\n")
	fromAddress := a.emailFromAddress(a.siteDomain(r.Context(), r))
	for _, ownerEmail := range ownerEmails {
		if err := a.enqueueEmail(ctx, mailout.Message{From: fromAddress, To: ownerEmail, Subject: subject, Body: body}); err != nil {
			log.Printf("site request owner email enqueue failed domain=%s to=%s error=%v", domain, ownerEmail, err)
		}
	}
}

func (a *App) enqueueSiteRegistrationDecisionEmail(ctx context.Context, r *http.Request, siteRequest hostingandsupport.SiteRequest, plan hostingandsupport.Plan, decision, ownerMessage, temporaryPassword string) error {
	subject := "Заявка на сайт " + siteRequest.Domain
	lines := []string{}
	if decision == "approved" {
		subject = "Сайт " + siteRequest.Domain + " активирован"
		lines = append(lines,
			"Ваша заявка на сайт "+siteRequest.Domain+" одобрена.",
			"",
			"Тариф: "+hostingAndSupportPlanEmailLabel(plan),
			"Адрес сайта: "+requestScheme(r)+"://"+siteRequest.Domain+"/",
			"Вход: "+requestScheme(r)+"://"+siteRequest.Domain+"/?login",
			"Email администратора: "+siteRequest.Email,
			"Временный пароль: "+temporaryPassword,
		)
	} else {
		subject = "Заявка на сайт " + siteRequest.Domain + " отклонена"
		lines = append(lines, "Ваша заявка на сайт "+siteRequest.Domain+" отклонена.")
	}
	if strings.TrimSpace(ownerMessage) != "" {
		lines = append(lines, "", "Сообщение владельца сервера:", ownerMessage)
	}
	return a.enqueueEmail(ctx, mailout.Message{
		From:    a.emailFromAddress(siteRequest.Domain),
		To:      siteRequest.Email,
		Subject: subject,
		Body:    strings.Join(lines, "\n"),
	})
}

func hostingAndSupportPlanEmailLabel(plan hostingandsupport.Plan) string {
	if plan.ID == 0 {
		return "не выбран"
	}
	return strings.TrimSpace(plan.Name + " · " + plan.QuotaLabel + " · " + plan.Price + " " + plan.Currency + "/" + plan.BillingPeriod)
}

func (a *App) updateManagedSiteFromForm(r *http.Request) string {
	translations := translationsForRequest(r)
	domain := normalizeQuotaDomainName(r.FormValue("domain"))
	if domain == "" {
		return translationOrDefault(translations, "billing_status_site_domain_required", "Site domain is required.")
	}
	planID, _ := strconv.Atoi(strings.TrimSpace(r.FormValue("plan_id")))
	serviceStatus := strings.TrimSpace(r.FormValue("service_status"))
	quotaBytes, quotaRequested, err := parseSiteQuotaLimitBytes(r.FormValue("quota"))
	if err != nil {
		return err.Error()
	}
	if !quotaRequested && planID > 0 {
		var plan hostingandsupport.Plan
		found := false
		_ = a.withServerControlDatabaseRead(r.Context(), "update-site-plan", func(database *sql.DB) error {
			plan, found = (hostingandsupport.Store{DB: database}).PlanByID(r.Context(), planID)
			return nil
		})
		if found {
			quotaBytes = plan.QuotaBytes
			quotaRequested = true
		}
	}
	if quotaRequested {
		if _, err := a.updateSiteQuotaLimit(r.Context(), domain, quotaBytes); err != nil {
			return err.Error()
		}
	}
	if err := a.withServerControlDatabaseWrite(r.Context(), "update-site-assignment", func(database *sql.DB) error {
		return (hostingandsupport.Store{DB: database}).AssignSite(r.Context(), domain, planID, serviceStatus)
	}); err != nil {
		return err.Error()
	}
	a.logHostingSupportEvent(r.Context(), "plan_changed", "saved", "", domain, "site plan or quota saved")
	a.reportHostingSnapshotAsync(r.Context())
	return fmt.Sprintf(translationOrDefault(translations, "billing_status_site_settings_saved", "Site %s settings were saved."), domain)
}

func (a *App) updateManagedSiteQuotaFromForm(r *http.Request) string {
	translations := translationsForRequest(r)
	domain := normalizeQuotaDomainName(r.FormValue("domain"))
	if domain == "" {
		return translationOrDefault(translations, "billing_status_site_domain_required", "Site domain is required.")
	}
	quotaBytes, quotaRequested, err := parseSiteQuotaLimitBytes(r.FormValue("quota"))
	if err != nil {
		return err.Error()
	}
	if !quotaRequested {
		return translationOrDefault(translations, "billing_status_quota_required", "Quota is required.")
	}
	updatedQuota, err := a.updateSiteQuotaLimit(r.Context(), domain, quotaBytes)
	if err != nil {
		return err.Error()
	}
	a.applyPreparedHostingAndSupportQuotaChange(updatedQuota)
	a.logHostingSupportEvent(r.Context(), "quota_changed", "saved", "", domain, "site quota saved")
	a.reportHostingSnapshotAsync(r.Context())
	return fmt.Sprintf(translationOrDefault(translations, "billing_status_site_settings_saved", "Site %s settings were saved."), domain)
}

func (a *App) deleteManagedSiteFromForm(r *http.Request) string {
	translations := translationsForRequest(r)
	domain := normalizeQuotaDomainName(r.FormValue("domain"))
	confirmDomain := normalizeQuotaDomainName(r.FormValue("confirm_domain"))
	retentionDays, retentionErr := hostingandsupport.ParseDeletionBackupRetentionDays(r.FormValue("backup_retention_days"))
	if retentionErr != nil {
		return retentionErr.Error()
	}
	if domain == "" || confirmDomain != domain {
		return translationOrDefault(translations, "billing_delete_confirm_mismatch", "Type the site domain to confirm deletion.")
	}
	if domain == a.siteDomain(r.Context(), r) {
		return translationOrDefault(translations, "billing_delete_current_site_blocked", "The current billing owner site cannot be deleted from Billing.")
	}
	backup, err := a.deleteManagedSiteWithBackup(r.Context(), r, domain, retentionDays)
	if err != nil {
		return err.Error()
	}
	return fmt.Sprintf(translationOrDefault(translations, "billing_status_site_deleted_with_backup", "Site %s was deleted. Backup %s was created and kept until %s."), domain, backup.FileName, backup.ExpiresAt)
}

func (a *App) deleteManagedSite(ctx context.Context, domain string) error {
	_, err := a.deleteManagedSiteWithBackup(ctx, nil, domain, hostingandsupport.DefaultDeletionBackupRetentionDays)
	return err
}

func (a *App) startDemoSiteCleanupWorker(ctx context.Context) {
	go func() {
		runCleanup := func(now time.Time) {
			a.cleanupExpiredDemoSites(ctx, now)
			a.cleanupExpiredPublicTrialSites(ctx, now)
		}
		runCleanup(time.Now())
		ticker := time.NewTicker(time.Minute)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case now := <-ticker.C:
				runCleanup(now)
			}
		}
	}()
}

func (a *App) cleanupExpiredDemoSites(ctx context.Context, now time.Time) {
	sessionsByDomain := make(map[string][]demo.Session)
	if err := a.withServerControlDatabaseRead(ctx, "demo-cleanup-scan", func(database *sql.DB) error {
		for _, session := range (demo.Store{DB: database}).Sessions(ctx) {
			domain := normalizeDomainName(session.Domain)
			if domain == "" {
				continue
			}
			sessionsByDomain[domain] = append(sessionsByDomain[domain], session)
		}
		return nil
	}); err != nil {
		return
	}
	for domain, sessions := range sessionsByDomain {
		if !demo.SessionsReadyForReset(sessions, now) {
			continue
		}
		if state, found := a.runtimeDemoSiteState(ctx); found && normalizeDomainName(state.Settings.Domain) == normalizeDomainName(domain) {
			a.updateRuntimeDemoSiteState(ctx, a.demoSiteRefreshingState(ctx, state.Settings))
		}
		if err := a.restoreDemoSiteFromSnapshot(ctx, domain); err != nil {
			if state, found := a.runtimeDemoSiteState(ctx); found && normalizeDomainName(state.Settings.Domain) == normalizeDomainName(domain) {
				a.updateRuntimeDemoSiteState(ctx, a.demoSiteRefreshFailureState(ctx, state.Settings, err))
			}
			log.Printf("demo site restore failed domain=%s error=%v", domain, err)
			continue
		}
		adminEmail, hasAdmin := a.firstAdminEmailForDomain(ctx, domain)
		if hasAdmin {
			state, found := a.runtimeDemoSiteState(ctx)
			if found && normalizeDomainName(state.Settings.Domain) == normalizeDomainName(domain) {
				state.AdminEmail = adminEmail
				state.Status = "ready"
				state.Error = ""
				state.Refreshing = false
				a.updateRuntimeDemoSiteState(ctx, state)
			}
		}
	}
}

func (a *App) deleteDemoManagedSiteWithoutBackup(ctx context.Context, domain string) error {
	domain = normalizeQuotaDomainName(domain)
	if domain == "" {
		return fmt.Errorf("demo domain is required")
	}
	var row siteQuotaRow
	err := a.withServerControlDatabaseRead(ctx, "demo-delete-owner-check", func(database *sql.DB) error {
		var ownerCount int
		_ = database.QueryRowContext(ctx, `SELECT COUNT(1) FROM server_managers WHERE domain=? AND role='owner'`, domain).Scan(&ownerCount)
		if ownerCount > 0 {
			return fmt.Errorf("server owner site %s cannot be deleted as a demo site", domain)
		}
		return nil
	})
	if err != nil {
		return err
	}
	row, found, err := a.managedSiteQuotaRow(ctx, domain)
	if err != nil {
		return err
	}
	if !found {
		return nil
	}
	if sameSiteQuotaPath(row.DatabasePath, a.serverControlDBPath()) {
		return fmt.Errorf("demo site %s is stored in the server control database and cannot be deleted as a separate site", domain)
	}
	if err := a.deleteManagedSiteFiles(ctx, row); err != nil {
		return err
	}
	return a.withServerControlDatabaseWrite(ctx, "demo-delete-finish", func(database *sql.DB) error {
		(hostingandsupport.Store{DB: database}).RemoveSiteAssignment(ctx, domain)
		_, deleteErr := database.ExecContext(ctx, `DELETE FROM server_managers WHERE domain=? AND role<>'owner'`, domain)
		return deleteErr
	})
}

func (a *App) deleteManagedSiteWithBackup(ctx context.Context, r *http.Request, domain string, retentionDays int) (managedSiteDeletionBackupView, error) {
	var ownerCount int
	err := a.withServerControlDatabaseRead(ctx, "delete-site-owner-check", func(database *sql.DB) error {
		return database.QueryRowContext(ctx, `SELECT COUNT(1) FROM server_managers WHERE domain=? AND role='owner'`, domain).Scan(&ownerCount)
	})
	if err != nil {
		return managedSiteDeletionBackupView{}, err
	}
	if ownerCount > 0 {
		return managedSiteDeletionBackupView{}, fmt.Errorf("server owner site %s cannot be deleted", domain)
	}
	row, found, err := a.managedSiteQuotaRow(ctx, domain)
	if err != nil {
		return managedSiteDeletionBackupView{}, err
	}
	if !found {
		return managedSiteDeletionBackupView{}, fmt.Errorf("site %s was not found", domain)
	}
	if sameSiteQuotaPath(row.DatabasePath, a.serverControlDBPath()) {
		return managedSiteDeletionBackupView{}, fmt.Errorf("site %s is stored in the server control database and cannot be safely deleted as a separate site", domain)
	}
	ownerContacts := managedSiteOwnerContacts(ctx, nil, row.DatabasePath, domain)
	_ = a.withServerControlDatabaseRead(ctx, "delete-site-owner-contacts", func(database *sql.DB) error {
		ownerContacts = append(ownerContacts, managedSiteOwnerContacts(ctx, database, "", domain)...)
		ownerContacts = uniqueStrings(ownerContacts)
		return nil
	})
	if retentionDays <= 0 {
		retentionDays = hostingandsupport.DefaultDeletionBackupRetentionDays
	}
	languageCode := "ru"
	if r != nil {
		languageCode = preferredLanguageCode(r.Header.Get("Accept-Language"))
	}
	backup, err := a.createManagedSiteDeletionBackup(ctx, r, row, ownerContacts, retentionDays, languageCode)
	if err != nil {
		return managedSiteDeletionBackupView{}, err
	}
	if err := a.withServerControlDatabaseWrite(ctx, "delete-site-control-rows", func(database *sql.DB) error {
		return a.deleteManagedSiteControlRows(ctx, database, row)
	}); err != nil {
		return managedSiteDeletionBackupView{}, err
	}
	if err := a.deleteManagedSiteFiles(ctx, row); err != nil {
		return managedSiteDeletionBackupView{}, err
	}
	a.logHostingSupportEvent(ctx, "site_deleted", "success", strings.Join(ownerContacts, ", "), domain, "managed site deleted with backup")
	a.reportHostingSnapshotAsync(ctx)
	a.notifyManagedSiteDeletionBackupCreated(ctx, r, backup, ownerContacts, languageCode)
	return backup, nil
}

func (a *App) updateManagedSiteDeletionBackupRetentionFromForm(r *http.Request) string {
	translations := translationsForRequest(r)
	backupID, _ := strconv.Atoi(strings.TrimSpace(r.FormValue("backup_id")))
	retentionDays, retentionErr := hostingandsupport.ParseDeletionBackupRetentionDays(r.FormValue("backup_retention_days"))
	if retentionErr != nil {
		return retentionErr.Error()
	}
	if backupID <= 0 {
		return translationOrDefault(translations, "billing_status_backup_not_selected", "Backup is not selected.")
	}
	var createdAtText string
	var metadataText string
	err := a.withServerControlDatabaseWrite(r.Context(), "update-backup-retention", func(database *sql.DB) error {
		if queryErr := database.QueryRowContext(r.Context(), `SELECT created_at,metadata_json FROM site_deletion_backups WHERE id=?`, backupID).Scan(&createdAtText, &metadataText); queryErr != nil {
			return queryErr
		}
		createdAt, parseErr := time.Parse(time.RFC3339, createdAtText)
		if parseErr != nil {
			createdAt = time.Now().UTC()
		}
		expiresAt := createdAt.AddDate(0, 0, retentionDays)
		metadataText = hostingandsupport.RewriteDeletionBackupMetadataRetention(metadataText, retentionDays, expiresAt)
		_, updateErr := database.ExecContext(r.Context(), `UPDATE site_deletion_backups SET retention_days=?,expires_at=?,metadata_json=? WHERE id=?`,
			retentionDays, expiresAt.Format(time.RFC3339), metadataText, backupID)
		return updateErr
	})
	if err != nil {
		return err.Error()
	}
	return translationOrDefault(translations, "billing_status_backup_retention_saved", "Backup retention was saved.")
}

func (a *App) deleteManagedSiteControlRows(ctx context.Context, controlDatabase *sql.DB, row siteQuotaRow) error {
	domain := normalizeQuotaDomainName(row.Domain)
	if domain == "" {
		return fmt.Errorf("site domain is required")
	}
	(hostingandsupport.Store{DB: controlDatabase}).RemoveSiteAssignment(ctx, domain)
	_, _ = controlDatabase.ExecContext(ctx, `DELETE FROM server_managers WHERE domain=? AND role<>'owner'`, domain)
	return nil
}

func (a *App) deleteManagedSiteFiles(ctx context.Context, row siteQuotaRow) error {
	domain := normalizeQuotaDomainName(row.Domain)
	if domain == "" {
		return fmt.Errorf("site domain is required")
	}
	a.closeManagedSiteDatabase(ctx, domain)
	if strings.TrimSpace(row.DatabasePath) != "" && !sameSiteQuotaPath(row.DatabasePath, a.serverControlDBPath()) {
		realDatabasePath, pathErr := a.existingPathInsideStorage(row.DatabasePath)
		if pathErr != nil && !errors.Is(pathErr, os.ErrNotExist) {
			return pathErr
		}
		if pathErr == nil {
			if err := os.Remove(realDatabasePath); err != nil && !errors.Is(err, os.ErrNotExist) {
				return err
			}
		}
	}
	for _, directoryPath := range []string{
		a.domainFilesDirForDomain(domain),
		a.domainStaticDir(domain),
		a.domainChrootRootDir(domain),
		a.domainLogDir(domain),
	} {
		if err := a.removeAllInsideStorage(directoryPath); err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
	}
	packPath := filepath.Join(a.packsDir(), domainStorageName(domain)+".zip")
	realPackPath, pathErr := a.existingPathInsideStorage(packPath)
	if pathErr == nil {
		if err := os.Remove(realPackPath); err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
	} else if !errors.Is(pathErr, os.ErrNotExist) {
		return pathErr
	}
	return nil
}

func (a *App) closeManagedSiteDatabase(ctx context.Context, domain string) {
	if a.siteDatabaseRouter == nil {
		return
	}
	if err := a.siteDatabaseRouter.ForgetDomain(ctx, domain); err != nil {
		log.Printf("managed site database close failed domain=%s error=%v", domain, err)
	}
}

func (a *App) managedSiteQuotaRow(ctx context.Context, domain string) (siteQuotaRow, bool, error) {
	rows, err := a.listSiteQuotaRows(ctx)
	if err != nil {
		return siteQuotaRow{}, false, err
	}
	for _, row := range rows {
		if normalizeQuotaDomainName(row.Domain) == domain {
			return row, true, nil
		}
	}
	return siteQuotaRow{}, false, nil
}

func (a *App) managedSiteDeletionSizeBytes(row siteQuotaRow) int64 {
	totalBytes := a.fileSizeInsideStorage(row.DatabasePath)
	for _, directoryPath := range []string{
		a.domainFilesDirForDomain(row.Domain),
		a.domainStaticDir(row.Domain),
		a.domainChrootRootDir(row.Domain),
		a.domainLogDir(row.Domain),
	} {
		totalBytes += a.directorySizeInsideStorage(directoryPath)
	}
	totalBytes += a.fileSizeInsideStorage(filepath.Join(a.packsDir(), domainStorageName(row.Domain)+".zip"))
	return totalBytes
}

func (a *App) managedSiteBillingDiskBytes(row siteQuotaRow, deletionBackupSizesByDomain map[string]int64) int64 {
	totalBytes := a.managedSiteDeletionSizeBytes(row)
	totalBytes += deletionBackupSizesByDomain[normalizeQuotaDomainName(row.Domain)]
	return totalBytes
}

func (a *App) managedSiteDeletionBackupPathsByDomain(ctx context.Context, controlDatabase *sql.DB) map[string][]string {
	pathsByDomain := make(map[string][]string)
	if controlDatabase == nil {
		return pathsByDomain
	}
	rows, err := controlDatabase.QueryContext(ctx, `SELECT domain,archive_path FROM site_deletion_backups`)
	if err != nil {
		return pathsByDomain
	}
	defer rows.Close()
	for rows.Next() {
		var domain string
		var archivePath string
		if scanErr := rows.Scan(&domain, &archivePath); scanErr != nil {
			continue
		}
		normalizedDomain := normalizeQuotaDomainName(domain)
		if normalizedDomain == "" {
			continue
		}
		pathsByDomain[normalizedDomain] = append(pathsByDomain[normalizedDomain], archivePath)
	}
	return pathsByDomain
}

func (a *App) managedSiteDeletionBackupSizesByDomain(pathsByDomain map[string][]string) map[string]int64 {
	sizesByDomain := make(map[string]int64, len(pathsByDomain))
	for normalizedDomain, archivePaths := range pathsByDomain {
		for _, archivePath := range archivePaths {
			archiveSizeBytes := int64(0)
			if realArchivePath, pathErr := a.existingPathInsideStorageSubtree(a.backupRootDir(), archivePath); pathErr == nil {
				if fileSizeBytes := a.fileSizeInsideStorage(realArchivePath); fileSizeBytes > 0 {
					archiveSizeBytes = fileSizeBytes
				}
			}
			if archiveSizeBytes > 0 {
				sizesByDomain[normalizedDomain] += archiveSizeBytes
			}
		}
	}
	return sizesByDomain
}

func managedSiteOwnerContacts(ctx context.Context, controlDatabase *sql.DB, databasePath, domain string) []string {
	contactSet := make(map[string]struct{})
	for _, email := range siteAdminEmails(ctx, databasePath, domain) {
		if _, err := stdmail.ParseAddress(email); err == nil {
			contactSet[strings.TrimSpace(email)] = struct{}{}
		}
	}
	if controlDatabase != nil {
		rows, err := controlDatabase.QueryContext(ctx, `SELECT email FROM server_managers WHERE TRIM(COALESCE(email,''))<>'' ORDER BY email`)
		if err == nil {
			for rows.Next() {
				var email string
				if scanErr := rows.Scan(&email); scanErr == nil {
					if _, parseErr := stdmail.ParseAddress(email); parseErr == nil {
						contactSet[strings.TrimSpace(email)] = struct{}{}
					}
				}
			}
			_ = rows.Close()
		}
	}
	contacts := make([]string, 0, len(contactSet))
	for email := range contactSet {
		contacts = append(contacts, email)
	}
	sort.Strings(contacts)
	return contacts
}

func uniqueStrings(values []string) []string {
	seen := make(map[string]struct{}, len(values))
	result := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		key := strings.ToLower(value)
		if _, found := seen[key]; found {
			continue
		}
		seen[key] = struct{}{}
		result = append(result, value)
	}
	sort.Strings(result)
	return result
}

func (a *App) backupRootDir() string {
	storagePath := a.storagePath
	if strings.TrimSpace(storagePath) == "" {
		storagePath = defaultAppStoragePath()
	}
	return filepath.Join(storagePath, "backup")
}

func (a *App) backupArchivePathAllowed(archivePath string) bool {
	archivePath = strings.TrimSpace(archivePath)
	if archivePath == "" || strings.ToLower(filepath.Ext(archivePath)) != ".zip" {
		return false
	}
	_, err := a.writablePathInsideStorageSubtree(a.backupRootDir(), archivePath)
	return err == nil
}

func (a *App) createManagedSiteDeletionBackup(ctx context.Context, r *http.Request, row siteQuotaRow, ownerContacts []string, retentionDays int, languageCode string) (managedSiteDeletionBackupView, error) {
	domain := normalizeQuotaDomainName(row.Domain)
	if domain == "" {
		return managedSiteDeletionBackupView{}, fmt.Errorf("site domain is required")
	}
	if strings.TrimSpace(row.DatabasePath) == "" {
		return managedSiteDeletionBackupView{}, fmt.Errorf("site database path is required")
	}
	createdAt := time.Now().UTC()
	expiresAt := createdAt.AddDate(0, 0, retentionDays)
	token := randomAccessToken()
	if strings.TrimSpace(token) == "" {
		return managedSiteDeletionBackupView{}, fmt.Errorf("backup download token was not created")
	}
	backupDirectory := a.backupRootDir()
	if err := a.mkdirAllInsideStorage(backupDirectory, 0o755); err != nil {
		return managedSiteDeletionBackupView{}, err
	}
	fileName := domainStorageName(domain) + "-deleted-" + createdAt.Format("20060102-150405") + ".zip"
	archivePath := filepath.Join(backupDirectory, fileName)
	tempArchivePath := archivePath + ".tmp"
	realTempArchivePath, err := a.writablePathInsideStorageSubtree(backupDirectory, tempArchivePath)
	if err != nil {
		return managedSiteDeletionBackupView{}, err
	}
	realArchivePath, err := a.writablePathInsideStorageSubtree(backupDirectory, archivePath)
	if err != nil {
		return managedSiteDeletionBackupView{}, err
	}
	_ = os.Remove(realTempArchivePath)
	metadata := hostingandsupport.DeletionBackupMetadata{
		Version:           1,
		Domain:            domain,
		CreatedAt:         createdAt.Format(time.RFC3339),
		ExpiresAt:         expiresAt.Format(time.RFC3339),
		RetentionDays:     retentionDays,
		OwnerContacts:     ownerContacts,
		DeletedBytes:      a.managedSiteDeletionSizeBytes(row),
		DatabaseFile:      "database/" + filepath.Base(row.DatabasePath),
		StaticDirectory:   "static/" + domainStorageName(domain),
		OriginalDatabase:  row.DatabasePath,
		OriginalStaticDir: a.domainStaticDir(domain),
	}
	if err := a.writeManagedSiteDeletionBackupArchive(ctx, domain, row.DatabasePath, realTempArchivePath, metadata); err != nil {
		_ = os.Remove(realTempArchivePath)
		return managedSiteDeletionBackupView{}, err
	}
	if err := verifyManagedSiteDeletionBackupArchive(realTempArchivePath, metadata); err != nil {
		_ = os.Remove(realTempArchivePath)
		return managedSiteDeletionBackupView{}, err
	}
	if err := os.Rename(realTempArchivePath, realArchivePath); err != nil {
		_ = os.Remove(realTempArchivePath)
		return managedSiteDeletionBackupView{}, err
	}
	archiveInfo, err := os.Stat(realArchivePath)
	if err != nil || archiveInfo.Size() <= 0 {
		_ = os.Remove(realArchivePath)
		if err != nil {
			return managedSiteDeletionBackupView{}, err
		}
		return managedSiteDeletionBackupView{}, fmt.Errorf("backup archive is empty")
	}
	metadataJSON, err := json.Marshal(metadata)
	if err != nil {
		_ = os.Remove(realArchivePath)
		return managedSiteDeletionBackupView{}, err
	}
	err = a.withServerControlDatabaseWrite(ctx, "save-deletion-backup", func(database *sql.DB) error {
		_, insertErr := database.ExecContext(ctx, `INSERT INTO site_deletion_backups(domain,archive_path,file_name,size_bytes,token,token_created_at,created_at,expires_at,retention_days,owner_contacts,metadata_json,language_code,download_count) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,0)`,
			domain, realArchivePath, fileName, archiveInfo.Size(), token, createdAt.Format(time.RFC3339), createdAt.Format(time.RFC3339), expiresAt.Format(time.RFC3339), retentionDays, strings.Join(ownerContacts, ", "), string(metadataJSON), languageCode)
		return insertErr
	})
	if err != nil {
		_ = os.Remove(realArchivePath)
		return managedSiteDeletionBackupView{}, err
	}
	downloadURL := ""
	if r != nil {
		downloadURL = absoluteURLForPath(r, "/?hosting_and_support_backup_download&token="+url.QueryEscape(token))
	}
	return managedSiteDeletionBackupView{
		Domain:        domain,
		FileName:      fileName,
		SizeLabel:     formatFileSize(archiveInfo.Size()),
		CreatedAt:     createdAt.Format(time.RFC3339),
		ExpiresAt:     expiresAt.Format(time.RFC3339),
		RetentionDays: retentionDays,
		OwnerContacts: strings.Join(ownerContacts, ", "),
		TokenStatus:   localizedBackupTokenStatus(translationsForLanguageCode(languageCode), false, 0),
		DownloadURL:   downloadURL,
	}, nil
}

func (a *App) writeManagedSiteDeletionBackupArchive(ctx context.Context, domain, databasePath, archivePath string, metadata hostingandsupport.DeletionBackupMetadata) error {
	realDatabasePath, err := a.existingPathInsideStorage(databasePath)
	if err != nil {
		return err
	}
	realArchivePath, err := a.writablePathInsideStorageSubtree(a.backupRootDir(), archivePath)
	if err != nil {
		return err
	}
	siteDatabase, err := sql.Open("sqlite", "file:"+realDatabasePath)
	if err != nil {
		return err
	}
	defer siteDatabase.Close()
	siteApplication := &App{db: siteDatabase, storagePath: a.storagePath, storageRealRoot: a.storageRealRoot, dbPath: a.serverControlDBPath(), debug: a.debug}
	archiveFile, err := os.Create(realArchivePath)
	if err != nil {
		return err
	}
	closeArchive := true
	defer func() {
		if closeArchive {
			_ = archiveFile.Close()
		}
	}()
	zipWriter := zip.NewWriter(archiveFile)
	if err := siteApplication.writeDomainBackupEntriesToZip(ctx, domain, zipWriter); err != nil {
		_ = zipWriter.Close()
		return err
	}
	if _, err := zipWriter.Create(metadata.StaticDirectory + "/"); err != nil {
		_ = zipWriter.Close()
		return err
	}
	if err := addDirectoryToZip(zipWriter, a.domainStaticDir(domain), metadata.StaticDirectory, nil); err != nil {
		_ = zipWriter.Close()
		return err
	}
	if err := addFileToZip(zipWriter, realDatabasePath, metadata.DatabaseFile); err != nil {
		_ = zipWriter.Close()
		return err
	}
	metadataJSON, err := json.MarshalIndent(metadata, "", "  ")
	if err != nil {
		_ = zipWriter.Close()
		return err
	}
	metadataWriter, err := zipWriter.Create("metadata.json")
	if err != nil {
		_ = zipWriter.Close()
		return err
	}
	if _, err := metadataWriter.Write(metadataJSON); err != nil {
		_ = zipWriter.Close()
		return err
	}
	if err := zipWriter.Close(); err != nil {
		return err
	}
	if err := archiveFile.Close(); err != nil {
		return err
	}
	closeArchive = false
	return nil
}

func addFileToZip(zipWriter *zip.Writer, sourcePath, archivePath string) error {
	sourceFile, err := os.Open(sourcePath)
	if err != nil {
		return err
	}
	defer sourceFile.Close()
	sourceInfo, err := sourceFile.Stat()
	if err != nil {
		return err
	}
	header, err := zip.FileInfoHeader(sourceInfo)
	if err != nil {
		return err
	}
	header.Name = filepath.ToSlash(archivePath)
	header.Method = zip.Deflate
	archiveWriter, err := zipWriter.CreateHeader(header)
	if err != nil {
		return err
	}
	_, err = io.Copy(archiveWriter, sourceFile)
	return err
}

func verifyManagedSiteDeletionBackupArchive(archivePath string, metadata hostingandsupport.DeletionBackupMetadata) error {
	archiveReader, err := zip.OpenReader(archivePath)
	if err != nil {
		return err
	}
	defer archiveReader.Close()
	requiredEntries := map[string]bool{
		"backup.json":            false,
		"metadata.json":          false,
		metadata.DatabaseFile:    false,
		metadata.StaticDirectory: false,
	}
	for _, archiveFile := range archiveReader.File {
		entryName := strings.TrimSuffix(archiveFile.Name, "/")
		if _, required := requiredEntries[entryName]; required {
			requiredEntries[entryName] = true
		}
		if strings.HasPrefix(entryName, metadata.StaticDirectory+"/") {
			requiredEntries[metadata.StaticDirectory] = true
		}
	}
	for entryName, found := range requiredEntries {
		if !found {
			return fmt.Errorf("backup archive missing %s", entryName)
		}
	}
	return nil
}

func (a *App) managedSiteDeletionBackupViews(ctx context.Context, r *http.Request, controlDatabase *sql.DB) []managedSiteDeletionBackupView {
	rows, err := controlDatabase.QueryContext(ctx, `SELECT id,domain,archive_path,file_name,size_bytes,token,created_at,expires_at,COALESCE(retention_days,0),owner_contacts,downloaded_at,download_count FROM site_deletion_backups ORDER BY created_at DESC, id DESC`)
	if err != nil {
		return nil
	}
	defer rows.Close()
	translations := translationsForRequest(r)
	now := time.Now().UTC()
	views := make([]managedSiteDeletionBackupView, 0, 8)
	for rows.Next() {
		var view managedSiteDeletionBackupView
		var archivePath string
		var token string
		var sizeBytes int64
		var downloadedAt sql.NullString
		if scanErr := rows.Scan(&view.ID, &view.Domain, &archivePath, &view.FileName, &sizeBytes, &token, &view.CreatedAt, &view.ExpiresAt, &view.RetentionDays, &view.OwnerContacts, &downloadedAt, &view.DownloadCount); scanErr != nil {
			continue
		}
		view.DownloadedAt = downloadedAt.String
		expiresAt, _ := time.Parse(time.RFC3339, view.ExpiresAt)
		createdAt, _ := time.Parse(time.RFC3339, view.CreatedAt)
		if view.RetentionDays <= 0 && !createdAt.IsZero() && !expiresAt.IsZero() {
			view.RetentionDays = int(expiresAt.Sub(createdAt).Hours() / 24)
		}
		if view.RetentionDays <= 0 {
			view.RetentionDays = hostingandsupport.DefaultDeletionBackupRetentionDays
		}
		view.Expired = !expiresAt.IsZero() && !expiresAt.After(now)
		if realArchivePath, pathErr := a.existingPathInsideStorageSubtree(a.backupRootDir(), archivePath); pathErr != nil {
			view.ArchiveMissing = true
		} else if _, statErr := os.Stat(realArchivePath); statErr != nil {
			view.ArchiveMissing = true
		}
		view.SizeLabel = formatFileSize(sizeBytes)
		view.TokenStatus = localizedBackupTokenStatus(translations, view.Expired || view.ArchiveMissing, view.DownloadCount)
		if !view.Expired && !view.ArchiveMissing && strings.TrimSpace(token) != "" {
			view.DownloadURL = "/?hosting_and_support_backup_download&token=" + url.QueryEscape(token)
		}
		views = append(views, view)
	}
	return views
}

func localizedBackupTokenStatus(translations map[string]string, unavailable bool, downloadCount int) string {
	if unavailable {
		return translationOrDefault(translations, "billing_backup_token_expired", "expired")
	}
	if downloadCount > 0 {
		return translationOrDefault(translations, "billing_backup_token_downloaded", "downloaded")
	}
	return translationOrDefault(translations, "billing_backup_token_active", "active")
}

func (a *App) cleanupExpiredManagedSiteDeletionBackups(ctx context.Context, controlDatabase *sql.DB) {
	now := time.Now().UTC()
	rows, err := controlDatabase.QueryContext(ctx, `SELECT id,archive_path,expires_at FROM site_deletion_backups`)
	if err != nil {
		return
	}
	type expiredBackup struct {
		id          int
		archivePath string
	}
	expiredBackups := make([]expiredBackup, 0)
	for rows.Next() {
		var backup expiredBackup
		var expiresAtText string
		if scanErr := rows.Scan(&backup.id, &backup.archivePath, &expiresAtText); scanErr != nil {
			continue
		}
		expiresAt, parseErr := time.Parse(time.RFC3339, expiresAtText)
		if parseErr == nil && !expiresAt.After(now) {
			expiredBackups = append(expiredBackups, backup)
		}
	}
	_ = rows.Close()
	for _, backup := range expiredBackups {
		if realArchivePath, pathErr := a.existingPathInsideStorageSubtree(a.backupRootDir(), backup.archivePath); pathErr == nil {
			_ = os.Remove(realArchivePath)
		}
		_, _ = controlDatabase.ExecContext(ctx, `UPDATE site_deletion_backups SET token='' WHERE id=?`, backup.id)
	}
}

func (a *App) notifyManagedSiteDeletionBackupCreated(ctx context.Context, r *http.Request, backup managedSiteDeletionBackupView, ownerContacts []string, languageCode string) {
	if len(ownerContacts) == 0 {
		return
	}
	translations := translationsForLanguageCode(languageCode)
	downloadURL := backup.DownloadURL
	if downloadURL == "" && r != nil {
		downloadURL = absoluteURLForPath(r, backup.DownloadURL)
	}
	subject := fmt.Sprintf(translationOrDefault(translations, "billing_backup_created_email_subject", "Site backup created for %s"), backup.Domain)
	body := fmt.Sprintf(translationOrDefault(translations, "billing_backup_created_email_body", "A deletion backup for %s was created.\nArchive: %s\nSize: %s\nExpires: %s\nDownload: %s"), backup.Domain, backup.FileName, backup.SizeLabel, backup.ExpiresAt, downloadURL)
	a.enqueueManagedSiteDeletionBackupEmails(ctx, backup.Domain, ownerContacts, subject, body)
}

func (a *App) notifyManagedSiteDeletionBackupDownloaded(ctx context.Context, backup managedSiteDeletionBackupView, ownerContacts []string, languageCode string, remoteAddress string) {
	if len(ownerContacts) == 0 {
		return
	}
	translations := translationsForLanguageCode(languageCode)
	subject := fmt.Sprintf(translationOrDefault(translations, "billing_backup_downloaded_email_subject", "Site backup downloaded for %s"), backup.Domain)
	body := fmt.Sprintf(translationOrDefault(translations, "billing_backup_downloaded_email_body", "The deletion backup for %s was downloaded.\nArchive: %s\nTime: %s\nRemote: %s"), backup.Domain, backup.FileName, time.Now().UTC().Format(time.RFC3339), remoteAddress)
	a.enqueueManagedSiteDeletionBackupEmails(ctx, backup.Domain, ownerContacts, subject, body)
}

func (a *App) enqueueManagedSiteDeletionBackupEmails(ctx context.Context, domain string, ownerContacts []string, subject, body string) {
	for _, email := range ownerContacts {
		if _, err := stdmail.ParseAddress(email); err != nil {
			continue
		}
		err := a.enqueueEmail(ctx, mailout.Message{
			From:    a.emailFromAddress(domain),
			To:      strings.TrimSpace(email),
			Subject: subject,
			Body:    body,
		})
		if err != nil {
			log.Printf("deletion backup email enqueue failed domain=%s to=%s error=%v", domain, email, err)
		}
	}
}

func (a *App) downloadManagedSiteDeletionBackup(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	token := strings.TrimSpace(r.URL.Query().Get("token"))
	if !validOpaqueAccessToken(token) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	var backup managedSiteDeletionBackupView
	var archivePath string
	var ownerContactsText string
	var languageCodeValue sql.NullString
	var downloadedAt sql.NullString
	var sizeBytes int64
	err := a.withServerControlDatabaseRead(r.Context(), "download-backup-lookup", func(database *sql.DB) error {
		return database.QueryRowContext(r.Context(), `SELECT id,domain,archive_path,file_name,size_bytes,created_at,expires_at,owner_contacts,downloaded_at,download_count,language_code FROM site_deletion_backups WHERE token=?`, token).Scan(
			&backup.ID, &backup.Domain, &archivePath, &backup.FileName, &sizeBytes, &backup.CreatedAt, &backup.ExpiresAt, &ownerContactsText, &downloadedAt, &backup.DownloadCount, &languageCodeValue)
	})
	if err != nil {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	expiresAt, _ := time.Parse(time.RFC3339, backup.ExpiresAt)
	if !expiresAt.IsZero() && !expiresAt.After(time.Now().UTC()) {
		http.Error(w, "backup expired", http.StatusGone)
		return
	}
	realArchivePath, pathErr := a.existingPathInsideStorageSubtree(a.backupRootDir(), archivePath)
	if pathErr != nil {
		http.Error(w, "backup archive unavailable", http.StatusNotFound)
		return
	}
	archiveFile, err := os.Open(realArchivePath)
	if err != nil {
		http.Error(w, "backup archive missing", http.StatusNotFound)
		return
	}
	defer archiveFile.Close()
	archiveInfo, err := archiveFile.Stat()
	if err != nil || archiveInfo.Size() <= 0 {
		http.Error(w, "backup archive unavailable", http.StatusInternalServerError)
		return
	}
	backup.SizeLabel = formatFileSize(archiveInfo.Size())
	downloadFileName := safeFileName(backup.FileName)
	if downloadFileName == "" {
		downloadFileName = backupFileName(backup.Domain)
	}
	w.Header().Set("Content-Type", "application/zip")
	w.Header().Set("Content-Disposition", "attachment; filename=\""+downloadFileName+"\"")
	if _, err := io.Copy(w, archiveFile); err != nil {
		return
	}
	nowText := time.Now().UTC().Format(time.RFC3339)
	_ = a.withServerControlDatabaseWrite(context.Background(), "download-backup-record", func(database *sql.DB) error {
		_, updateErr := database.ExecContext(context.Background(), `UPDATE site_deletion_backups SET downloaded_at=?,download_count=COALESCE(download_count,0)+1 WHERE id=?`, nowText, backup.ID)
		return updateErr
	})
	ownerContacts := splitOwnerContacts(ownerContactsText)
	a.notifyManagedSiteDeletionBackupDownloaded(context.Background(), backup, ownerContacts, languageCodeValue.String, r.RemoteAddr)
}

func splitOwnerContacts(ownerContactsText string) []string {
	contacts := make([]string, 0, 4)
	for _, rawContact := range strings.Split(ownerContactsText, ",") {
		contact := strings.TrimSpace(rawContact)
		if contact != "" {
			contacts = append(contacts, contact)
		}
	}
	return contacts
}

func (a *App) saveServicePlanFromForm(r *http.Request) string {
	translations := translationsForRequest(r)
	name := strings.TrimSpace(r.FormValue("name"))
	if name == "" {
		return translationOrDefault(translations, "billing_status_plan_name_required", "Plan name is required.")
	}
	quotaBytes, quotaRequested, err := parseSiteQuotaLimitBytes(r.FormValue("quota"))
	if err != nil {
		return err.Error()
	}
	if !quotaRequested {
		return translationOrDefault(translations, "billing_status_plan_quota_required", "Plan quota is required.")
	}
	planID, _ := strconv.Atoi(strings.TrimSpace(r.FormValue("plan_id")))
	siteLimit, err := positiveIntegerFromForm(r, "site_limit", 1)
	if err != nil {
		return err.Error()
	}
	analyticsReportLimit, err := nonNegativeIntegerFromForm(r, "analytics_report_limit", 0)
	if err != nil {
		return err.Error()
	}
	price := strings.TrimSpace(r.FormValue("price"))
	currency := strings.TrimSpace(r.FormValue("currency"))
	if currency == "" {
		currency = "USD"
	}
	billingPeriod := strings.TrimSpace(r.FormValue("billing_period"))
	if billingPeriod == "" {
		billingPeriod = "monthly"
	}
	isDefault := r.FormValue("is_default") == "1"
	if err := a.withServerControlDatabaseWrite(r.Context(), "save-service-plan", func(database *sql.DB) error {
		return (hostingandsupport.Store{DB: database}).SavePlan(r.Context(), planID, name, quotaBytes, siteLimit, analyticsReportLimit, price, currency, billingPeriod, isDefault)
	}); err != nil {
		return err.Error()
	}
	eventKind := "plan_changed"
	if planID <= 0 {
		eventKind = "plan_created"
	}
	a.logHostingSupportEvent(r.Context(), eventKind, "saved", "", "", name)
	a.reportHostingSnapshotAsync(r.Context())
	return translationOrDefault(translations, "billing_status_plan_saved", "Plan saved.")
}

func positiveIntegerFromForm(r *http.Request, fieldName string, fallback int) (int, error) {
	rawText := strings.TrimSpace(r.FormValue(fieldName))
	if rawText == "" {
		return fallback, nil
	}
	parsedValue, err := strconv.Atoi(rawText)
	if err != nil || parsedValue <= 0 {
		return 0, fmt.Errorf("Значение %s должно быть положительным числом.", fieldName)
	}
	return parsedValue, nil
}

func nonNegativeIntegerFromForm(r *http.Request, fieldName string, fallback int) (int, error) {
	rawText := strings.TrimSpace(r.FormValue(fieldName))
	if rawText == "" {
		return fallback, nil
	}
	parsedValue, err := strconv.Atoi(rawText)
	if err != nil || parsedValue < 0 {
		return 0, fmt.Errorf("Значение %s не может быть отрицательным.", fieldName)
	}
	return parsedValue, nil
}

func (a *App) deleteServicePlanFromForm(r *http.Request) string {
	translations := translationsForRequest(r)
	planID, _ := strconv.Atoi(strings.TrimSpace(r.FormValue("plan_id")))
	if planID <= 0 {
		return translationOrDefault(translations, "billing_status_plan_not_selected", "Plan is not selected.")
	}
	if err := a.withServerControlDatabaseWrite(r.Context(), "delete-service-plan", func(database *sql.DB) error {
		return (hostingandsupport.Store{DB: database}).DeletePlan(r.Context(), planID)
	}); err != nil {
		return err.Error()
	}
	a.logHostingSupportEvent(r.Context(), "plan_deleted", "deleted", "", "", strconv.Itoa(planID))
	a.reportHostingSnapshotAsync(r.Context())
	return translationOrDefault(translations, "billing_status_plan_deleted", "Plan deleted.")
}

func (a *App) savePaymentProviderFromForm(r *http.Request) string {
	provider := hostingandsupport.PaymentProvider{
		Provider:     r.FormValue("provider"),
		Enabled:      r.FormValue("enabled") == "1",
		DisplayName:  r.FormValue("display_name"),
		PaymentURL:   r.FormValue("payment_url"),
		Instructions: r.FormValue("instructions"),
	}
	if err := a.withServerControlDatabaseWrite(r.Context(), "save-payment-provider", func(database *sql.DB) error {
		return (hostingandsupport.Store{DB: database}).SavePaymentProvider(r.Context(), provider)
	}); err != nil {
		return err.Error()
	}
	a.logHostingSupportEvent(r.Context(), "payment_provider_changed", "saved", "", "", provider.Provider)
	a.reportHostingSnapshotAsync(r.Context())
	return "Платёжный провайдер сохранён."
}

func (a *App) createInvoiceFromForm(r *http.Request) string {
	customerEmail := strings.TrimSpace(r.FormValue("customer_email"))
	if _, err := stdmail.ParseAddress(customerEmail); err != nil {
		return "Email клиента некорректен."
	}
	invoice := hostingandsupport.Invoice{
		CustomerEmail:   customerEmail,
		Domain:          normalizeQuotaDomainName(r.FormValue("domain")),
		PlanName:        strings.TrimSpace(r.FormValue("plan_name")),
		Amount:          strings.TrimSpace(r.FormValue("amount")),
		Currency:        strings.TrimSpace(r.FormValue("currency")),
		Provider:        strings.TrimSpace(r.FormValue("provider")),
		DueAt:           strings.TrimSpace(r.FormValue("due_at")),
		Notes:           strings.TrimSpace(r.FormValue("notes")),
		Recurring:       r.FormValue("recurring_enabled") == "1",
		RecurringPeriod: strings.TrimSpace(r.FormValue("recurring_period")),
	}
	if invoice.Provider == "" {
		invoice.Provider = "sitebrush_com"
	}
	var createdInvoice hostingandsupport.Invoice
	err := a.withServerControlDatabaseWrite(r.Context(), "create-invoice", func(database *sql.DB) error {
		store := hostingandsupport.Store{DB: database}
		if store.IsDemoDomain(r.Context(), invoice.Domain) {
			return errors.New(translationOrDefault(translationsForRequest(r), "billing_demo_billing_blocked", "Demo sites do not participate in billing."))
		}
		invoice.ServerCostMinor = hostingandsupport.MoneyMinor(strings.ReplaceAll(invoice.Amount, ",", "."))
		if invoice.ServerCostMinor > 0 && (invoice.Provider == "stripe" || invoice.Provider == "sitebrush_com") {
			invoice.CommissionBPS = store.SitebrushCommissionBPS(r.Context())
			invoice.PaymentFeeMinor = expenses.PaymentCommissionMinor(invoice.ServerCostMinor, invoice.CommissionBPS)
			invoice.AmountMinor = invoice.ServerCostMinor + invoice.PaymentFeeMinor
			invoice.Amount = hostingandsupport.MoneyAmount(invoice.AmountMinor)
		}
		if invoice.PlanName == "" {
			invoice.PlanName = "Доля расходов сервера"
		}
		var createErr error
		createdInvoice, createErr = store.CreateInvoice(r.Context(), invoice)
		return createErr
	})
	if err != nil {
		return err.Error()
	}
	a.logHostingSupportEvent(r.Context(), "invoice", "issued", createdInvoice.CustomerEmail, createdInvoice.Domain, createdInvoice.Number+" "+createdInvoice.Amount+" "+createdInvoice.Currency)
	a.reportHostingSnapshotAsync(r.Context())
	return "Счёт " + createdInvoice.Number + " выставлен."
}

func (a *App) updateInvoiceStatusFromForm(r *http.Request, status string) string {
	invoiceID, _ := strconv.Atoi(strings.TrimSpace(r.FormValue("invoice_id")))
	var invoice hostingandsupport.Invoice
	err := a.withServerControlDatabaseWrite(r.Context(), "update-invoice-status", func(database *sql.DB) error {
		var updateErr error
		invoice, updateErr = (hostingandsupport.Store{DB: database}).UpdateInvoiceStatus(r.Context(), invoiceID, status)
		return updateErr
	})
	if err != nil {
		return err.Error()
	}
	eventKind := "billing_event"
	if status == "paid" {
		eventKind = "payment"
	} else if status == "payment_error" {
		eventKind = "payment_error"
	}
	a.logHostingSupportEvent(r.Context(), eventKind, status, invoice.CustomerEmail, invoice.Domain, invoice.Number+" "+invoice.Provider)
	a.reportHostingSnapshotAsync(r.Context())
	return "Статус счёта " + invoice.Number + " обновлён."
}

func (a *App) applyLatestActiveRevision(ctx context.Context, domain string, pagePath string) {
	var latestActiveHTML string
	err := a.db.QueryRowContext(ctx, `SELECT html FROM revisions WHERE domain=? AND page_path=? AND is_active=1 ORDER BY id DESC LIMIT 1`, domain, pagePath).Scan(&latestActiveHTML)
	if err != nil {
		a.removeManagedPage(ctx, domain, pagePath)
		return
	}
	pageTitle := pagePath
	_ = a.db.QueryRowContext(ctx, `SELECT title FROM pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&pageTitle)
	newHTMLBytes := int64(len([]byte(latestActiveHTML)))
	var previousStoredHTML string
	_ = a.db.QueryRowContext(ctx, `SELECT html FROM pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&previousStoredHTML)
	pageDelta := newHTMLBytes - int64(len([]byte(previousStoredHTML)))
	publishedPageDelta := int64(0)
	publishedStaticDelta := int64(0)
	if !a.isDomainFrozen(ctx, domain) {
		var previousPublishedHTML string
		_ = a.db.QueryRowContext(ctx, `SELECT html FROM published_pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&previousPublishedHTML)
		publishedPageDelta = newHTMLBytes - int64(len([]byte(previousPublishedHTML)))
		publishedStaticDelta = newHTMLBytes - a.fileSizeInsideStorage(filepath.Join(a.domainStaticDir(domain), staticRelativePathForPage(pagePath)))
	}
	if storageErr := a.applyDomainStorageDelta(ctx, domain, pageDelta, publishedPageDelta, 0, 0, publishedStaticDelta); storageErr != nil {
		log.Printf("restore blocked by storage limit domain=%s path=%s error=%s",
			diagnosticlog.SafeLogValue(domain), diagnosticlog.SafeLogValue(pagePath), diagnosticlog.SafeLogValue(storageErr.Error()))
		return
	}
	a.clearPageRedirectSource(ctx, domain, pagePath)
	_, _ = a.db.ExecContext(ctx, `INSERT OR REPLACE INTO pages(domain,path,title,html,published) VALUES(?,?,?,?,1)`, domain, pagePath, pageTitle, latestActiveHTML)
	if !a.isDomainFrozen(ctx, domain) {
		_, _ = a.db.ExecContext(ctx, `INSERT OR REPLACE INTO published_pages(domain,path,title,html) VALUES(?,?,?,?)`, domain, pagePath, pageTitle, latestActiveHTML)
		a.writePublishedStaticHTML(domain, pagePath, latestActiveHTML)
	}
}

func (a *App) removeManagedPage(ctx context.Context, domain string, pagePath string) {
	var storedHTML string
	_ = a.db.QueryRowContext(ctx, `SELECT html FROM pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&storedHTML)
	var publishedHTML string
	_ = a.db.QueryRowContext(ctx, `SELECT html FROM published_pages WHERE domain=? AND path=?`, domain, pagePath).Scan(&publishedHTML)
	publishedStaticBytes := a.fileSizeInsideStorage(filepath.Join(a.domainStaticDir(domain), staticRelativePathForPage(pagePath)))
	_ = a.applyDomainStorageDelta(ctx, domain, -int64(len([]byte(storedHTML))), -int64(len([]byte(publishedHTML))), 0, 0, -publishedStaticBytes)
	_, _ = a.db.ExecContext(ctx, `DELETE FROM pages WHERE domain=? AND path=?`, domain, pagePath)
	_, _ = a.db.ExecContext(ctx, `DELETE FROM published_pages WHERE domain=? AND path=?`, domain, pagePath)
	a.removePublishedStaticFile(domain, pagePath)
}

func (a *App) previewRevision(w http.ResponseWriter, r *http.Request) {
	if !a.canEditPages(r) || r.Method != http.MethodGet {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	revisionID, _ := strconv.Atoi(r.URL.Query().Get("id"))
	if revisionID <= 0 {
		http.Error(w, "revision not found", http.StatusNotFound)
		return
	}
	domain := a.siteDomain(r.Context(), r)
	var revisionHTML string
	err := a.db.QueryRowContext(r.Context(), `SELECT html FROM revisions WHERE id=? AND domain=?`, revisionID, domain).Scan(&revisionHTML)
	if err != nil {
		http.Error(w, "revision not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(revisionHTML))
}

func (a *App) restoreRevision(w http.ResponseWriter, r *http.Request) {
	if !a.isAdminRequest(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	revisionID, _ := strconv.Atoi(r.FormValue("id"))
	var pagePath, html string
	domain := a.siteDomain(r.Context(), r)
	err := a.db.QueryRowContext(r.Context(), `SELECT page_path,html FROM revisions WHERE id=? AND domain=?`, revisionID, domain).Scan(&pagePath, &html)
	if err != nil {
		http.Error(w, "revision not found", http.StatusNotFound)
		return
	}
	if storageErr := a.applyDomainStorageDelta(r.Context(), domain, 0, 0, int64(len([]byte(html))), 0, 0); storageErr != nil {
		http.Error(w, storageErr.Error(), http.StatusInsufficientStorage)
		return
	}
	_, _ = a.db.ExecContext(r.Context(), `UPDATE pages SET html=? WHERE domain=? AND path=?`, html, domain, pagePath)
	_, _ = a.db.ExecContext(r.Context(), `INSERT INTO revisions(domain,page_path,html,created_at) VALUES(?,?,?,?)`, domain, pagePath, html, time.Now().Format(time.RFC3339))
	a.applyLatestActiveRevision(r.Context(), domain, pagePath)
	httpsecurity.RedirectLocal(w, r, pagePath, http.StatusFound)
}

func (a *App) deleteRevision(w http.ResponseWriter, r *http.Request) {
	if !a.isAdminRequest(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	revisionID, _ := strconv.Atoi(r.FormValue("id"))
	pagePath := r.FormValue("path")
	domain := a.siteDomain(r.Context(), r)
	_, _ = a.db.ExecContext(r.Context(), `UPDATE revisions SET is_active=0 WHERE id=? AND domain=?`, revisionID, domain)
	a.applyLatestActiveRevision(r.Context(), domain, pagePath)
	httpsecurity.RedirectLocal(w, r, pagePath+"?revisions", http.StatusFound)
}

func (a *App) deleteRevisionByQuery(w http.ResponseWriter, r *http.Request) {
	if !a.isAdminRequest(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	revisionID, _ := strconv.Atoi(strings.TrimSpace(r.URL.Query().Get("delete")))
	if revisionID <= 0 {
		http.Error(w, "revision not found", http.StatusNotFound)
		return
	}
	domain := a.siteDomain(r.Context(), r)
	var pagePath string
	err := a.db.QueryRowContext(r.Context(), `SELECT page_path FROM revisions WHERE id=? AND domain=?`, revisionID, domain).Scan(&pagePath)
	if err != nil {
		http.Error(w, "revision not found", http.StatusNotFound)
		return
	}
	_, _ = a.db.ExecContext(r.Context(), `UPDATE revisions SET is_active=0 WHERE id=? AND domain=?`, revisionID, domain)
	a.applyLatestActiveRevision(r.Context(), domain, pagePath)
	httpsecurity.RedirectLocal(w, r, pagePath, http.StatusFound)
}

func (a *App) toggleRevision(w http.ResponseWriter, r *http.Request) {
	if !a.isAdminRequest(r) || r.Method != http.MethodPost {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	revisionID, _ := strconv.Atoi(r.FormValue("id"))
	pagePath := r.FormValue("path")
	domain := a.siteDomain(r.Context(), r)
	enableRevision := r.FormValue("enable") == "1"
	nextActiveState := 0
	if enableRevision {
		nextActiveState = 1
	}
	_, _ = a.db.ExecContext(r.Context(), `UPDATE revisions SET is_active=? WHERE id=? AND domain=?`, nextActiveState, revisionID, domain)
	a.applyLatestActiveRevision(r.Context(), domain, pagePath)
	httpsecurity.RedirectLocal(w, r, pagePath+"?revisions", http.StatusFound)
}

func (a *App) profilePage(w http.ResponseWriter, r *http.Request) {
	if !a.isAdminRequest(r) {
		if !a.hasAdmin(r.Context(), a.siteDomain(r.Context(), r)) {
			httpsecurity.RedirectLocal(w, r, r.URL.Path+"?register", http.StatusFound)
			return
		}
		httpsecurity.RedirectLocal(w, r, loginURLForRequest(r), http.StatusFound)
		return
	}
	currentEmail, found := a.currentAdminEmail(r)
	if !found {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	translations := translationsForRequest(r)
	status := ""
	statusClass := ""
	showPasswordCodeForm := false
	passwordConfirmationToken := ""
	pendingProfileEmail := currentEmail
	emailDeliveryView := profileEmailDeliveryView{}
	if r.Method == http.MethodPost {
		passwordConfirmationToken = strings.TrimSpace(r.FormValue("profile_confirmation_token"))
		if passwordConfirmationToken == "" {
			passwordConfirmationToken = strings.TrimSpace(r.FormValue("password_confirmation_token"))
		}
		passwordConfirmationCode := strings.TrimSpace(r.FormValue("profile_confirmation_code"))
		if passwordConfirmationCode == "" {
			passwordConfirmationCode = strings.TrimSpace(r.FormValue("password_confirmation_code"))
		}
		profileAction := strings.TrimSpace(r.FormValue("profile_action"))
		nextEmail := strings.TrimSpace(r.FormValue("email"))
		nextPassword := strings.TrimSpace(r.FormValue("password"))
		confirmPassword := strings.TrimSpace(r.FormValue("password_confirm"))
		if passwordConfirmationToken != "" || passwordConfirmationCode != "" {
			a.handleProfilePasswordCode(w, r, currentEmail, passwordConfirmationToken, passwordConfirmationCode)
			return
		}
		domain := a.siteDomain(r.Context(), r)
		if profileAction == "" {
			if nextPassword != "" && nextEmail != "" && nextEmail != currentEmail {
				profileAction = "both"
			} else if nextPassword != "" {
				profileAction = "password"
			} else if nextEmail != "" && nextEmail != currentEmail {
				profileAction = "email"
			}
		}
		switch {
		case profileAction == "email" && nextEmail == "":
			status = translationOrDefault(translations, "profile_status_email_required", "Email is required.")
			statusClass = "warning"
		case profileAction == "email" && nextEmail == currentEmail:
			status = translationOrDefault(translations, "profile_status_updated", "Account updated.")
			statusClass = "success"
		case (profileAction == "password" || profileAction == "both") && nextPassword == "":
			status = translationOrDefault(translations, "profile_status_password_required", "Password is required.")
			statusClass = "warning"
		case (profileAction == "password" || profileAction == "both") && nextPassword != confirmPassword:
			status = translationOrDefault(translations, "profile_status_password_mismatch", "Password confirmation does not match.")
			statusClass = "warning"
		case profileAction != "email" && profileAction != "password" && profileAction != "both":
			status = translationOrDefault(translations, "profile_status_unknown_action", "Choose what to update.")
			statusClass = "warning"
		default:
			if profileAction == "email" || profileAction == "both" {
				var existingCount int
				_ = a.db.QueryRowContext(r.Context(), `SELECT COUNT(1) FROM users WHERE domain=? AND email=?`, domain, nextEmail).Scan(&existingCount)
				if existingCount > 0 {
					status = translationOrDefault(translations, "email_confirmation_status_email_exists", "This email address is already used.")
					statusClass = "danger"
					break
				}
			}
			codeEmail := ""
			codePassword := ""
			codeKind := "password_change_code"
			if profileAction == "email" || profileAction == "both" {
				codeEmail = nextEmail
				codeKind = "email_change"
			}
			if profileAction == "password" || profileAction == "both" {
				codePassword = nextPassword
			}
			token, deliveryResult, dnsHelp, err := a.createAndSendProfileCode(r, domain, currentEmail, codeEmail, codePassword, codeKind)
			if err != nil {
				statusClass = "danger"
				emailDeliveryView = profileEmailDeliveryViewForResult(translations, deliveryResult, dnsHelp)
				if emailDeliveryView.Show {
					status = translationOrDefault(translations, "profile_password_code_status_not_sent", "Email was not sent.")
				} else {
					status = err.Error()
				}
				break
			}
			a.clearFailedLoginAttempts(r.Context(), profilePasswordFailureDomain(domain, currentEmail), clientIPAddress(r))
			status = translationOrDefault(translations, "profile_password_code_status_sent", "The code email was sent and accepted by the recipient mail server.")
			statusClass = "success"
			emailDeliveryView = profileEmailDeliveryViewForResult(translations, deliveryResult, profileEmailDeliveryDNSHelp{})
			showPasswordCodeForm = true
			passwordConfirmationToken = token
			if profileAction == "email" {
				pendingProfileEmail = nextEmail
			}
		}
	}
	a.renderProfilePage(w, r, pendingProfileEmail, status, statusClass, showPasswordCodeForm, passwordConfirmationToken, time.Time{}, false, emailDeliveryView)
}

